/*
 * The teaching layer: what each module is for, and how to teach it.
 *
 * Generated by merge-teaching.js from four band drafts. Edit the drafts and
 * re-run rather than editing this file, or the next merge silently reverts you.
 *
 *
 * What is in here, and why it could not be derived.
 *
 * The course already knew what each module *contains*. It did not know what a
 * student should be able to *do* afterwards, and that is not the same thing —
 * "the lessons about ordering coffee" and "I can order a coffee and change the
 * order when it arrives wrong" are a syllabus entry and a learning objective,
 * and only one of them can be assessed.
 *
 * The workbook has been printing a heading that said "By the end of this
 * module I can..." since long before this file existed, and filling it with
 * the first sentence of each lesson's scene description. That produced lines
 * like "A neighbor stops you by the mailboxes" under a can-do heading: a
 * setting, not a capability, and not a claim anyone could check. This file is
 * what that heading was always promising.
 *
 *
 * The one rule that governs every string here.
 *
 * `.en` is read by the English speaker studying Spanish, and by their teacher.
 * `.es` is read by the Spanish speaker studying English, and by their teacher.
 * They are two different classes learning two different languages, so the two
 * sides of a teaching note are NOT translations of each other:
 *
 *     presentation.en -> "Put soy, es, somos, son on the board."
 *     presentation.es -> "Escribe am, is y are en el tablero."
 *
 * Translating one into the other puts Spanish conjugations in front of the
 * class that came to learn English. That mistake passes every language test in
 * this repo, because those tests check which language a string is written in
 * and never which language it is about.
 *
 * `mission` and `canDo` are the exception and *are* translation pairs: the
 * task is the same in both classrooms, only the target language differs.
 */
const MODULE_TEACHING = {
  "00-core": {
    mission: { en: "Use eight survival scenes to enter a Colombian day, greet people, ask simply, and leave each exchange with dignity.", es: "Usar ocho escenas de supervivencia para entrar en un día en inglés, saludar, pedir de forma simple y cerrar con dignidad." },
    canDo: [
      { en: "Order coffee and fruit with the local courtesy words", es: "Pedir café y fruta con palabras corteses del inglés cotidiano" },
      { en: "Ask for taxis, prices, symptoms, work updates, and plans", es: "Preguntar por taxis, precios, síntomas, avances de trabajo y planes" },
      { en: "Recognize when a scene is casual, courteous, or formal", es: "Reconocer cuándo una escena es casual, cortés o formal" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Stand at the door as the tienda owner and greet each student with Buenas. Let them answer with any polite word they already own. Keep the coffee request hidden until the room has felt like a transaction, not a grammar chart.", es: "Párate en la puerta como barista y saluda con Hi. Deja que respondan con cualquier palabra amable que ya tengan. Mantén Could I have a black coffee? oculto hasta que la escena se sienta como compra real, no lista." },
      presentation: { en: "Put the whole request ¿Me regalas un tinto? on one strip and have the class say it as a single breath. Do not analyze regalar yet; attach the strip to a cup, then contrast it with ¿Cuánto me cobra? at the taxi door.", es: "Pon Could I have a black coffee? en una tira completa y haz que la clase la diga como un solo bloque. No analices could todavía; pégala al vaso y contrástala con Could you take me downtown? en la puerta del taxi." },
      practice: { en: "Run four shop and taxi slips. Students choose between ¿Me regalas un tinto? and ¿Cuánto me cobra? after seeing only the object or destination. Add Regáleme una libra when the picture changes to fruit, so the drill follows the day instead of a list.", es: "Haz cuatro tarjetas de café y taxi. El grupo escoge entre Could I have a black coffee? y Could you take me downtown? viendo solo objeto o destino. Agrega How much are the mangoes? cuando la imagen pase a fruta, para que la práctica siga el día." },
      production: { en: "Set three corners as tienda, taxi, and market. Give each pair one coin problem or destination card. They complete two exchanges, then choose whether ¿Me regalas...? or Regáleme... fits the person in front of them.", es: "Marca tres esquinas: café, taxi y mercado. Da a cada pareja un problema de monedas o destino. Hacen dos intercambios y deciden si Could I have...? o How much are...? encaja con la persona que tienen delante." },
      exitTicket: { en: "At the door, hand over a cup card. The learner must request it cold with ¿Me regalas un tinto? and no written prompt. You are checking fluency of the transaction.", es: "En la salida, entrega una tarjeta de vaso. Cada estudiante pide sin modelo con Could I have a black coffee?; revisas fluidez de compra, no explicación gramatical." },
      homework: { en: "Practice the tinto request as rehearsal, not writing practice. Say ¿Me regalas un tinto? ten times while holding a cup, then use it once in a real or pretend shop and note the answer.", es: "Practican la petición de café como ensayo oral. Dicen Could I have a black coffee? diez veces con un vaso, luego la usan en una cafetería real o fingida y anotan la respuesta." },
      support: { en: "For a lost beginner, cover every scene except the tienda. Give the first words ¿Me... and two endings, regalas and cobra. Once the request works, uncover the taxi and show why cobra belongs there.", es: "Con quien está perdido, tapa todo salvo el café. Da el inicio Could I... y dos finales, have y take. Cuando el pedido salga, destapa el taxi y muestra por qué take pertenece allí." },
      stretch: { en: "Challenge quick pairs to run the coffee order with a distracted shopkeeper who answers only with price or gesture. They keep ¿Me regalas un tinto? whole and add ¿Cuánto me cobra? only after the cup changes hands.", es: "Reta a parejas rápidas a atender un barista distraído que responde solo con precio o gesto. Mantienen Could I have a black coffee? completo y añaden How much is it? después de recibir el vaso." },
      errors: [
        { en: "They say \"¿Puedo tener un tinto?\", copying English in daily survival exchanges. Stop it with \"¿Me regalas un tinto?\" because tener is possession, not the Colombian shop request. Put the repair above ¿Puedo tener un tinto?, cross out the false words, and restart the corner shop.", es: "Dicen \"I want a coffee\" porque traducen desde el español en intercambios diarios de supervivencia. Cámbialo por \"Could I have a black coffee?\" y repasa Could I have a black coffee?, porque I want suena a exigencia en el mostrador. Pon la reparación sobre I want a coffee, tacha las palabras falsas y reinicia el mostrador de café." },
        { en: "Expect \"Ya te lo traigo means I already brought it\" when pressure rises in daily survival exchanges. The repair is \"Ya te lo traigo means I will bring it right over\" because ya often points to immediate action. Students repeat it with one new daily survival exchanges detail so it is not just copying.", es: "Espera \"How much costs?\" cuando sube la presión en intercambios diarios de supervivencia. La reparación es \"How much are the mangoes?\", porque la pregunta necesita are antes del objeto plural. Repiten la línea con un detalle nuevo de intercambios diarios de supervivencia para que no sea copia." }
      ]
    }
  },
  "01-foundation-identity": {
    mission: { en: "Introduce yourself in a new building, say what is fixed about you, and separate identity from a temporary state.", es: "Presentarte en un edificio nuevo, decir lo que te define y separar identidad de un estado temporal." },
    canDo: [
      { en: "Say your name, apartment, origin, and job politely", es: "Decir nombre, apartamento, origen y trabajo con cortesía" },
      { en: "Confirm that someone has identified you correctly", es: "Confirmar que otra persona te identificó correctamente" },
      { en: "Choose identity language instead of temporary-state language", es: "Escoger lenguaje de identidad y no de estado temporal" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Write Alex, 502, dog, teacher on four cards and ask what a neighbor can know in ten seconds. Students sort facts from moods before seeing Soy and Estoy. The aim is to make identity visible first.", es: "Escribe Alex, 502, dog y teacher en tarjetas y pregunta qué sabe un vecino en diez segundos. Ordenan datos y estados antes de ver inglés; la meta es preparar I am sin explicar gramática." },
      presentation: { en: "Draw two columns with the same subject: yo. In the left column write Soy profesor and Soy estadounidense; in the right write Estoy sin trabajo fijo. Ask which column can change this month, then add ¿A qué se dedica? above the job column.", es: "Dibuja dos columnas con el mismo sujeto, I. Escribe I am a teacher y I am from 502 junto a It's ready. Pregunta cuál describe una persona y cuál una cosa lista; después añade What do you do? sobre el oficio." },
      practice: { en: "Give apartment cards with name, floor, nationality, and job. Students build Soy Alex, soy estadounidense, and ¿A qué se dedica? from the cards, then decide where estoy sin trabajo fijo belongs. Keep the juice-counter ready line for the final contrast.", es: "Da tarjetas con nombre, piso, nacionalidad y oficio. Construyen I am Alex, I am Colombian, y What do you do? con esas tarjetas; luego deciden dónde va ready. Deja that's me para responder cuando alguien identifique al vecino." },
      production: { en: "Hold a two-minute residents meeting. One chairperson asks ¿Usted quién es? and ¿A qué se dedica?; the new neighbor answers and reacts with ese soy yo when named by the dog or apartment.", es: "Haz una reunión breve del edificio. Una persona pregunta Who are you? y What do you do?; la vecina nueva responde y usa that's me cuando la identifican por el perro o el apartamento." },
      exitTicket: { en: "Ask for two lines: one with Soy for a stable fact and one with Estoy for today. If a learner writes Soy cansado, keep that card for tomorrow.", es: "Pide dos líneas: una con I am para oficio u origen y otra con ready para estado de cosa. Si falta el sujeto, guarda esa tarjeta para repaso." },
      homework: { en: "Sort ten tiny cards into two piles: Soy for identity and Estoy for today's condition. Do not write new sentences yet; bring back the two cards that felt hardest to place.", es: "Clasifican diez tarjetas pequeñas en dos grupos: I am para identidad y ready o not ready para estado del día. No escriben frases nuevas; traen las dos tarjetas más difíciles." },
      support: { en: "The hard point is the ser and estar split. Freeze the subject as yo and give only two choices: Soy profesor or Estoy sin trabajo fijo. Let the student sort permanent identity before adding apartment details.", es: "Lo difícil es no soltar sujeto ni artículo. Fija la frase I am ___ y ofrece teacher, from 502 y ready. El estudiante completa una sola línea antes de volver a la reunión." },
      stretch: { en: "Ask early finishers to invent one more resident card with job, apartment, and one temporary problem. Their partner must choose Soy for the card identity and Estoy only for today's problem.", es: "Pide a quienes terminan pronto crear otra tarjeta de residente con oficio, apartamento y un problema temporal. Su pareja usa I am para identidad y ready o not ready solo para el estado del día." },
      errors: [
        { en: "They say \"Estoy profesor\", copying English in identity and state. Stop it with \"Soy profesor\" because the job is identity, while estoy sin trabajo fijo is temporary. Put the repair above Estoy profesor, cross out the false words, and restart building meeting.", es: "Dicen \"Am teacher\" porque traducen desde el español en identidad y estado. Cámbialo por \"I am a teacher\" y repasa I am a teacher, porque el inglés exige sujeto y artículo antes del oficio. Pon la reparación sobre Am teacher, tacha las palabras falsas y reinicia reunión del edificio." },
        { en: "Expect \"Yo soy ese\" when pressure rises in identity and state. The repair is \"Ese soy yo\" because Spanish accepts an identity someone else offered with that order. Students repeat it with one new identity and state detail so it is not just copying.", es: "Espera \"ready means inteligente\" cuando sube la presión en identidad y estado. La reparación es \"It’s ready\", porque ready describe estado, no profesión ni inteligencia. Repiten la línea con un detalle nuevo de identidad y estado para que no sea copia." }
      ]
    }
  },
  "02-foundation-state": {
    mission: { en: "Handle a small problem day: locate a person, explain what you have, and make a simple plan in the heat.", es: "Manejar un día con problemas pequeños: ubicar a alguien, decir qué tienes y hacer un plan sencillo con calor." },
    canDo: [
      { en: "Ask where someone is and understand an arrival update", es: "Preguntar dónde está alguien y entender que ya llega" },
      { en: "Say what you have, lack, and have to do", es: "Decir qué tienes, qué te falta y qué debes hacer" },
      { en: "Talk about weather, errands, and making food together", es: "Hablar del clima, vueltas y comida que se prepara en grupo" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Show a phone with three missed calls, a large bill, and a noon sun. Students point to location, money, or heat. Do not correct language yet; you are locating which problem they can already recognize.", es: "Muestra un celular con llamadas perdidas, un billete grande y sol de mediodía. Señalan location, money o heat. No corrijas todavía; ubicas qué problema reconocen antes de Whereabouts are you?" },
      presentation: { en: "Act out the technician call from across the room. Write ¿por dónde está? only after students see you looking for a person, then answer with Estoy llegando from the doorway. Add tengo que later with the shop errand, not in the same breath.", es: "Representa la llamada al técnico desde el otro lado del salón. Escribe Whereabouts are you? cuando vean que buscas a alguien; contesta I'm around the corner desde la puerta. Deja I have to para la tienda." },
      practice: { en: "Put a phone, a bill, and a sun card on three desks. Students ask ¿por dónde está? only at the phone, use tengo que with the bill errand, and save hace calor for the sidewalk. Move bodies, not lists.", es: "Pon teléfono, billete y sol en tres mesas. Usan Whereabouts are you? solo con el teléfono, I have to en el mandado, e I'm in a rush cuando aparece la tienda. El movimiento evita mezclar funciones." },
      production: { en: "One student is the late technician, one is Don Norbey, one is the neighbor planning sancocho. The visitor must solve the day with estoy llegando, tengo afán, and hacer una vuelta in the right places.", es: "Un estudiante es técnico atrasado, otro tendero, otro vecino del guiso. La persona que visita resuelve el día con I'm around the corner, I'm in a rush y run errands donde correspondan." },
      exitTicket: { en: "Point to the phone card. Each learner writes the technician question or the arrival answer. Accept only ¿por dónde está? or estoy llegando, because that is today's location check.", es: "Señala la tarjeta del teléfono. Cada estudiante escribe Whereabouts are you? o I'm around the corner. Acepta solo esa pregunta o respuesta; hoy revisas ubicación." },
      homework: { en: "Copy one technician line, one shop line, and one sancocho line. Change only the time or person, then underline estoy llegando, tengo que, or hace calor according to the scene.", es: "Copian una línea de llamada, una de tienda y una de plan de comida. Cambian solo hora o persona, y subrayan Whereabouts are you?, I have to o I'm in a rush según la escena." },
      support: { en: "Separate body, obligation, and weather with icons. Point to the body for tengo calor, the clock for tengo que, and the sky for hace calor. Do not ask for a full dialogue yet.", es: "Separa ubicación, obligación y prisa con dibujos. Señala mapa para Whereabouts are you?, reloj para I have to y fila para I'm in a rush. No pidas diálogo completo todavía." },
      stretch: { en: "Let strong students turn the phone call into a three-stop errand. They must use ¿por dónde está? before moving, tengo que at the shop, and hace calor only once outside.", es: "Deja que estudiantes fuertes conviertan la llamada en tres mandados. Usan Whereabouts are you? antes de moverse, I have to en la tienda y I'm in a rush solo cuando hay fila." },
      errors: [
        { en: "They say \"Estoy caliente\", copying English in state, possession, and plans. Stop it with \"Tengo calor\" because body heat uses tener, while weather uses hace calor. Put the repair above Estoy caliente, cross out the false words, and restart the technician call.", es: "Dicen \"I have rush\" porque traducen desde el español en estado, posesión y planes. Cámbialo por \"I’m in a rush\" y repasa Whereabouts are you?, porque rush no se posee en esta frase. Pon la reparación sobre I have rush, tacha las palabras falsas y reinicia llamada al técnico." },
        { en: "Expect \"Tengo a recoger\" when pressure rises in state, possession, and plans. The repair is \"Tengo que recoger\" because tener que needs the infinitive after que. Students repeat it with one new state, possession, and plans detail so it is not just copying.", es: "Espera \"make errands\" cuando sube la presión en estado, posesión y planes. La reparación es \"run errands\", porque hacer una vuelta se vuelve run errands. Repiten la línea con un detalle nuevo de estado, posesión y planes para que no sea copia." }
      ]
    }
  },
  "03-foundation-ability": {
    mission: { en: "Ask for help, pass along what neighbors said, and accept an invitation without losing the thread.", es: "Pedir ayuda, contar lo que dijeron los vecinos y aceptar una invitación sin perder el hilo." },
    canDo: [
      { en: "Request a practical favor from a building worker", es: "Pedir un favor práctico a alguien del edificio" },
      { en: "Report a rumor without making it sound certain", es: "Contar un rumor sin presentarlo como seguro" },
      { en: "Understand an invitation to come over and bring something", es: "Entender una invitación para ir a una casa y llevar algo" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Bring in a heavy bag and silently fail to lift it. Let students offer gestures or English words for help. The awkwardness sets up why a porter request needs courtesy before Spanish appears.", es: "Trae una bolsa pesada y falla al levantarla. Deja que ofrezcan gestos o palabras en español para ayudar. Esa incomodidad prepara por qué can/could cambia el tono." },
      presentation: { en: "Write Ayúdame on the board and cross it out for the porter. Next to it write ¿me puede colaborar? and mark puede as the polite hinge. Students decide which line belongs to Don Jairo before you mention ability.", es: "Escribe Help me en el tablero y ponlo como demasiado directo para el encargado. Al lado escribe Could you give me a hand? y marca could como bisagra cortés. Deciden qué frase usaría una persona educada." },
      practice: { en: "Start at the gas cylinder. Students choose ¿me puede colaborar? for a favor, then move to the hallway rumor and change only the source: dicen or me dijeron que. Keep venga out until the invitation card appears.", es: "Empieza con el cilindro de gas. Escogen Could you give me a hand? para el favor; luego pasan al rumor y cambian solo la fuente: They told me o Apparently. No uses come over hasta la invitación." },
      production: { en: "Make a hallway chain. The porter helps with gas, a neighbor passes water news, and Memo invites someone over. Each student must decide whether poder, decir, or venir carries the turn before speaking.", es: "Arma una cadena de pasillo. El encargado ayuda, una vecina cuenta el corte, y Memo invita a cenar. Cada estudiante decide si usa can, told me o come over antes de hablar." },
      exitTicket: { en: "Hold up the gas cylinder picture. Learners write one polite request to Don Jairo. If they choose ayúdame or Help me, the register did not land.", es: "Levanta el dibujo del gas. Escriben una petición cortés con Could you give me a hand? Si aparece Help me solo, la cortesía no quedó." },
      homework: { en: "At home, choose one small favor someone could ask a porter for. Write it first too direct, then repair it with ¿me puede colaborar? and circle puede as the politeness hinge.", es: "En casa, escogen un favor pequeño para pedir en portería. Lo escriben primero demasiado directo con Help me, luego lo reparan con Could you give me a hand? y encierran could." },
      support: { en: "If a student freezes, return to the favor. Give ¿me puede...? plus colaborar on a separate tile. The concrete need makes poder useful before the rumor language adds uncertainty.", es: "Si alguien se bloquea, vuelve al favor. Da Could you...? y give me a hand en tarjetas separadas. La necesidad concreta hace útil can antes de sumar la incertidumbre del rumor." },
      stretch: { en: "Send fast finishers to add a rumor after the porter favor. The favor must stay courteous with ¿me puede colaborar?; the water news must sound uncertain with dizque or dicen.", es: "Envía a quienes avanzan rápido a sumar un rumor después del favor. La petición mantiene Could you give me a hand?; la noticia del agua suena incierta con apparently o they told me." },
      errors: [
        { en: "They say \"¿Puedo colaborar?\", copying English in help, reporting, and invitations. Stop it with \"¿Me puede colaborar?\" because Alex needs help from Don Jairo, not permission to help him. Put the repair above ¿Puedo colaborar?, cross out the false words, and restart the porter desk.", es: "Dicen \"They said me\" porque traducen desde el español en ayuda, reporte e invitaciones. Cámbialo por \"They told me\" y repasa can, porque tell necesita persona y say no la lleva así. Pon la reparación sobre They said me, tacha las palabras falsas y reinicia la portería." },
        { en: "Expect \"Dizque van a cortar el agua as fact\" when pressure rises in help, reporting, and invitations. The repair is \"Dizque van a cortar el agua, no sé\" because dizque marks distance from the rumor. Students repeat it with one new help, reporting, and invitations detail so it is not just copying.", es: "Espera \"go to my house\" cuando sube la presión en ayuda, reporte e invitaciones. La reparación es \"come over\", porque la invitación se dice desde la casa del anfitrión. Repiten la línea con un detalle nuevo de ayuda, reporte e invitaciones para que no sea copia." }
      ]
    }
  },
  "04-foundation-perception": {
    mission: { en: "Talk through what you see, keep valuables out of sight, and identify a new taste at a market stall.", es: "Hablar de lo que ves, guardar objetos valiosos y reconocer un sabor nuevo en un puesto de mercado." },
    canDo: [
      { en: "Comment on a game using basic seeing language", es: "Comentar un partido con lenguaje básico de percepción" },
      { en: "Understand a warning about showing your phone downtown", es: "Entender una advertencia sobre mostrar el celular en el centro" },
      { en: "Say what an unfamiliar fruit tastes like", es: "Decir a qué sabe una fruta desconocida" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Flash three images for two seconds each: a goal, a phone in the street, and a cut curuba. Students say see, danger, or taste with gestures only. The speed keeps the focus on perception.", es: "Muestra tres imágenes dos segundos: partido, celular en la calle y curuba abierta. Responden con gestos de see, danger o taste. La velocidad prepara percepción sin producir todavía." },
      presentation: { en: "Use your eyes and finger. For ver, stare at the match result already on the board; for mirar, point deliberately at one detail; for sabe a, taste imaginary juice. Put only those three labels under the actions.", es: "Usa ojos y dedo. Para look at, señala un detalle del cuadro; para watch, mira una jugada; para tastes like, prueba jugo imaginario. Escribe cada etiqueta bajo la acción, no en una lista." },
      practice: { en: "Show a match photo, a phone on the street, and a sliced curuba. Students choose vi, mire, or sabe a for each card. Add dar papaya only after the phone card creates a real warning.", es: "Muestra partido, celular en la calle y curuba abierta. Escogen look at, watch o tastes like según la tarjeta. Agrega put away solo cuando el celular cree una advertencia real." },
      production: { en: "One pair walks through a mini market after a game. They mention what they saw, receive a phone warning, and guess the fruit. Require sabe a in the last turn, not earlier.", es: "Una pareja pasa por un mercado después del partido. Dice qué vio, recibe advertencia por el teléfono y prueba la fruta. Exige tastes like en el último turno, no antes." },
      exitTicket: { en: "Show the curuba card. Each learner completes La curuba sabe a ___. You are checking the tiny a after taste, not their opinion of the fruit.", es: "Muestra la curuba. Cada estudiante completa It tastes like ___. Revisas la frase de sabor, no si de verdad conocen la fruta." },
      homework: { en: "For three days, write one short Spanish noticing line: something you saw, something you deliberately looked at, and one taste. Mark ver, mirar, or sabe a beside the real moment.", es: "Durante tres días escriben una línea breve en inglés: algo que saw, algo que watched o looked at, y un sabor con tastes like. Marcan cuál fue observación, atención o prueba." },
      support: { en: "The block is choosing perception verbs. Put an eye icon for ver, a pointing finger for mirar, and a tongue for sabe a. The student answers by pointing before saying the phrase.", es: "El bloqueo está en separar verbos de percepción. Pon ojo para see, pantalla para watch y lengua para tastes like. El estudiante señala primero y luego produce la frase." },
      stretch: { en: "Have confident learners guide a partner through the three cards blindfolded. They use mire for one visible detail, no dé papaya for the phone, and sabe a only after the fruit is tasted.", es: "Haz que estudiantes seguros guíen a una pareja por tres tarjetas sin verlas. Usan look at para un detalle, put it away con el celular y tastes like solo al probar la fruta." },
      errors: [
        { en: "They say \"Miro el partido anoche\", copying English in seeing, warning, and tasting. Stop it with \"Vi el partido anoche\" because the match was perceived in the past, not watched now. Put the repair above Miro el partido anoche, cross out the false words, and restart stairwell match.", es: "Dicen \"listen the game\" porque traducen desde el español en ver, advertir y probar. Cámbialo por \"watch the game\" y repasa look at, porque watch va con partido visto en pantalla o cancha. Pon la reparación sobre listen the game, tacha las palabras falsas y reinicia partido en la escalera." },
        { en: "Expect \"La curuba sabe como mango\" when pressure rises in seeing, warning, and tasting. The repair is \"La curuba sabe a mango\" because taste takes a in Spanish. Students repeat it with one new seeing, warning, and tasting detail so it is not just copying.", es: "Espera \"it knows like banana\" cuando sube la presión en ver, advertir y probar. La reparación es \"it tastes like banana\", porque taste like expresa sabor, no conocimiento. Repiten la línea con un detalle nuevo de ver, advertir y probar para que no sea copia." }
      ]
    }
  },
  "05-foundation-meeting": {
    mission: { en: "Meet a friend of a friend, accept or refuse a coffee kindly, and call ahead when lunch is waiting.", es: "Conocer a una amiga de un amigo, aceptar o rechazar café con amabilidad y avisar cuando llegas tarde." },
    canDo: [
      { en: "Greet a new person and answer the same courtesy back", es: "Saludar a alguien nuevo y devolver la misma cortesía" },
      { en: "Ask what someone wants and offer to pay", es: "Preguntar qué quiere alguien y ofrecer pagar" },
      { en: "Call to say you are almost there but late", es: "Llamar para decir que casi llegas pero vas tarde" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Make a triangle with Santi, Laura, and Alex name cards. Students move the cards to show who knows whom already at the terrace. Keep conocer hidden until they see that one relationship is new.", es: "Haz un triángulo con tarjetas de Santi, Laura y Alex. Mueven las tarjetas para mostrar quién ya conoce a quién. Mantén Nice to meet you oculto hasta que vean la relación nueva." },
      presentation: { en: "Stage the introduction physically. Santi points to Laura; Alex answers Mucho gusto; Laura returns Igualmente. Write conocer above the first handshake only, then put ¿qué querés? on a cup card for the bakery as a different move.", es: "Representa la presentación. Una persona señala a Laura; Alex dice Nice to meet you; Laura responde Likewise. Escribe this is sobre el gesto de presentar y deja I'd like en una tarjeta de café aparte." },
      practice: { en: "Use three role cards: Santi introduces Laura, Manu offers tinto, Doña Marta waits for lunch. Students practice mucho gusto only on the terrace, ¿qué querés? at the bakery, and ya casi llego on the call.", es: "Usa tres roles: presentación, café y llamada antes de comer. Practican Nice to meet you solo al conocer a Laura, I'd like en el mostrador, y I'm running late cuando alguien espera." },
      production: { en: "Stage a terrace where the new person is handed from friend to friend. After two greetings, move the same pair to the bakery and make one student offer to pay with yo invito.", es: "Monta una terraza donde presentan a la persona nueva. Tras dos saludos, mueve la misma pareja al café y haz que una persona pague con It's on me." },
      exitTicket: { en: "Give two name cards that have never met. The learner performs the greeting and reply. Mark only whether mucho gusto or Nice to meet you appears in the first turn.", es: "Da dos tarjetas de personas que no se conocen. Hacen saludo y respuesta. Marca solo si aparece Nice to meet you en el primer turno." },
      homework: { en: "Prepare two name cards for people who have never met. Practice the three-turn exchange aloud: introduction, mucho gusto, igualmente. Add yo invito only on a separate coffee card.", es: "Preparan dos tarjetas de personas que no se conocen. Ensayan en voz alta: this is, Nice to meet you, Likewise. Agregan It's on me solo en una tarjeta aparte de café." },
      support: { en: "For the stuck student, strip the scene to greeting and echo. Write mucho gusto, leave the reply blank, and offer igualmente or yo invito. The wrong option shows why meeting is not buying.", es: "Para quien se pierde, reduce todo a saludo y respuesta. Escribe Nice to meet you, deja la respuesta vacía, y ofrece Likewise o It's on me. La opción falsa separa conocer de invitar." },
      stretch: { en: "Ask a quick group to add a late lunch call after the terrace greeting. They must keep mucho gusto at the first meeting and save ya casi llego for Doña Marta waiting at home.", es: "Pide a un grupo rápido añadir una llamada de retraso después del saludo. Mantienen Nice to meet you al conocer a Laura y guardan I'm almost there para la persona que espera comida." },
      errors: [
        { en: "They say \"Sé a Laura\", copying English in meeting, offering, and arriving. Stop it with \"Conozco a Laura\" because conocer, not saber, is meeting a person. Put the repair above Sé a Laura, cross out the false words, and restart Chapinero terrace.", es: "Dicen \"Much taste\" porque traducen desde el español en conocer, ofrecer y llegar. Cámbialo por \"Nice to meet you\" y repasa nice to meet you, porque mucho gusto no se traduce palabra por palabra. Pon la reparación sobre Much taste, tacha las palabras falsas y reinicia terraza." },
        { en: "Expect \"Yo quiero un tinto\" when pressure rises in meeting, offering, and arriving. The repair is \"¿Qué querés tomar?\" because the bakery scene asks what the other person wants. Students repeat it with one new meeting, offering, and arriving detail so it is not just copying.", es: "Espera \"I am late by bus\" cuando sube la presión en conocer, ofrecer y llegar. La reparación es \"I’m running late\", porque running late es el bloque natural para avisar retraso. Repiten la línea con un detalle nuevo de conocer, ofrecer y llegar para que no sea copia." }
      ]
    }
  },
  "06-foundation-obligation": {
    mission: { en: "Handle a neighborly weekend, a small debt and Sunday lunch duties without freezing when obligation shows up in real time.", es: "Manejar un fin de semana con vecinos, una deuda pequeña y los preparativos del domingo sin bloquearte cuando aparece la obligación." },
    canDo: [
      { en: "Answer a puente invitation and say whether you will drop by", es: "Responder una invitación de puente y decir si vas a pasar" },
      { en: "Settle what you owe and thank someone for trusting you", es: "Pagar lo que debes y agradecer la confianza de alguien" },
      { en: "Offer help and follow house-preparation instructions before guests arrive", es: "Ofrecer ayuda y seguir instrucciones de preparación antes de que lleguen invitados" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Start in the stairwell. Ask students how they already greet a neighbor, excuse a dog, and offer weekend plans. Keep pasar hidden until they notice one English verb cannot cover spend, drop by and happen.", es: "Arranca en la escalera. Pregunta cómo saludarían a un vecino, disculparían al perro y contarían planes del fin de semana. Mantén have to y owe escondidos hasta que vean que la obligación y la deuda no suenan igual." },
      presentation: { en: "Put three short lines on the board: ¿Dónde vas a pasar el puente?, No pasa nada and le debo treinta y ocho. Draw arrows from each to its job: spend time, reassure, owe money. Add ponte only after lunch preparation appears.", es: "Escribe tres líneas: Where are you spending the long weekend?, It's no trouble and I owe you fourteen. Marca qué hace cada una: plan, tranquilidad y deuda. Añade put on cuando aparezca la ropa para la comida." },
      practice: { en: "Run a stairwell-to-shop relay. One pair answers the puente invitation with me paso or no pasa nada; the next pair turns the shop note into le debo. Stop after each round for one exact correction. Let pasar carry the drill.", es: "Haz un relevo de vecino a compañera de almuerzo. Una pareja usa have to para una obligación real; otra usa owe para el dinero. Después entra put on con la ropa. Corrige una forma exacta por ronda." },
      production: { en: "Set three corners: neighbor's door, corner shop and aunt's kitchen. Students draw a card that interrupts them, such as late guest or missing plates, and must move rooms while keeping the obligation polite. Make pasar necessary in the scene.", es: "Marca tres rincones: vecino, lunch money y apartamento antes de la cena. Cada grupo recibe una interrupción, como perro, billete o música muy alta, y debe resolverla con have to, owe o put on sin sonar brusco." },
      exitTicket: { en: "Give the half-line Ahí ___ el domingo. Students choose me paso, paso, or no pasa nada and explain the choice in five words. This shows whether pasar is still one undifferentiated verb.", es: "Da la media frase I ___ you for lunch. Deben completar con owe, have o must y justificarlo en pocas palabras. Así ves si separan deuda, obligación y suposición." },
      homework: { en: "Students write a real weekend note to a neighbor. It must include one invitation response and one owed favor or object, but not a pasted dialogue line. Ask for the awkward version too. Bring pasar back next class.", es: "Escriben una nota real para un compañero. Debe incluir una deuda pequeña y una obligación de casa, pero no copiar el diálogo. Pide también la versión que les sonó rara. Traen \"owe\" de vuelta. Usa trouble también." },
      support: { en: "If pasar collapses, draw three boxes: time, visit and problem. Put puente, por la casa and nada under them, then let the student build only one box before trying the full exchange.", es: "Si todo se vuelve must, dibuja tres columnas: money, rule and guess. Pon owe, have to y must be encima. El estudiante cambia solo la cantidad o el sujeto antes de volver al diálogo." },
      stretch: { en: "Ask fast students to soften a refusal. They must decline the Sunday sancocho, still use no pasa nada correctly, and add one warm reason that keeps the neighbor relationship open. Push pasar into a new register.", es: "A los rápidos, dales una deuda incómoda: Karen dice there's no rush, pero quieren pagar ya. Deben usar owe y Thanks for covering me sin convertirlo en disculpa larga." },
      errors: [
        { en: "They say \"Paso por la casa\" when they mean \"I will pop over.\" Add \"me\" and practice \"me paso el domingo\"; the reflexive makes it a visit, not motion past a place.", es: "Dicen \"I have money to you\" porque calcan \"te tengo plata\". Escribe \"I owe you fourteen\" y cambia solo la cantidad; owe lleva a la persona después, no have." },
        { en: "They write \"debe ser las doce\" after hearing deber de for a guess. Circle agreement and repair it to \"deben de ser las doce\" or a simpler \"creo que son las doce.\"", es: "Dicen \"I must go to lunch\" para una invitación amable. Contrasta \"I have to help\" con \"I get to come by\"; must suena más duro y más personal." }
      ]
    }
  },
  "07-foundation-opinion": {
    mission: { en: "Give an opinion about cost, fit and bad weather while keeping the conversation friendly enough to continue.", es: "Dar una opinión sobre precio, talla y mal tiempo mientras mantienes la conversación lo bastante amable para seguir." },
    canDo: [
      { en: "Negotiate a paint job by saying what seems fair", es: "Negociar una pintada diciendo qué parece justo" },
      { en: "Say how clothing fits and make a return agreement", es: "Decir cómo queda la ropa y acordar una devolución" },
      { en: "State a belief about a public event without sounding certain", es: "Expresar una creencia sobre un evento sin sonar demasiado seguro" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Show a paint swatch, a tight jacket and a dark sky. Students give gut reactions with words they know. Do not accept grammar lectures; collect the pressure points where opinion needs parecer, quedar or creer.", es: "Muestra una muestra de pintura, una chaqueta apretada y un cielo negro. Piden reacciones rápidas en inglés conocido. Recoge dónde necesitan Does that work?, suits you o I don't think para seguir la conversación. Guarda \"seems\" hasta que lo pidan." },
      presentation: { en: "Use the painter first. Write ¿le parece que empecemos el sábado? and me parece caro, then ask who is being respected. Only after that bring in me queda for the jacket and no creo que llueva for doubt.", es: "Empieza con el pintor. Escribe Does Saturday work for you? y It seems steep, y pregunta cuál cuida la relación. Después añade It suits you para la chaqueta y I don't think it'll rain para la duda." },
      practice: { en: "Pairs sort twelve mini-lines into price, fit and weather. They repair two errors: pienso caro becomes me parece caro, and no creo que llueve becomes no creo que llueva. Keep the focus narrow.", es: "Las parejas clasifican doce mini frases en price, fit y weather. Reparan dos fallas: It appears expensive pasa a It seems steep, y I think no it will rain pasa a I don't think it'll rain." },
      production: { en: "Turn the room into El Hueco. One student sells a jacket, one is unsure, one friend watches the clouds outside. They must negotiate fit, pickup time and whether the parade is worth waiting for. Make parece necessary in the scene.", es: "Convierte el salón en una tienda. Un estudiante vende una chaqueta, otro duda y un amigo mira la lluvia. Deben usar suits, works for me y I don't think para cerrar precio, talla y plan. La escena debe necesitar \"seems\"." },
      exitTicket: { en: "Ask for one sentence disagreeing with the painter without sounding rude. Require me parece plus one softener, because that is the form most likely to keep the estimate conversation alive.", es: "Pide una frase que cuestione el precio sin sonar grosera. Debe usar It seems steep o Does that work for you?, porque ahí se ve si la opinión mantiene abierto el trato." },
      homework: { en: "Students photograph or sketch one item of clothing and write two opinions: how it fits and what they believe about the price. Ban dictionaries; they should recycle queda and parece.", es: "Escogen una prenda o un objeto de casa y escriben dos opiniones: cómo queda y qué piensan del precio. Deben reciclar suits, seems o works for me sin buscar palabras nuevas." },
      support: { en: "For students stuck on parecer, cover the adjective first. Give Me parece ___ with caro, bien and justo as tiles, then add ¿le parece? as the question version once the statement works.", es: "Si se enredan con opinion verbs, separa think, seem y suit con tres dibujos. La chaqueta no thinks; the price seems steep; the date works. Que completen solo un dibujo primero." },
      stretch: { en: "Have early finishers play a polite disagreement with don Fabio. They must reject one price, suggest Saturday, and use no creo que once about the weather without overclaiming certainty. Push parece into a new register.", es: "Quienes avancen rápido hacen una negociación breve. Deben proponer Saturday, decir works for me y objetar un precio con seems steep, manteniendo tono de cliente educado." },
      errors: [
        { en: "They answer \"pienso caro\" for the paint price. Put \"me parece caro\" beside it and ask who receives the opinion; parecer needs me here, not a bare thinker.", es: "Dicen \"It appears expensive\" porque ven parecer. Pon \"It seems steep\" al lado y explica que appear es visual o formal; seem lleva la opinión aquí." },
        { en: "They say \"no creo que llueve\" after the parade line. Box \"no creo que\" and change it to \"llueva\"; the doubt, not the rain, chooses the form.", es: "Dicen \"I think no it will rain.\" Move no after do: \"I don't think it will rain.\" En inglés la negación vive con think, no pegada a rain." }
      ]
    }
  },
  "08-foundation-conversation": {
    mission: { en: "Keep a simple conversation alive by calling, entering a shop, and thinking through a risky plan out loud.", es: "Mantener viva una conversación simple al llamar, entrar a una tienda y pensar en voz alta un plan riesgoso." },
    canDo: [
      { en: "Open a phone call and say who is speaking", es: "Abrir una llamada y decir quién habla" },
      { en: "Follow an invitation to come in and keep going straight", es: "Seguir una invitación para entrar y continuar derecho" },
      { en: "Say what you think about a plan before deciding", es: "Decir qué piensas de un plan antes de decidir" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Put a phone, an open shop door, and a crooked road on the floor. Students stand by the picture they understand and say nothing yet. Their choices tell you whether call openings or directions need more time.", es: "Pon un teléfono, una puerta abierta y una calle torcida en el piso. Se paran junto a la imagen que entienden sin hablar. Sus elecciones muestran si falta llamada o dirección." },
      presentation: { en: "Hold the phone to your ear and write ¿Con quién hablo? as the receiver's line. Then walk to the open door and label it ¡siga!, not seguir. Finish with siga derecho on the road arrow so the two sigas stay separate.", es: "Levanta el teléfono y escribe Who's calling? como frase de quien contesta. Luego camina a la puerta y etiqueta Come on in. Termina con Keep going straight sobre la flecha para separar las dos funciones." },
      practice: { en: "Put two phones back to back for ¿Con quién hablo? and habla Alex. Then draw a shop doorway for ¡siga! and a road line for siga derecho. Students move the card before choosing the phrase.", es: "Pon dos teléfonos espalda con espalda para Who's calling? e It's Alex. Luego dibuja una puerta para Come on in y una línea para Keep going straight. Mueven la tarjeta antes de hablar." },
      production: { en: "Run one interrupted phone call. Valentina answers, Don Fabio waves the caller into the shop, and Camilo suggests the midnight trip. The learner must end by using pienso que to refuse safely.", es: "Haz una llamada interrumpida. Valentina contesta, el tendero invita a entrar, y Camilo propone viajar a medianoche. La persona termina con I think that para rechazar sin sonar brusca." },
      exitTicket: { en: "Show either the phone or the open door. Learners write the one line that fits: ¿Con quién hablo? or ¡siga! No explanation counts, only choosing the right scene.", es: "Muestra el teléfono o la puerta abierta. Escriben la frase que encaja: Who's calling? o Come on in. No cuenta explicar; cuenta elegir bien la escena." },
      homework: { en: "Look for one doorway sign, one phone greeting, or one direction in the wild. Write where ¡siga! would mean come in and where siga derecho would mean keep going straight.", es: "Buscan una puerta, un saludo telefónico o una dirección real. Escriben dónde Come on in funcionaría y dónde Keep going straight funcionaría, sin traducir follow todavía." },
      support: { en: "The confusing piece is siga. Give two pictures only: open door and straight street. The student places ¡siga! or siga derecho under one picture, then says just that line.", es: "Lo confuso es que seguir no siempre es follow. Da dos dibujos: puerta abierta y calle recta. Ubican Come on in o Keep going straight y dicen solo esa línea." },
      stretch: { en: "Let early finishers turn the shop doorway into a wrong turn. One student gives ¡siga! to enter, another says siga derecho for the street, and the caller refuses the midnight plan with pienso que no.", es: "Deja que quienes acaban antes conviertan la puerta en una dirección equivocada. Una persona dice Come on in, otra Keep going straight, y quien llama rechaza el viaje con I think not." },
      errors: [
        { en: "They say \"Soy Alex? at the first phone turn\", copying English in phone calls, directions, and thinking. Stop it with \"¿Con quién hablo?\" because the receiver asks who is calling before giving information. Put the repair above Soy Alex? at the first phone turn, cross out the false words, and restart phone meetup.", es: "Dicen \"With whom do I speak?\" porque traducen desde el español en llamadas, direcciones y pensamiento. Cámbialo por \"Who’s calling?\" y repasa who's calling?, porque la llamada cotidiana no usa esa forma formal. Pon la reparación sobre With whom do I speak?, tacha las palabras falsas y reinicia llamada." },
        { en: "Expect \"Pienso en es mala idea\" when pressure rises in phone calls, directions, and thinking. The repair is \"Pienso que es mala idea\" because pensar que introduces the opinion sentence. Students repeat it with one new phone calls, directions, and thinking detail so it is not just copying.", es: "Espera \"follow straight\" cuando sube la presión en llamadas, direcciones y pensamiento. La reparación es \"keep going straight\", porque las direcciones usan keep going, no follow. Repiten la línea con un detalle nuevo de llamadas, direcciones y pensamiento para que no sea copia." }
      ]
    }
  },
  "09-foundation-finding": {
    mission: { en: "Look for a place, get someone called, and come back to a lunch spot you liked.", es: "Buscar un lugar, lograr que llamen a alguien y volver a un sitio de almuerzo que te gustó." },
    canDo: [
      { en: "Say you cannot find a shop or object", es: "Decir que no encuentras una tienda o un objeto" },
      { en: "Ask someone to call the technician and give a name", es: "Pedir que llamen al técnico y dar un nombre" },
      { en: "Return somewhere and order again without sounding new", es: "Volver a un lugar y pedir de nuevo sin sonar nuevo" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Hide the hardware-store card before class in the back corner. Let students search for it with maps closed today. Their frustration gives meaning to no la encuentro before the Spanish line appears.", es: "Esconde la tarjeta de ferretería antes de clase. Buscan sin mapas abiertos. Esa frustración da sentido a I can't find it antes de ver la frase en inglés." },
      presentation: { en: "Walk while saying busco la ferretería, then stop empty-handed and write no la encuentro. Put the store card under the second line only. Introduce llamar al técnico with the router, because calling is a new problem.", es: "Camina diciendo I'm looking for the store; detente sin encontrarla y escribe I can't find it. Pon la tarjeta de tienda bajo la segunda línea. Introduce call the technician solo con el router." },
      practice: { en: "Hide a hardware-store card under one of four corners. Students say busco while moving and no la encuentro after two misses. Bring in llamar al técnico only when the router picture replaces the map.", es: "Esconde una tarjeta de ferretería. Dicen I'm looking while buscan y I can't find it tras dos intentos. Introduce call the technician solo cuando el dibujo del router reemplace el mapa." },
      production: { en: "Turn the room into yesterday's lunch block. Students ask about the moved shop, get the technician called, then return to the corrientazo counter with volví and vuelvo a pedir lo mismo today.", es: "Convierte el salón en la cuadra del almuerzo. Preguntan por la tienda, piden llamada al técnico, y vuelven al puesto con I came back y order it again." },
      exitTicket: { en: "Point to an empty corner where the store should be. Each learner writes No la encuentro or I can't find it. The ticket checks result, not the act of searching.", es: "Señala una esquina vacía donde debería estar la tienda. Escriben I can't find it. La salida revisa resultado, no la búsqueda." },
      homework: { en: "Draw a tiny map with one missing place. Write busco while the search is still open, then no la encuentro when it fails. Add llamar al técnico only if the missing thing is internet.", es: "Dibujan un mapa pequeño con un lugar perdido. Escriben I'm looking for mientras buscan y I can't find it cuando falla. Añaden call the technician solo si el problema es internet." },
      support: { en: "Use a search-result split. Left side says busco; right side says no encuentro. Let the student move a store card from left to right before adding llamar al técnico.", es: "Usa una división entre búsqueda y resultado. Un lado dice looking for; el otro I can't find it. Mueven la tienda entre lados antes de sumar call the technician." },
      stretch: { en: "Ask quick pairs to make the found shop close early. They first say no la encuentro, then call the technician by name, and finally return to the lunch counter with volví.", es: "Pide a parejas rápidas que la tienda encontrada cierre temprano. Primero dicen I can't find it, luego call the technician por nombre, y al final vuelven al almuerzo con I came back." },
      errors: [
        { en: "They say \"Busco la ferretería after failing\", copying English in finding, calling, and returning. Stop it with \"No encuentro la ferretería\" because buscar is the search and encontrar is the result. Put the repair above Busco la ferretería after failing, cross out the false words, and restart moved hardware store.", es: "Dicen \"I look the store\" porque traducen desde el español en buscar, llamar y volver. Cámbialo por \"I can’t find the store\" y repasa find, porque find marca el resultado que falta. Pon la reparación sobre I look the store, tacha las palabras falsas y reinicia ferretería movida." },
        { en: "Expect \"Voy a volver pedir\" when pressure rises in finding, calling, and returning. The repair is \"Voy a volver a pedir\" because volver a needs the second a before the infinitive. Students repeat it with one new finding, calling, and returning detail so it is not just copying.", es: "Espera \"call to the technician\" cuando sube la presión en buscar, llamar y volver. La reparación es \"call the technician\", porque call no lleva to antes de la persona llamada. Repiten la línea con un detalle nuevo de buscar, llamar y volver para que no sea copia." }
      ]
    }
  },
  "10-foundation-daily-life": {
    mission: { en: "Make an ordinary plan, explain that you feel unwell, and tell a neighbor where you live.", es: "Hacer un plan cotidiano, explicar que te sientes mal y decirle a una vecina dónde vives." },
    canDo: [
      { en: "Agree on drinks, transport, and a decision after work", es: "Acordar una bebida, transporte y una decisión después del trabajo" },
      { en: "Say how you feel and since when", es: "Decir cómo te sientes y desde cuándo" },
      { en: "Give building, street, and address information simply", es: "Dar información simple de edificio, calle y dirección" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Draw Friday at five, a sick face, and a building lobby. Students choose plan, health, or address with their bodies. Keep tomar hidden until the drink plan has a time and friend.", es: "Dibuja viernes a las cinco, una cara enferma y una portería. Escogen plan, health o address moviéndose. Mantén go out for a drink oculto hasta que el plan tenga hora y amistad." },
      presentation: { en: "Write tomar algo under a glass and tomar un taxi under a car, then move tomar una decisión to a separate box. The board shows that tomar travels, but not everywhere. Add me siento mal only with the sick face.", es: "Escribe go out for a drink bajo el vaso y take a cab bajo el carro. Pon make a decision en otra caja para mostrar que no todo usa take. Agrega I feel sick solo con la cara." },
      practice: { en: "Deal three Friday cards: drink, taxi, decision. Students use tomar with the first two, then notice tomar una decisión as a chunk. Shift to the health card and change the verb to me siento.", es: "Reparte tarjetas de viernes: drink, cab y decision. Usan go out for a drink con la primera, take a cab con la segunda, y make a decision aparte. Luego cambian a I feel sick." },
      production: { en: "Students plan after-work drinks by text, then one wakes up maluco and cancels. The final turn must give a building address to Doña Rosa, so vivir en has a real reason today.", es: "Planean salir después del trabajo por mensaje, luego una persona se siente mal y cancela. El último turno da dirección a la administradora, para que live on tenga motivo real." },
      exitTicket: { en: "Give one card: Friday drink, sick morning, or new address. The learner writes the matching line. You are checking that tomar, sentir, and vivir do not blur.", es: "Entrega una tarjeta: bebida de viernes, mañana enferma o dirección nueva. Escriben la línea que encaja; revisas que drink, feel y live no se mezclen." },
      homework: { en: "Make a three-box Friday note: drink plan, sick cancellation, address for help. Use tomar algo only in the first box, me siento mal in the second, and vivo en in the third.", es: "Hacen una nota de viernes con tres casillas: plan de bebida, cancelación por salud y dirección. Usan go out for a drink, I feel sick y I live on cada una en su casilla." },
      support: { en: "Sort the module by preposition. Put tomar algo with a cup, me siento mal with a face, and vivo en with a map. The student makes one line from the strongest picture.", es: "Ordena por preposición e imagen. Pon go out for a drink con vaso, I feel sick con cara, y live on con calle. El estudiante produce una línea de la imagen más clara." },
      stretch: { en: "Have strong students write a cancellation text after the Friday plan. They need tomar algo for the original invitation, me siento mal for the reason, and vivo en for where a neighbor can help.", es: "Haz que estudiantes fuertes escriban una cancelación después del plan. Usan go out for a drink en la invitación, I feel sick en la razón y I live on para pedir ayuda." },
      errors: [
        { en: "They say \"Soy maluco\", copying English in plans, feelings, and addresses. Stop it with \"Estoy maluco\" because illness today is a state, not identity. Put the repair above Soy maluco, cross out the false words, and restart Friday drinks.", es: "Dicen \"take a beer\" porque traducen desde el español en planes, síntomas y direcciones. Cámbialo por \"go out for a drink\" y repasa go out for a drink, porque take funciona para taxi o bus, no para esa invitación. Pon la reparación sobre take a beer, tacha las palabras falsas y reinicia plan de viernes." },
        { en: "Expect \"Vivo sobre Bogotá\" when pressure rises in plans, feelings, and addresses. The repair is \"Vivo en Bogotá\" because sobre fits a street area, not the city itself. Students repeat it with one new plans, feelings, and addresses detail so it is not just copying.", es: "Espera \"I live in Fifth Street\" cuando sube la presión en planes, síntomas y direcciones. La reparación es \"I live on Fifth Street\", porque las calles usan on en inglés americano. Repiten la línea con un detalle nuevo de planes, síntomas y direcciones para que no sea copia." }
      ]
    }
  },
  "11-foundation-reading-writing": {
    mission: { en: "Trade contact information, talk about books, clear up a bill, and correct a tiny inventory list.", es: "Intercambiar contacto, hablar de libros, aclarar una factura y corregir una lista pequeña de inventario." },
    canDo: [
      { en: "Exchange numbers and promise a short message later", es: "Intercambiar números y prometer un mensaje corto después" },
      { en: "Say what you read and whether you finished it", es: "Decir qué lees y si lo terminaste" },
      { en: "Fix basic article, plural, and adjective choices on a list", es: "Corregir artículos, plurales y adjetivos básicos en una lista" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Pass around a paper phone, a used book, and a confusing bill. Ask what each object makes people do: message, read, or complain. Save escríbeme for the phone after the action is clear.", es: "Circula tres objetos: teléfono falso, libro usado y factura rara. Pregunta qué acción pide cada uno: text, read o understand. Guarda Text me para cuando el teléfono esté claro." },
      presentation: { en: "Write Escríbeme on the phone drawing, not in a letter. Then put leer on the book and comprendo su situación on the bill. End by showing one inventory line so agreement looks like a repair job, not a lecture.", es: "Escribe Text me sobre el dibujo del celular, no en una carta. Luego pon read en el libro e I understand your situation en la factura. Termina con una línea de inventario para corregir a/an." },
      practice: { en: "Pass a paper phone, a used book, and a bill. Students write escríbeme on the phone, leí or leer on the book card, and comprendo su situación at the service desk. Each object permits one phrase.", es: "Pasa un celular de papel, un libro usado y una factura. Escriben Text me en el teléfono, read the whole thing con el libro, e I understand your situation en la oficina. Cada objeto permite una frase." },
      production: { en: "Set up a tiny library table. Learners trade numbers after the workshop, recommend one used book, then correct three donated items for gender or adjective agreement before the box can be stored.", es: "Monta una mesa de biblioteca. Intercambian números, recomiendan un libro usado, y corrigen tres objetos donados con a/an o adjetivo antes de guardar la caja final." },
      exitTicket: { en: "Hand each learner either a phone or an inventory label. Phones need Escríbeme; labels need one corrected noun phrase with article agreement. The card tells you which half landed.", es: "Entrega un celular o una etiqueta de inventario. El celular pide Text me; la etiqueta pide a/an o adjetivo correcto. La tarjeta revela qué mitad quedó." },
      homework: { en: "Send or draft one real message that starts Escríbeme or me escribes. Then correct two household labels for article or adjective agreement; keep the phone task and label task separate.", es: "Envían o redactan un mensaje real con Text me o Drop me a line. Después corrigen dos etiquetas con a/an o adjetivo; mantienen separado mensaje y lista." },
      support: { en: "If agreement collapses, stop speaking. Give three inventory labels: libro viejo, revista nueva, problema serio. The student matches endings first, then returns to escríbeme for the social closing.", es: "Si se pierde la forma, pausa el diálogo. Da etiquetas red book, old table y an orange. El estudiante corrige a/an o adjetivo antes de volver a Text me." },
      stretch: { en: "Invite fast finishers to turn the inventory repair into a message. They correct one label, then send Escríbeme with a phone number so the writing work still has a person waiting.", es: "Invita a quienes terminan rápido a convertir la corrección en mensaje. Arreglan una etiqueta con a/an y luego escriben Text me con número, para que la escritura tenga destinatario." },
      errors: [
        { en: "They say \"Escríbeme una carta later\", copying English in messages, reading, bills, and agreement. Stop it with \"Escríbeme por WhatsApp\" because the coastal line means message me, not write a letter. Put the repair above Escríbeme una carta later, cross out the false words, and restart WhatsApp numbers.", es: "Dicen \"Write me for a quick text\" porque traducen desde el español en mensajes, lectura, facturas y concordancia. Cámbialo por \"Text me\" y repasa text me, porque text me nombra el mensaje corto de celular. Pon la reparación sobre Write me for a quick text, tacha las palabras falsas y reinicia números." },
        { en: "Expect \"libro viejas\" when pressure rises in messages, reading, bills, and agreement. The repair is \"libros viejos\" because noun and adjective must match in number and gender. Students repeat it with one new messages, reading, bills, and agreement detail so it is not just copying.", es: "Espera \"reds books\" cuando sube la presión en mensajes, lectura, facturas y concordancia. La reparación es \"red books\", porque los adjetivos en inglés no cambian por plural. Repiten la línea con un detalle nuevo de mensajes, lectura, facturas y concordancia para que no sea copia." }
      ]
    }
  },
  "12-foundation-learning": {
    mission: { en: "Learn a dance, follow a kitchen lesson, and explain what you study without turning school into a job history.", es: "Aprender un baile, seguir una clase de cocina y explicar qué estudias sin convertir la carrera en historia laboral." },
    canDo: [
      { en: "Ask someone to teach or show you a simple action", es: "Pedir que alguien te enseñe o muestre una acción simple" },
      { en: "Say you are learning by doing and paying attention", es: "Decir que aprendes haciendo y poniendo atención" },
      { en: "Name a degree or subject you study", es: "Nombrar una carrera o materia que estudias" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Hold up a dance step, a spoon, and a student ID. Ask which one you can learn by copying, which one needs a teacher, and which one names university life. Keep aprender a covered.", es: "Levanta un paso de baile, una cuchara y un carné. Pregunta cuál se aprende copiando, cuál necesita teacher, y cuál habla de universidad. Mantén learn to dance tapado." },
      presentation: { en: "Place a small a tile between aprender and bailar, then reuse the same tile between enseñar and cocinar. Students touch the tile before speaking. Only after that add estudiar una carrera on the bus card.", es: "Coloca una tarjeta to entre learn y dance, y otra entre teach y me para mostrar estructura, no traducción. Después agrega I major in en el carné del bus universitario." },
      practice: { en: "Put footprints, a spoon, and a university ID on the table. Students say aprendo a bailar with footprints, enséñeme with the spoon, and estudio una carrera only when the ID appears today.", es: "Pon huellas, cuchara y carné universitario. Dicen learn to dance con huellas, teach me con cuchara, y I major in solo cuando aparece el carné del estudiante." },
      production: { en: "Run a house party that moves into the kitchen. A cousin teaches the step, Doña Miriam teaches the recipe, and the bus conversation at the end asks what each person studies today.", es: "Haz una fiesta en casa que pasa a la cocina. Una prima enseña el paso, otra persona muestra la receta, y al final el bus pregunta what do you study." },
      exitTicket: { en: "Give a dance card. Learners write Aprendo a bailar or learn to dance. The check is the small connector after the learning verb, not a full party dialogue.", es: "Da una tarjeta de baile. Escriben learn to dance o I want to learn. Revisas el conector después de learn, no una conversación completa de fiesta." },
      homework: { en: "Copy two mini lessons from life: one thing you want someone to teach and one thing you are learning to do. Circle the a after aprender and enseñar before adding the action.", es: "Copian dos mini clases de la vida: algo you want to learn y algo someone can teach you. Encierran to después de learn o teach antes de añadir la acción." },
      support: { en: "The hard piece is the little a after aprender and enseñar. Give aprendo ___ bailar and enseño ___ cocinar with one shared a tile. Let the student place the tile before speaking.", es: "Lo difícil es elegir learn, teach o show. Da tres dibujos: baile, receta que explicas, receta que muestras. El estudiante escoge el verbo antes de decir la frase." },
      stretch: { en: "Ask confident learners to teach one tiny dance move without explaining grammar. The learner says enséñeme once, copies twice, and then answers what they study on the bus card.", es: "Pide a estudiantes seguros enseñar un paso mínimo sin explicar gramática. La otra persona dice teach me una vez, copia dos veces y luego responde What do you study? con el carné." },
      errors: [
        { en: "They say \"Aprendo bailar\", copying English in learning, teaching, and studying. Stop it with \"Aprendo a bailar\" because aprender needs a before the action learned. Put the repair above Aprendo bailar, cross out the false words, and restart family parranda.", es: "Dicen \"learn dancing\" porque traducen desde el español en aprender, enseñar y estudiar. Cámbialo por \"learn to dance\" y repasa learn to dance, porque la meta inmediata usa learn to más verbo. Pon la reparación sobre learn dancing, tacha las palabras falsas y reinicia fiesta familiar." },
        { en: "Expect \"Estudio una carrera as job history\" when pressure rises in learning, teaching, and studying. The repair is \"Estudio medicina\" because the bus scene asks about studies, not employment. Students repeat it with one new learning, teaching, and studying detail so it is not just copying.", es: "Espera \"my career is biology\" cuando sube la presión en aprender, enseñar y estudiar. La reparación es \"I major in biology\", porque career no nombra la materia universitaria. Repiten la línea con un detalle nuevo de aprender, enseñar y estudiar para que no sea copia." }
      ]
    }
  },
  "13-foundation-asking": {
    mission: { en: "Ask a stranger, answer for a roommate, and borrow a tool while staying clear and polite.", es: "Preguntar a un desconocido, contestar por una compañera y pedir prestada una herramienta con claridad." },
    canDo: [
      { en: "Ask permission before asking for directions", es: "Pedir permiso antes de preguntar por direcciones" },
      { en: "Answer a phone or question for another person", es: "Contestar un teléfono o una pregunta por otra persona" },
      { en: "Say what you need and ask to borrow it", es: "Decir qué necesitas y pedirlo prestado" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Tape a map to one wall, a ringing phone to another, and a drill to the door. Students point to information, answer, or tool before seeing ¿le puedo preguntar? The room itself separates the three asking jobs.", es: "Pega un mapa, un teléfono sonando y un taladro en paredes distintas. Señalan information, answer o tool. El salón separa las tres funciones antes de usar inglés." },
      presentation: { en: "Put ¿le puedo preguntar? beside the map and pedir prestado beside the drill. Do not put both under ask. Have students touch the object first, then choose preguntar, responder, or necesitar aloud.", es: "Pon Can I ask you something? junto al mapa y Can I borrow the drill? junto al taladro. No pongas ambos bajo ask. Tocan el objeto primero y luego eligen ask, answer o need." },
      practice: { en: "Draw a street corner, a ringing phone, and a drill. Students use ¿le puedo preguntar? at the corner, contestar el teléfono in the apartment, and necesito only after the shelf appears today.", es: "Dibuja esquina, teléfono y taladro. Usan Can I ask you something? en la calle, answer the phone en el apartamento, y I need to cuando aparece la repisa." },
      production: { en: "Run one apartment morning with ¿le puedo preguntar? on the first door. The learner asks the way to the health center, answers Caro's phone, then knocks across the hall to borrow the drill.", es: "Representa una mañana de apartamento. Preguntan por el centro, contestan el teléfono de Caro y piden prestado el taladro. Cada puerta cambia entre ask, answer y borrow." },
      exitTicket: { en: "Show only the drill. Learners write the borrowing question, not a direction question. If preguntar appears, they have not separated information from objects.", es: "Muestra solo el taladro. Escriben Can I borrow the drill?, no una pregunta de dirección. Si aparece ask for directions, falta separar información y objeto." },
      homework: { en: "Take three small photos or sketches: a map, a phone, and a tool. Under each, write the matching job: ¿le puedo preguntar?, contestar el teléfono, or pedir prestado.", es: "Toman tres fotos o dibujos: mapa, teléfono y herramienta. Debajo escriben la función correcta en inglés: Can I ask?, answer the phone o Can I borrow the drill?" },
      support: { en: "Separate information from objects. Put preguntar por on a map and pedir prestado on the drill. The student touches the map or tool before building the sentence.", es: "Separa información y objetos. Pon ask for directions sobre un mapa y borrow sobre el taladro. El estudiante toca mapa o herramienta antes de construir la frase." },
      stretch: { en: "Let early finishers add a neighbor who has the wrong tool. They ask directions with ¿le puedo preguntar?, answer Caro's phone, and borrow only after the drill card appears.", es: "Deja que quienes terminan pronto añadan un vecino con herramienta equivocada. Usan Can I ask? para direcciones, answer the phone para Caro y borrow solo cuando aparece el taladro." },
      errors: [
        { en: "They say \"Pedir por el centro de salud\", copying English in asking, answering, and needing. Stop it with \"Preguntar por el centro de salud\" because information uses preguntar, not pedir. Put the repair above Pedir por el centro de salud, cross out the false words, and restart health-center directions.", es: "Dicen \"ask directions\" porque traducen desde el español en preguntar, responder y necesitar. Cámbialo por \"ask for directions\" y repasa ask a question, porque ask for pide ayuda u objeto. Pon la reparación sobre ask directions, tacha las palabras falsas y reinicia direcciones al centro médico." },
        { en: "Expect \"Te presto el taladro? from borrower\" when pressure rises in asking, answering, and needing. The repair is \"¿Me prestás el taladro?\" because the person receiving the tool asks with prestar. Students repeat it with one new asking, answering, and needing detail so it is not just copying.", es: "Espera \"Can I lend your drill?\" cuando sube la presión en preguntar, responder y necesitar. La reparación es \"Can I borrow your drill?\", porque borrow es recibir y lend es prestar. Repiten la línea con un detalle nuevo de preguntar, responder y necesitar para que no sea copia." }
      ]
    }
  },
  "14-foundation-handling-things": {
    mission: { en: "Get set up to work, open a bank account, and finish a purchase before the shop closes.", es: "Instalarte para trabajar, abrir una cuenta bancaria y terminar una compra antes de que cierren." },
    canDo: [
      { en: "Ask to use a table, outlet, password, or restroom", es: "Pedir usar mesa, enchufe, clave o baño" },
      { en: "State what you need to open an account", es: "Decir qué necesitas para abrir una cuenta" },
      { en: "Ask closing time and close a small deal", es: "Preguntar la hora de cierre y cerrar un trato pequeño" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Set a laptop with no outlet, an ID card, and a closing sign on three chairs. Students choose work, bank, or shop. Keep ¿lo puedo usar? hidden until the laptop is visibly dying.", es: "Pon portátil sin enchufe, cédula y aviso de cierre en tres sillas. Escogen work, bank o shop. Mantén Could I use...? oculto hasta que el portátil parezca apagarse." },
      presentation: { en: "Point to the outlet and write ¿lo puedo usar? with lo tied to el enchufe. Then move to the ID and write abrir una cuenta. Keep cerrar for the shutter sign so open and close stay physical.", es: "Señala el enchufe y escribe Could I use the outlet? como pregunta completa. Luego mueve la cédula a open an account. Deja closed para el aviso de cierre; no mezcles banco y cafetería." },
      practice: { en: "Lay out a laptop, outlet, ID, and shutter sign. Students ask ¿lo puedo usar? for the outlet, abrir una cuenta with the ID, and ¿a qué hora cierran? only when the shutter drops.", es: "Extiende portátil, enchufe, documento y aviso de cierre. Practican Could I use the outlet? primero, open an account con el documento, y What time do you close? cuando baja la reja." },
      production: { en: "One learner works from a cafe until the battery dies, then walks to the bank and finally reaches a shop near closing. The same person must switch from using to opening to closing.", es: "Una persona trabaja en cafetería, va al banco y alcanza una tienda por cerrar. Debe cambiar de Could I use...? a open an account y luego It's closed." },
      exitTicket: { en: "Hold up the outlet card. Each learner writes ¿lo puedo usar? as the permission question. You are checking the object request and the pronoun, not bank paperwork.", es: "Levanta la tarjeta del enchufe. Escriben Could I use the outlet? Revisas petición de objeto, no trámites bancarios." },
      homework: { en: "At one cafe or desk, list two objects you might request permission to use. Write ¿lo puedo usar? for the masculine object and ¿la puedo usar? only if the object is feminine.", es: "En una cafetería o escritorio, listan dos objetos que podrían pedir. Escriben Could I use the outlet? completo una vez y luego cambian solo outlet por restroom o password." },
      support: { en: "For object pronouns, give only el enchufe and la clave. Students choose lo or la in ¿lo puedo usar? before any bank language appears. The bank is a later scene.", es: "Para apoyar, limita la cafetería a outlet, restroom y password. El estudiante pide una sola cosa con Could I use...?; open an account queda tapado hasta que esa pregunta salga." },
      stretch: { en: "Send quick pairs through a dying-battery race. They ask ¿lo puedo usar? for the outlet, open the account with ID, then reach the shop as the shutter comes down.", es: "Envía parejas rápidas por una carrera de batería baja. Piden Could I use the outlet?, abren la cuenta con documento y llegan a la tienda cuando baja la reja." },
      errors: [
        { en: "They say \"¿La puedo usar? for el enchufe\", copying English in using, opening, and closing. Stop it with \"¿Lo puedo usar?\" because the object is masculine in that cafe request. Put the repair above ¿La puedo usar? for el enchufe, cross out the false words, and restart cafe workspace.", es: "Dicen \"Can I use the bath?\" porque traducen desde el español en usar, abrir y cerrar. Cámbialo por \"Could I use the restroom?\" y repasa Could I use...?, porque restroom es la palabra pública adecuada. Pon la reparación sobre Can I use the bath?, tacha las palabras falsas y reinicia cafetería." },
        { en: "Expect \"La tienda es cerrada\" when pressure rises in using, opening, and closing. The repair is \"La tienda está cerrada\" because closed is a state after the action. Students repeat it with one new using, opening, and closing detail so it is not just copying.", es: "Espera \"The bank is close\" cuando sube la presión en usar, abrir y cerrar. La reparación es \"The bank is closed\", porque closed es adjetivo y close es verbo. Repiten la línea con un detalle nuevo de usar, abrir y cerrar para que no sea copia." }
      ]
    }
  },
  "15-foundation-starting-finishing": {
    mission: { en: "Start a class, finish a haircut, and enter a first workplace with the right small verbs.", es: "Empezar una clase, terminar un corte y entrar al primer trabajo con verbos pequeños bien usados." },
    canDo: [
      { en: "Say when a class starts and that you are ready", es: "Decir cuándo empieza una clase y que estás listo" },
      { en: "Ask whether a service is almost finished", es: "Preguntar si un servicio ya casi termina" },
      { en: "Understand instructions for entering and starting work", es: "Entender instrucciones para entrar y comenzar trabajo" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Mark three floor spots: salsa line, barber chair, office door. Students step to start, finish, or enter in order twice together. Keep the verbs covered until their bodies have chosen the event.", es: "Marca tres lugares: línea de salsa, silla de peluquería y puerta de oficina. Caminan a start, finish o enter. Mantén los verbos tapados hasta que el cuerpo elija el evento." },
      presentation: { en: "Use arrows between verb and action: empezar a bailar, terminar de cortar, entrar a trabajar. Put the small words on colored cards. Students move the card, because the missing preposition is the lesson.", es: "Usa flechas entre verbo y acción: start dancing, finish cutting, come in. Pon las partículas en tarjetas de color. El grupo mueve la tarjeta para distinguir proceso, final y entrada." },
      practice: { en: "Use a salsa step card for empezar a, scissors for terminar de, and a door badge for entrar a trabajar. Students add the small preposition by placing the card between verb and action.", es: "Usa paso de baile para start dancing, tijeras para finish cutting, y carnet para come in o start work. El grupo escoge una escena; no mezcles peluquería con oficina." },
      production: { en: "Stage the first day as three thresholds: studio floor, barber chair, office reception. Students ask with empezar a or terminar de whether each activity starts, is almost done, or lets them enter.", es: "Monta tres umbrales: salón de baile, silla de peluquería y recepción. Preguntan si algo starts, is almost done o come in, y cruzan al siguiente lugar juntos." },
      exitTicket: { en: "Give one threshold card: dance floor, barber mirror, or office door. Learners write the matching Spanish line with empezar, terminar, or entrar. Check the small connector.", es: "Entrega una tarjeta de umbral: pista, espejo o puerta. Escriben la línea de start, finish o come in que encaja. Revisa el conector pequeño." },
      homework: { en: "Draw three thresholds: before the dance, near the last haircut snip, and at the office door. Label them empezar a, terminar de, and entrar a with one action each.", es: "Dibujan tres umbrales: antes del baile, al final del corte y en la puerta laboral. Los etiquetan start dancing, finish cutting y come in, sin mezclar las escenas." },
      support: { en: "The obstacle is the missing preposition. Write empezar ___ bailar and entrar ___ trabajar with a single a tile. The student places it, then earns terminar de as the next card.", es: "El obstáculo es que start no siempre traduce entrar. Muestra puerta y horario: come in para la puerta, start work para el horario. El estudiante decide mirando el dibujo." },
      stretch: { en: "Have fast finishers choreograph three doorway lines. One starts salsa with empezar a, one checks the haircut with terminar de, and one enters work without turning entrar into arrive.", es: "Pide a estudiantes rápidos armar tres líneas de umbral. Una inicia baile con start dancing, otra termina corte con be done, y otra entra al trabajo sin decir arrive." },
      errors: [
        { en: "They say \"Empiezo bailar\", copying English in starting, finishing, and entering. Stop it with \"Empiezo a bailar\" because empezar needs a before the infinitive. Put the repair above Empiezo bailar, cross out the false words, and restart Cali salsa class.", es: "Dicen \"enter to work\" porque traducen desde el español en empezar, terminar y entrar. Cámbialo por \"start work\" y repasa start, porque entrar a trabajar se expresa como empezar el trabajo. Pon la reparación sobre enter to work, tacha las palabras falsas y reinicia clase de baile." },
        { en: "Expect \"Termino cortar\" when pressure rises in starting, finishing, and entering. The repair is \"Termino de cortar\" because terminar de marks finishing an action already in progress. Students repeat it with one new starting, finishing, and entering detail so it is not just copying.", es: "Espera \"I am finished?\" cuando sube la presión en empezar, terminar y entrar. La reparación es \"Are we almost done?\", porque el servicio pregunta por el proceso completo. Repiten la línea con un detalle nuevo de empezar, terminar y entrar para que no sea copia." }
      ]
    }
  },
  "16-foundation-coming-and-going": {
    mission: { en: "Plan going out, ride up to a hillside neighborhood, and get off the bus at the right stop.", es: "Planear una salida, subir a un barrio en loma y bajarte del bus en la parada correcta." },
    canDo: [
      { en: "Say when you get off work and go out", es: "Decir cuándo sales del trabajo y sales a divertirte" },
      { en: "Describe getting on transport and going up", es: "Describir subir a un transporte y subir una loma" },
      { en: "Ask where to get off and follow the answer", es: "Preguntar dónde bajarte y seguir la respuesta" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Draw a route from work to cable car to bus stop. Students walk it silently: leave, go up, get off. Keep salir del trabajo covered until the first arrow has a clear starting point.", es: "Dibuja una ruta de trabajo a cabina y parada. Caminan en silencio: leave, go up, get off. Mantén get off work oculto hasta que la primera flecha tenga origen claro." },
      presentation: { en: "Write salir del trabajo on the arrow leaving the office, me subo al metrocable on the cabin door, and me bajo aquí on the bus bell. The board is a map, not a conjugation table.", es: "Escribe get off work en la flecha que sale del trabajo, get on the cable car en la cabina y get off here en el timbre del bus. El tablero es mapa, no tabla." },
      practice: { en: "Put a work clock, cable-car door, and bus bell in order. Students say salgo del trabajo at the clock, me subo al metrocable at the door, and me bajo aquí only at the bell.", es: "Pon reloj laboral, puerta de cabina y timbre de bus. Practican get off work con el reloj, get on the cable car con la cabina y get off here solo con el timbre." },
      production: { en: "Students plan Saturday by chat, ride up to a friend’s barrio, then ask an older passenger for the bus stop home. The route forces salir, subir, and bajar to stay in different moments.", es: "Planean el sábado por chat, suben a visitar a un amigo y preguntan por la parada de regreso. La ruta separa get off work, get on y get off." },
      exitTicket: { en: "Point to one arrow on the route. The learner writes the matching movement line. If bajar una app appears for the bus, the transport meaning needs another day.", es: "Señala una flecha de la ruta. Escriben get off work, get on o get off. Si aparece download para el bus, falta separar tecnología y transporte." },
      homework: { en: "Trace one route you took today. Put salir del trabajo at the starting place, subirse where transport begins, and bajarse where you leave it. Keep bajar una app off the route.", es: "Trazan una ruta del día. Escriben get off work en el inicio, get on donde suben al transporte y get off donde bajan. Download queda solo para el celular." },
      support: { en: "Use arrows, not grammar labels. One arrow leaves work for salir de, one climbs to the barrio for subir, one drops from the bus for bajarse. The student says only the arrow chosen.", es: "Usa flechas, no explicaciones largas. Una sale del trabajo, otra entra al transporte, otra baja del bus. El estudiante dice get off work, get on o get off según la flecha." },
      stretch: { en: "Ask strong students to add a phone-app confusion card. They must keep bajarse for the bus bell and use bajar una app only when the phone, not the route, is visible.", es: "Pide a estudiantes fuertes añadir una confusión de aplicación. Mantienen get off para el timbre del bus y usan download solo cuando aparece el celular, no la ruta." },
      errors: [
        { en: "They say \"Salgo a mi trabajo\", copying English in going out, going up, and getting off. Stop it with \"Salgo del trabajo\" because de marks the place you leave. Put the repair above Salgo a mi trabajo, cross out the false words, and restart the Saturday chat.", es: "Dicen \"go out of work\" porque traducen desde el español en salir, subir y bajar. Cámbialo por \"get off work\" y repasa get off work, porque salir del trabajo no es una salida social. Pon la reparación sobre go out of work, tacha las palabras falsas y reinicia el chat del sábado." },
        { en: "Expect \"Subo el metrocable\" when pressure rises in going out, going up, and getting off. The repair is \"Me subo al metrocable\" because transport boarding needs the reflexive form. Students repeat it with one new going out, going up, and getting off detail so it is not just copying.", es: "Espera \"download the bus\" cuando sube la presión en salir, subir y bajar. La reparación es \"get off the bus\", porque download solo sirve para archivos o apps. Repiten la línea con un detalle nuevo de salir, subir y bajar para que no sea copia." }
      ]
    }
  },
  "17-foundation-carrying-and-leaving": {
    mission: { en: "Manage what goes with you, what comes to you and what stays behind during meals and visits.", es: "Manejar lo que llevas, lo que te traen y lo que se queda atrás durante comidas y visitas." },
    canDo: [
      { en: "Ask what to bring to a shared meal and accept the answer", es: "Preguntar qué llevar a una comida compartida y aceptar la respuesta" },
      { en: "Order lunch, request the check and explain you are in a hurry", es: "Pedir almuerzo, pedir la cuenta y explicar que tienes afán" },
      { en: "Leave a friend's house naturally and recover a forgotten item", es: "Despedirte en una casa y recuperar algo olvidado" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Put a sancocho pot, a restaurant bill and a forgotten jacket on three chairs. Students say what moves toward whom. Do not name llevar yet; the arrows reveal who is imagining the motion.", es: "Pon un asado, una cuenta y una chaqueta olvidada en tres sillas. Pregunta qué va hacia quién en inglés. No enseñes bring ni leave todavía; las flechas muestran desde dónde piensan." },
      presentation: { en: "Draw two arrows: Alex to Wilmer and waiter to table. Place ¿qué llevo? on the first and ¿me trae la cuenta? on the second. Then show dejé la chaqueta as a different problem, not more movement. Keep the board anchored in llevar.", es: "Dibuja dos flechas: invitado hacia barbecue y waiter hacia mesa. Pon What should I bring? y Could you bring the bill? Después muestra I left my jacket como problema de objeto, no de dirección." },
      practice: { en: "Use six object cards: beers, juice, menu, check, dishes, jacket. Students choose llevo, trae or dejé for each and say the full line. Wrong arrows go back to the floor map. Let llevar carry the drill.", es: "Usa seis tarjetas: beer, juice, menu, bill, dishes y jacket. Escogen bring, take o leave y dicen la frase completa. Cuando fallen, vuelven al mapa de flechas antes de repetir." },
      production: { en: "Stage the goodbye at the friend's place. Half the class tries to help too much; the hosts use dejá eso ahí and dejame contarte. A late discovery of the jacket forces a natural repair. Make llevar necessary in the scene.", es: "Representa la despedida en casa. Unos quieren lavar platos, otros guardan una historia y alguien olvida la chaqueta. Deben usar Leave that there, let me tell you y I left my jacket sin traducir palabra por palabra. La escena debe necesitar \"bring\"." },
      exitTicket: { en: "Give two arrows and one sentence stem: ¿Qué ___? Students write llevo or trae and add why. This catches the common bring/take reversal before it hardens. Check llevar, not a list.", es: "Entrega una flecha hacia la fiesta y otra hacia la mesa. Completan What should I ___? o Could you ___ the bill? y explican quién recibe el movimiento. Revisa \"bring\", no una lista." },
      homework: { en: "Write a six-line visit plan: what you will take, what you ask someone to bring, and one thing you might leave behind. Use real objects from this week. Bring llevar back next class.", es: "Escriben un plan de visita de seis líneas: qué bring, qué piden que alguien bring y qué podrían leave behind. Deben usar objetos reales de la semana." },
      support: { en: "When llevar and traer blur, stand the student physically at the starting point. Move one card toward the party and one toward the table. Say the verb only after the body chooses the arrow.", es: "Si bring y take se mezclan, cambia el punto de vista con el cuerpo. El estudiante se para como host y luego como guest. Solo después escribe What should I bring?" },
      stretch: { en: "Give confident students the phrase deje así. They must decide whether it means leave it physically, drop the topic, or stop worrying, then write three different replies. Push llevar into a new register.", es: "A los rápidos, dales drop it, leave it there y quit. Deben acomodar cada una en una despedida distinta y justificar por qué la chaqueta no usa let. Lleva \"bring\" a otro tono." },
      errors: [
        { en: "They bring everything with traer: \"¿Qué traigo al sancocho?\" while standing away from the house. Draw arrows to Wilmer and Alex; from Alex outward is \"¿qué llevo?\"", es: "Dicen \"What should I take?\" al preguntar al anfitrión qué aportar. Muestra \"What should I bring?\" y explica que bring mira hacia el punto de la fiesta, no desde quien camina." },
        { en: "They translate \"déjame\" as \"leave me\" in the goodbye scene. Put \"dejame contarte\" next to \"let me tell you\" and mark dejar as permission, not abandonment.", es: "Dicen \"leave me tell you\". Escribe \"let me tell you\" y luego \"I left my jacket\". En esta escena leave es para la chaqueta; let da permiso para hablar." }
      ]
    }
  },
  "18-foundation-memory-and-waiting": {
    mission: { en: "Recover memories, admit a forgotten errand and wait your turn without making the exchange collapse.", es: "Recuperar recuerdos, admitir un mandado olvidado y esperar el turno sin dañar el intercambio." },
    canDo: [
      { en: "Recognize an old friend and ask about shared school memories", es: "Reconocer a una amiga y preguntar por recuerdos del colegio" },
      { en: "Apologize for forgetting an errand and promise a repair", es: "Disculparte por olvidar un mandado y prometer arreglarlo" },
      { en: "Ask how long the clinic wait is and respond politely", es: "Preguntar cuánto demora el turno médico y responder con cortesía" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Write three prompts: old school, missing cake, clinic line. Students tell the easiest possible story for each. Listen for whether they already separate memory, apology and waiting. Hold recordar until students ask for it. Add one name.", es: "Escribe tres pistas: old school, forgotten cake y clinic line. Cuentan la historia más simple que puedan. Escucha si ya separan remember, forget, wait, hope y expect antes de mostrar modelos." },
      presentation: { en: "Start with Diana's question ¿vos te acordás de mí? Put me acuerdo de beside no recuerdo tu apellido. Ask why one takes de and the other does not before moving to se me olvidó. Keep the board anchored in recordar.", es: "Empieza con Do you remember me? y I don't recall your last name. Subraya que remember no lleva of. Después presenta It slipped my mind para la torta, porque la disculpa necesita otra textura." },
      practice: { en: "Students rebuild three broken lines: recuerdo de tu apellido, olvidé por completo la torta, and espero por el turno. Each repair must say whether the issue is preposition, responsibility or meaning. Let recordar carry the drill.", es: "Reparan tres frases rotas: I remember of you, I forgot of the cake y I am waiting my turn. Cada arreglo debe nombrar qué cambia: preposition, object or missing for." },
      production: { en: "Run the clinic scene with a memory interruption. The receptionist delays the turn; an old friend appears; the student realizes they forgot the cake. The task is to recover socially, not finish perfectly. Make recordar necessary in the scene.", es: "Haz la escena de la clínica con una interrupción. Mientras esperan, aparece una amiga vieja y falta una torta prometida. Deben combinar remember, It slipped my mind y wait for sin perder cortesía." },
      exitTicket: { en: "Ask for one apology with se me olvidó and one promise with no se me olvida. If students choose olvidé both times, you know the softer accident frame needs return. Check recordar, not a list.", es: "Pide una disculpa con It slipped my mind y una promesa con I won't forget. Si usan forget igual en ambas, vuelve a la diferencia entre accidente y compromiso. Revisa \"remember\", no una lista." },
      homework: { en: "Students write a message to someone from school. It must ask if the person remembers one shared detail and include a separate line admitting one small forgotten task. Bring recordar back next class.", es: "Escriben un mensaje a alguien conocido. Debe preguntar Do you remember one shared detail y admitir con It slipped my mind un mandado pequeño, sin usar of después de remember." },
      support: { en: "For a lost student, give two fixed frames: me acuerdo de ___ and recuerdo ___. Use the same noun in both frames so the student sees that the verb, not the memory, changes the grammar. Make recordar the small rescue.", es: "Para apoyo, entrega tres tarjetas: remember, remind y recall. Usa the teacher en las tres: I remember the teacher, remind me to call, I recall his name. Cambia solo la tarjeta." },
      stretch: { en: "Ask advanced pairs to make the wait kinder. They must use espere un momentico, eso espero and one estimate without sounding annoyed at the receptionist. Push recordar into a new register.", es: "Quienes terminen pronto convierten la fila en una conversación amable. Deben usar One moment, please, hang tight y I hope so, y luego explicar cuál frase baja la tensión. Lleva \"remember\" a otro tono." },
      errors: [
        { en: "They write \"recuerdo de Diana\" because English has remember about. Put \"me acuerdo de Diana\" and \"recuerdo a Diana\" on the board; one takes de, the other does not.", es: "Dicen \"I remember of Diana.\" Tacha of y deja \"I remember Diana\"; si necesitan una imagen más formal, ofrece \"I recall her,\" sin preposición." },
        { en: "They say \"olvidé la torta\" and sound colder than the scene. Show \"se me olvidó la torta\"; the se me admits fault while keeping the apology human.", es: "Dicen \"I forgot of the cake.\" Escribe \"I forgot the cake\" y \"I forgot to bring it\"; forget takes the object directly or to plus verb." }
      ]
    }
  },
  "19-foundation-looking-and-listening": {
    mission: { en: "Look at art, manage a noisy call, and catch a shout in a salsa club without freezing.", es: "Mirar arte, manejar una llamada con ruido y captar un grito en una salsateca sin quedarte quieto." },
    canDo: [
      { en: "Tell someone what to look at in a picture", es: "Decirle a alguien qué mirar en una imagen" },
      { en: "Check whether another person can hear you", es: "Comprobar si otra persona puede oírte" },
      { en: "React to a call for attention in a loud room", es: "Reaccionar a un llamado de atención en un lugar ruidoso" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Dim the room like a museum, then cover your ears as street music begins outside. Students show with hands whether the problem is looking, hearing, or attention. Keep mire off the board.", es: "Oscurece el salón como museo y luego tapa tus oídos por la música. Muestran con manos si el problema es look, hear o attention. Mantén Can you hear me? fuera del tablero." },
      presentation: { en: "Stand by a picture and say Mire este cuadro while pointing. Move away, pretend the phone signal fails, and write ¿me escuchas? Finally use oiga as a call across the room. Three spaces, three purposes.", es: "Párate junto a un cuadro y escribe look at the painting. Luego falla la llamada y escribe Can you hear me? Usa Listen to me solo para pedir atención. Tres espacios, tres propósitos." },
      practice: { en: "Place a painting, a noisy phone, and a salsa-club shout on the wall. Students choose mire for the guide, ¿me escuchas? for the call, and oiga only when someone needs attention today.", es: "Coloca cuadro, llamada ruidosa y grito de club. Practican Can you hear me? con el teléfono, look at the painting con el guía y Listen to me cuando alguien pide atención." },
      production: { en: "Walk the class through a museum that becomes a street party. The guide says mire at one painting, the phone call fails once, and the dancer catches a shout before answering safely.", es: "Recorre un museo que se vuelve fiesta. Una persona mira el cuadro, otra revisa si la oyen, y la bailarina responde al grito con Excuse me o Hey." },
      exitTicket: { en: "Show a bad-signal phone. Learners write ¿me escuchas? or Can you hear me? Do not accept look language; the ticket checks sound arriving.", es: "Muestra un teléfono sin señal. Escriben Can you hear me? No aceptes look at; la salida revisa si el sonido llega." },
      homework: { en: "Collect three quiet observations: one picture detail for mire, one noisy-call moment for ¿me escuchas?, and one attention call for oiga. Bring the setting, not a long sentence.", es: "Recogen tres observaciones: un detalle de imagen para look at, una llamada mala para Can you hear me?, y un llamado de atención para Listen to me. Traen el contexto, no párrafos." },
      support: { en: "For students stuck between mirar and escuchar, remove the club. Use one painting and one phone. The student chooses mire with the eyes or ¿me escuchas? with the signal bar.", es: "Si confunden hear y listen, quita el museo. Usa solo una llamada: Can you hear me? revisa señal; Listen to me pide atención. Después vuelve al cuadro." },
      stretch: { en: "Let confident learners run the same line across three noise levels. They point with mire in the quiet museum, test ¿me escuchas? on the bad call, and use oiga only to get attention.", es: "Deja que estudiantes seguros prueben una frase en tres niveles de ruido. Usan look at en museo, Can you hear me? en llamada mala y Listen to me solo para llamar atención." },
      errors: [
        { en: "They say \"Vea el cuadro for attention\", copying English in looking, listening, and hearing. Stop it with \"Mire el cuadro\" because mirar asks for active looking at the painting. Put the repair above Vea el cuadro for attention, cross out the false words, and restart Botero museum.", es: "Dicen \"look the painting\" porque traducen desde el español en mirar, escuchar y oír. Cámbialo por \"look at the painting\" y repasa Can you hear me?, porque look necesita at antes del objeto. Pon la reparación sobre look the painting, tacha las palabras falsas y reinicia museo." },
        { en: "Expect \"¿Me oyes? for the phone check\" when pressure rises in looking, listening, and hearing. The repair is \"¿Me escuchas?\" because the phone scene checks whether sound arrives clearly. Students repeat it with one new looking, listening, and hearing detail so it is not just copying.", es: "Espera \"listen me\" cuando sube la presión en mirar, escuchar y oír. La reparación es \"Listen to me\", porque listen exige to antes de la persona. Repiten la línea con un detalle nuevo de mirar, escuchar y oír para que no sea copia." }
      ]
    }
  },
  "20-foundation-buying-and-paying": {
    mission: { en: "Pay with awkward cash, bargain for mangoes, sell a bike, and buy exact amounts for breakfast.", es: "Pagar con efectivo incómodo, negociar mangos, vender una bicicleta y comprar cantidades exactas para el desayuno." },
    canDo: [
      { en: "Ask about price, change, and smaller bills", es: "Preguntar por precio, cambio y billetes más pequeños" },
      { en: "Make and close a simple offer", es: "Hacer y cerrar una oferta simple" },
      { en: "Choose articles and quantities for market items", es: "Escoger artículos y cantidades para productos del mercado" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Give one student a large bill and another a mango at the pretend register. Let the class predict the problem before words appear. Keep sencillo hidden until they see that payment can fail.", es: "Da a una persona un billete grande y a otra un mango. Predicen el problema antes de ver palabras. Mantén anything smaller oculto hasta que vean que el pago puede fallar." },
      presentation: { en: "Place sencillo before the cash changes hands and vuelto after the coins return. Then move to the mango stall and write ¿a cómo? above the fruit. The board follows the money's path.", es: "Coloca anything smaller antes de pagar y keep the change después de recibir monedas. Luego mueve la fruta al puesto y escribe How much are you asking? El tablero sigue el camino del dinero." },
      practice: { en: "Put play money beside mango pictures. Students ask ¿tiene sencillo? before paying, use el vuelto after the cashier returns coins, and switch to ¿a cómo? when the mango seller names no price.", es: "Pon billetes de juguete junto a mangos. Practican anything smaller? antes de pagar, keep the change después, y How much are you asking? cuando el vendedor no da precio." },
      production: { en: "Make a checkout line that turns into a coastal stall. The buyer has one large bill, bargains for mangoes, then reads a se vende bike sign and makes a final offer today.", es: "Arma una fila de caja que se vuelve venta de garaje. La compradora tiene un billete grande, pregunta precio, y cierra con Would you take...? o I'll take it." },
      exitTicket: { en: "Show a large bill at the register. Learners ask for smaller change. You are checking anything smaller or ¿tiene sencillo?, not bargaining yet.", es: "Muestra un billete grande en la caja. Piden cambio con anything smaller? Revisas esa petición, no la negociación de mangos todavía." },
      homework: { en: "Handle the cash problem on paper. Draw a large bill, write ¿tiene sencillo?, then draw the coins returning as vuelto. Save ¿a cómo? for a separate mango price tag.", es: "Resuelven el problema del efectivo en papel. Dibujan billete grande, escriben anything smaller?, y luego monedas de cambio con keep the change aparte. How much are you asking? va en un mango." },
      support: { en: "The money words come in order. Put sencillo before the sale and vuelto after the sale with an arrow between them. The learner cannot say the second word until coins move back.", es: "El apoyo es temporal. Anything smaller? va antes del pago; keep the change va después. Mueve monedas de ida y vuelta para que el estudiante elija por momento, no por traducción." },
      stretch: { en: "Have early finishers bargain only after solving the large-bill problem. The cashier must hear ¿tiene sencillo? first; ¿a cómo? and le hago precio wait for the mango stall.", es: "Haz que quienes terminan pronto negocien solo después del billete grande. La caja oye anything smaller? primero; How much are you asking? y Would you take...? esperan al puesto de mango." },
      errors: [
        { en: "They say \"¿Tiene simple?\", copying English in paying, buying, selling, and quantities. Stop it with \"¿Tiene sencillo?\" because sencillo is the small-change word at the register. Put the repair above ¿Tiene simple?, cross out the false words, and restart checkout bill.", es: "Dicen \"pay the mangoes\" porque traducen desde el español en pagar, comprar, vender y cantidades. Cámbialo por \"pay for the mangoes\" y repasa anything smaller, porque pay for lleva el objeto comprado. Pon la reparación sobre pay the mangoes, tacha las palabras falsas y reinicia caja." },
        { en: "Expect \"¿Cuánto cuesta? at the coastal stall\" when pressure rises in paying, buying, selling, and quantities. The repair is \"¿A cómo?\" because the stall price question is shorter and local. Students repeat it with one new paying, buying, selling, and quantities detail so it is not just copying.", es: "Espera \"other mango for one more\" cuando sube la presión en pagar, comprar, vender y cantidades. La reparación es \"another mango\", porque another combina an y other para uno adicional. Repiten la línea con un detalle nuevo de pagar, comprar, vender y cantidades para que no sea copia." }
      ]
    }
  },
  "21-foundation-at-the-table": {
    mission: { en: "Order the lunch special, accept or refuse seconds, and answer the coastal question about eating.", es: "Pedir el almuerzo del día, aceptar o rechazar repetición y responder la pregunta costeña sobre comer." },
    canDo: [
      { en: "Order soup, main plate, and juice politely", es: "Pedir sopa, plato fuerte y jugo con cortesía" },
      { en: "Accept more food or say you are full", es: "Aceptar más comida o decir que estás lleno" },
      { en: "Answer whether you have eaten when you arrive", es: "Responder si ya comiste cuando llegas" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Set a paper bowl, a second ladle, and a doorway near a lunch menu card. Students point to order, more, or already ate. Keep pedir hidden until the menu makes someone hungry.", es: "Pon plato de papel, cucharón, puerta y menú de almuerzo. Señalan order, more o already ate. Mantén Could I get...? oculto hasta que el menú cree hambre." },
      presentation: { en: "Put ¿me regala el corrientazo? on the menu, not under a generic order heading. Move to the empty bowl for ¿le sirvo más?, then to the doorway for ¿ya comiste? The table changes the language.", es: "Pon Could I get the lunch special? en el menú, no bajo una lista de pedidos. Pasa al plato vacío con Want some more? y a la puerta con Did you eat? La mesa cambia la frase." },
      practice: { en: "Use a paper menu with soup, seco, and juice. Students order with ¿me regala...? once, then practice ¿le sirvo más? only when the bowl card is empty. Finish with ¿ya comiste? at the doorway.", es: "Usa menú de papel con sopa, plato y jugo. Practican Could I get...? para pedir, Want some more? con el plato vacío, y Did you eat? al llegar a la puerta." },
      production: { en: "Run a lunch hour. One student orders the corrientazo, another becomes Doña Miriam with seconds, and a third is the coastal aunt at the door. The table language changes with each host.", es: "Representa la hora de comer. Una persona pide el lunch special, otra ofrece más comida y otra pregunta Did you eat? en la puerta. Cada anfitrión cambia la frase." },
      exitTicket: { en: "Hand out one menu card. Learners order the lunch special politely with ¿me regala el corrientazo? If they write ordenar or ask, repeat the restaurant request tomorrow.", es: "Entrega una tarjeta de menú. Piden el lunch special con Could I get...? Si aparece ask suelto, repite la petición de restaurante mañana." },
      homework: { en: "Plan one lunch visit. Write the menu request with ¿me regala el corrientazo?, one answer to ¿le sirvo más?, and a doorway answer to ¿ya comiste? on separate cards.", es: "Planean una visita de almuerzo. Escriben Could I get the lunch special?, una respuesta a Want some more?, y una respuesta de puerta a Did you eat? en tarjetas separadas." },
      support: { en: "If the learner says ordenar, point to the menu and give pido as the only verb. Keep servir covered until a second helping appears; one meal step at a time.", es: "Si el estudiante usa ask solo, señala el menú y da Could I get...? como bloque entero. Tapa Help yourself hasta que aparezca la segunda porción." },
      stretch: { en: "Ask quick pairs to handle a generous aunt after ordering. They request the corrientazo, accept or refuse ¿le sirvo más?, and answer ¿ya comiste? at the doorway, not at the menu.", es: "Pide a parejas rápidas manejar una tía generosa después de pedir. Ordenan el lunch special, aceptan o rechazan Want some more?, y responden Did you eat? en la puerta, no en el menú." },
      errors: [
        { en: "They say \"Ordeno un corrientazo\", copying English in ordering, serving, and eating. Stop it with \"Pido un corrientazo\" because pedir, not ordenar, is the restaurant verb here. Put the repair above Ordeno un corrientazo, cross out the false words, and restart Bogotá corrientazo.", es: "Dicen \"ask the lunch special\" porque traducen desde el español en pedir, servir y comer. Cámbialo por \"Could I get the lunch special?\" y repasa could I get...?, porque el pedido suena natural como frase completa. Pon la reparación sobre ask the lunch special, tacha las palabras falsas y reinicia almuerzo del día." },
        { en: "Expect \"No como nothing\" when pressure rises in ordering, serving, and eating. The repair is \"Estoy lleno, gracias\" because the refusal should be simple and polite. Students repeat it with one new ordering, serving, and eating detail so it is not just copying.", es: "Espera \"serve yourself more\" cuando sube la presión en pedir, servir y comer. La reparación es \"Help yourself\", porque esa invitación deja que la persona tome comida. Repiten la línea con un detalle nuevo de pedir, servir y comer para que no sea copia." }
      ]
    }
  },
  "22-foundation-rest-and-play": {
    mission: { en: "Explain oversleeping, learn a game, and ask for help on the road without overcomplicating it.", es: "Explicar que te quedaste dormido, aprender un juego y pedir ayuda en el camino sin complicarte." },
    canDo: [
      { en: "Say you slept, fell asleep, or overslept", es: "Decir que dormiste, te dormiste o te quedaste dormido" },
      { en: "Use play for games but not for every instrument or touch", es: "Usar play para juegos sin aplicarlo a todo toque" },
      { en: "Ask someone to help you find or do something", es: "Pedir que alguien te ayude a encontrar o hacer algo" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Draw a missed boat, a tejo target, and a map to Pereira. Students tell the story with faces and arrows first. Keep me quedé dormido covered until they see the consequence clearly.", es: "Dibuja bus perdido, cancha de tejo y mapa a Pereira. Cuentan la historia con caras y flechas primero. Mantén I overslept tapado hasta que vean la consecuencia." },
      presentation: { en: "Put dormir, dormirse, and me quedé dormido on a timeline from normal night to accident. Then move to the tejo target and write jugar; put tocar only under the guitar joke so play does not fool them.", es: "Pon sleep, fall asleep y overslept en una línea de noche normal a accidente. Luego pasa a la cancha y escribe play tejo; pon play the guitar bajo la broma musical." },
      practice: { en: "Put alarm, tejo stone, guitar, and station map in a row. Students choose me quedé dormido for the missed boat, jugar for tejo, tocar for guitar, and ayudar a for the map.", es: "Pon alarma, cancha, guitarra y mapa en fila. Escogen I overslept para perder el bus, play tejo para el juego, play the guitar para música y help me find para la estación." },
      production: { en: "Tell one travel day. The learner oversleeps in Santa Marta, tries tejo in Santander, then asks for help in Pereira. Each stop allows one verb, so dormir cannot swallow the whole story.", es: "Cuenta un día de viaje. La persona overslept, aprende a play tejo y luego pide help me find en la estación. Cada parada permite una frase y evita mezclar todo." },
      exitTicket: { en: "Show the missed-boat card. Learners write Me quedé dormido or I overslept. You are checking accident meaning, not the whole travel story.", es: "Muestra la tarjeta del bus perdido. Escriben I overslept. Revisas accidente y despertar tarde, no toda la historia del viaje." },
      homework: { en: "Write a three-panel excuse: missed boat, tejo court, station favor. Use me quedé dormido only in the first panel, jugar at the court, and ayudar a encontrar at the station.", es: "Escriben una excusa en tres cuadros: bus perdido, cancha y favor en estación. Usan I overslept en el primero, play tejo en la cancha y help me find en la estación." },
      support: { en: "The hardest contrast is juego versus instrumento. Draw a tejo target and a guitar. Put jugar under the target and tocar under the guitar before adding the sleep problem.", es: "El contraste difícil no es largo: oversleep no es sleep over. Dibuja alarma tarde y cama ajena; el estudiante elige I overslept antes de pasar a play." },
      stretch: { en: "Let strong students add the guitar joke only after tejo works. They say juguemos for the court, tocar guitarra for the joke, then return to me quedé dormido when the boat leaves.", es: "Permite que estudiantes fuertes añadan la broma de guitarra solo después del tejo. Usan play tejo en cancha, play the guitar en la broma y vuelven a I overslept con el bus perdido." },
      errors: [
        { en: "They say \"Dormí and missed the boat\", copying English in sleep, play, and help. Stop it with \"Me quedé dormido\" because the problem is accidental oversleeping, not normal sleep. Put the repair above Dormí and missed the boat, cross out the false words, and restart Tayrona boat.", es: "Dicen \"I slept over for oversleeping\" porque traducen desde el español en sueño, juego y ayuda. Cámbialo por \"I overslept\" y repasa sleep, porque oversleep significa despertarse tarde. Pon la reparación sobre I slept over for oversleeping, tacha las palabras falsas y reinicia lancha a Tayrona." },
        { en: "Expect \"Juego guitarra\" when pressure rises in sleep, play, and help. The repair is \"Toco guitarra\" because Spanish separates playing a game from playing an instrument. Students repeat it with one new sleep, play, and help detail so it is not just copying.", es: "Espera \"help to me find\" cuando sube la presión en sueño, juego y ayuda. La reparación es \"help me find\", porque help lleva persona directa sin to. Repiten la línea con un detalle nuevo de sueño, juego y ayuda para que no sea copia." }
      ]
    }
  },
  "23-foundation-sorting-things-out": {
    mission: { en: "Look for the right thing, try a risky activity and change money while keeping the next step clear.", es: "Buscar lo que necesitas, intentar una actividad nueva y cambiar dinero manteniendo claro el siguiente paso." },
    canDo: [
      { en: "Describe the hat you are looking for in a small shop", es: "Describir el sombrero que buscas en una tienda pequeña" },
      { en: "Say you will try the kayak but need to go slowly", es: "Decir que intentarás el kayak pero necesitas ir despacio" },
      { en: "Ask for change and confirm coins before leaving", es: "Pedir cambio y confirmar monedas antes de salir" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Set a plain hat, a paddle and a large bill on the desk. Students choose which one they can ask for now. Their gaps tell you whether to begin with buscar, intentar or cambiar.", es: "Pon un sombrero sencillo, un paddle y un billete grande en la mesa. Eligen qué pueden pedir en inglés ahora. Sus vacíos te dicen si empezar con look for, try or change. Guarda \"looking\" hasta que lo pidan." },
      presentation: { en: "Begin inside the hat shop. Write Busco un sombrero sencillo and ask why no por appears. Then show the kayak line Quiero intentar, pero me da nervios as a different kind of trying. Keep the board anchored in buscar.", es: "Empieza en la tienda. Escribe I'm looking for a simple hat y pregunta qué hace for. Luego muestra I want to try, but I'm nervous, para separar buscar algo de intentar una acción." },
      practice: { en: "Give three baskets labeled object, action and money. Students place sombrero, salir en kayak and billete, then form one line with busco, intento or ¿me cambiás? The category chooses the verb. Let buscar carry the drill.", es: "Da tres canastas: thing, action y money. Colocan hat, head out in the kayak y bill, y luego forman una línea con look for, try to o change. La categoría decide la forma. La práctica gira en \"looking\"." },
      production: { en: "Turn the room into Taganga beach. The instructor keeps the first attempt small: try the paddle, then try to head out. Add nervousness and one safety question before anyone gets imaginary water time. Make buscar necessary in the scene.", es: "Convierte el salón en una playa. El instructor limita el primer intento: try the paddle y luego try to head out. Añade nervios y una pregunta de seguridad antes de la vuelta imaginaria. La escena debe necesitar \"looking\"." },
      exitTicket: { en: "Show I am looking ___ a hat and I am trying ___ paddle. Students fill for or nothing. This checks the English transfer that most damages buscar.", es: "Muestra I am looking ___ a hat y I am trying ___ paddle. Completan for o nada. Esta salida revisa la transferencia que más daña look for y try." },
      homework: { en: "Students write two errand lines for tomorrow: one thing they are looking for and one bill they need changed. The kayak sentence is optional only if they can include nervousness. Bring buscar back next class.", es: "Escriben dos mandados para mañana: una cosa they are looking for y un bill que necesitan change. La frase del kayak es opcional si incluye nervousness." },
      support: { en: "If buscar keeps gaining por, cover the English prompt and leave only the picture. Have the student say Busco plus the object three times, then uncover looking for and compare.", es: "Si search y look for se mezclan, tapa la traducción. Deja solo el dibujo del sombrero y dos opciones: search the shop, look for a hat. Eligen antes de escribir. Haz de \"looking\" el rescate." },
      stretch: { en: "Fast pairs get the bakery. They must ask for coins without buying anything, then add the shirt line me cambio la camiseta so cambiar clearly does two jobs. Push buscar into a new register.", es: "A los rápidos, dales la panadería. Deben pedir coins sin comprar y luego añadir I'll change my shirt para mostrar dos usos de change en una sola escena. Lleva \"looking\" a otro tono." },
      errors: [
        { en: "They ask \"busco por un sombrero\" because look for has for. Cross out por and repeat \"busco un sombrero\"; Spanish buscar already contains the search direction.", es: "Dicen \"I search a hat\". Escribe \"I'm looking for a simple hat\" al lado. Search necesita un lugar o una persona; look for sirve para el objeto que falta." },
        { en: "They say \"intento el remo\" when the instructor means a quick test. Contrast \"intento salir\" with \"pruebo el remo\"; intentar aims at an action, probar tests a thing.", es: "Dicen \"I try to the paddle.\" Divide el tablero: \"try the paddle\" para el objeto y \"try to head out\" para la acción. To aparece solo antes del verbo." }
      ]
    }
  },
  "24-developing-music-and-movement": {
    mission: { en: "Join music without pretending confidence: invite, sing badly, take a turn and protect the mood.", es: "Sumarte a la música sin fingir seguridad: invitar, cantar mal, tomar turno y cuidar el ambiente." },
    canDo: [
      { en: "Invite someone to dance and give them a graceful way out", es: "Invitar a bailar y darle a alguien una salida amable" },
      { en: "Joke about singing badly and still take the chorus", es: "Bromear sobre cantar mal y aun así tomar el coro" },
      { en: "Take a rehearsal turn and ask what you should bring", es: "Tomar un turno de ensayo y preguntar qué debes llevar" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Play the room as a wedding, but start silent. Students mime invitation, embarrassment and escape for water, then name any Spanish they already have. The gap prepares ¿Bailamos? without overexplaining dance culture.", es: "Haz que el salón sea una boda, pero empieza en silencio. Representan invitation, shyness y escape for water; luego nombran inglés que ya tengan. El vacío prepara Shall we dance? sin explicar demasiado." },
      presentation: { en: "Put ¿Bailamos o te da pena? beside the wedding picture. Ask which half invites and which half gives an exit. Later add yo canto bajito so students hear modesty, not refusal. Keep bodies moving.", es: "Pon Shall we dance, or are you shy? junto a la boda. Pregunta qué mitad invita y qué mitad deja salida. Después añade I'll sing quietly para mostrar modestia, no rechazo." },
      practice: { en: "Use call-and-response cards from karaoke. One student gives a push, le toca cantar; the other answers yo canto bajito or no respondo por los gallos. The answer must lower pressure, not kill the fun. Let bailamos carry the drill.", es: "Usa tarjetas de karaoke. Una persona empuja con It's your turn to sing; la otra responde I'll sing quietly o I can't promise. La respuesta debe bajar presión sin apagar el momento. La práctica gira en \"dance\"." },
      production: { en: "Move to joropo rehearsal. Assign a cuatro player, a cable warning and a key holder. Students must decide me toca abrir and still bring maracas, so tocar becomes turn-taking inside a real plan. Make bailamos necessary in the scene.", es: "Pasa al ensayo de joropo. Asigna quien plays the cuatro, quien says don't touch the cable y quien has the key. Deben decidir It's my turn y traer maracas dentro de un plan real. La escena debe necesitar \"dance\"." },
      exitTicket: { en: "Ask for the English of tocar el cuatro and me toca abrir in two separate boxes. If both become touch, the student stays for the three-sense repair. Check bailamos, not a list.", es: "Pide dos cajas: play the cuatro y it's my turn to open. Si ambas se vuelven touch, el estudiante hace una reparación corta de sentidos. Revisa \"dance\", no una lista." },
      homework: { en: "Students write a four-line party exchange: invite someone to dance, admit a weakness, accept a small role, and give one escape phrase. It should sound kind, not theatrical. Bring bailamos back next class.", es: "Escriben un intercambio de fiesta de cuatro líneas: Shall we dance, a shy answer, one singing role and one escape for water. Debe sonar amable, no actuado." },
      support: { en: "For support, remove the music vocabulary first. Give only ¿Bailamos? and two faces, eager and nervous. Once the invitation works, add champeta or karaoke as the changing detail.", es: "Para apoyo, quita primero el vocabulario musical. Da solo Shall we dance? con dos caras, eager y shy. Cuando funcione, agrega champeta o karaoke como detalle nuevo." },
      stretch: { en: "Challenge confident students with a person who says no. They must keep the mood warm, switch to karaoke or maracas, and use me toca without making the other person guilty. Push bailamos into a new register.", es: "Reta a quienes avanzan con alguien que says no. Deben cuidar el ánimo, cambiar a karaoke o maracas y usar It's my turn sin hacer sentir culpable al otro. Lleva \"dance\" a otro tono." },
      errors: [
        { en: "They invite with \"¿Quieres bailar conmigo?\" and sound heavier than the wedding. Put \"¿Bailamos?\" first; the shared we makes the invitation lighter and easier to refuse.", es: "Dicen \"Do you want dance?\" Falta to: \"Do you want to dance?\" Luego muestra \"Shall we dance?\" para una invitación más suave y menos insistente." },
        { en: "They read \"me toca abrir\" as touching a door. Place \"tocar el cuatro,\" \"no toqués,\" and \"me toca\" in three boxes; only the last means whose turn.", es: "Dicen \"I touch the cuatro.\" Corrige a \"I play the cuatro\" y reserva touch para el cable. El turno se dice \"It's my turn,\" no \"it touches me.\"" }
      ]
    }
  },
  "25-developing-getting-around-the-country": {
    mission: { en: "Move through the country by ticket, road and mountain truck while asking precise travel questions.", es: "Moverte por el país con tiquete, carretera y chiva mientras haces preguntas precisas de viaje." },
    canDo: [
      { en: "Buy a long-distance ticket and choose a useful seat", es: "Comprar un tiquete largo y escoger un puesto útil" },
      { en: "Discuss driving rules, licenses and road timing at a counter", es: "Hablar de reglas de conducción, licencia y ruta en un mostrador" },
      { en: "Get onto a rural vehicle and understand another meaning of ride", es: "Subirte a un vehículo rural y entender otro sentido de montar" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Draw a route from Armenia to Santa Marta and ask what students can already buy at a terminal. Keep the chiva photo covered. You want ticket and seat language before montar complicates the map. Hold viajar until students ask for it.", es: "Dibuja una ruta larga y pregunta qué pueden comprar ya in a bus station. Mantén tapada la foto de la chiva. Necesitas ticket y seat antes de que get on complique el mapa. Guarda \"travel\" hasta que lo pidan." },
      presentation: { en: "Start at the counter: Quiero viajar a Santa Marta esta noche. Add puesto 12 by drawing the bus. Only after seats are clear, introduce conducir with the license and pico y placa warning.", es: "Empieza en el mostrador: I want to travel to Corpus Christi tonight. Dibuja seat 12 en el bus. Después presenta drive con driver's license y plate rules, porque son otra parte del viaje." },
      practice: { en: "Students receive a ticket form with three blanks: destination, seat and departure time. They ask ¿A qué hora sale? and choose ventana or pasillo before one partner becomes the rental agent. Let viajar carry the drill.", es: "Entrega un formulario con tres espacios: destination, seat y leaving time. Preguntan What time does it leave? y piden window seat antes de pasar al mostrador de rental car. La práctica gira en \"travel\"." },
      production: { en: "Stage the Salento chiva boarding. The driver gives a safety warning, one tourist asks about montar un negocio, and a friend teases too much. Students must sort ride, set up and pick on. Make viajar necessary in the scene.", es: "Representa la subida a la chiva. La conductora dice hold on, alguien pregunta por set up a business y un amigo se burla. Deben separar get on, set up y pick on. La escena debe necesitar \"travel\"." },
      exitTicket: { en: "Give one travel line and one driving line. Students complete viajar a ___ and licencia de ___ without using manejar for the document. The check is small because the module is wide.", es: "Da una línea de viaje y una de carro. Completan travel by ___ y driver's ___ sin decir handle the car para la ruta. La salida es pequeña porque el módulo es amplio." },
      homework: { en: "Plan a two-leg trip on paper. Include a ticket question, a seat choice and one road rule. Add a separate chiva sentence only if the movement is get on, not drive. Bring viajar back next class.", es: "Planean un viaje de dos tramos. Incluyen ticket question, seat choice y una regla de driving. Agregan una frase de truck solo si el movimiento es get on, no drive. Traen \"travel\" de vuelta." },
      support: { en: "If students drown in transport words, give them a paper ticket first. They fill only destination and seat. Then add one spoken question: ¿A qué hora sale? Nothing else moves until that works. Make viajar the small rescue.", es: "Si se pierden con transport, empieza con un ticket de papel. Llenan solo destination y seat. Luego añaden What time does it leave? No agregues drive hasta que eso funcione. Haz de \"travel\" el rescate." },
      stretch: { en: "Ask fast students to explain pico y placa to a traveler who wants to leave now. They must give the restriction, offer a waiting plan and keep the tone formal. Push viajar into a new register.", es: "Quienes van rápido explican plate rules a alguien que quiere salir ya. Deben dar la restricción, proponer wait here y mantener tono de rental counter. Lleva \"travel\" a otro tono." },
      errors: [
        { en: "They say \"voy a hacer un viajar\" after seeing trip. Write \"viajar\" and \"hacer un viaje\" separately; one is the verb, the other is the noun package.", es: "Dicen \"I travel in bus.\" Pon \"I travel by bus\" y \"I take a bus\" en el tablero. By nombra el medio; take nombra el viaje concreto." },
        { en: "They treat conducir and manejar as always equal. In the license scene, keep \"licencia de conducción\" for the document and \"sé manejar\" for practical skill.", es: "Dicen \"I will handle to Big Bend.\" Cambia handle por drive para la ruta. Handle sirve para manejar un problema, no para conducir el carro en esta escena." }
      ]
    }
  },
  "26-foundation-kitchen-and-morning": {
    mission: { en: "Accept a drink, help cook a family pot, and wake up early enough to catch the bus.", es: "Aceptar una bebida, ayudar a cocinar una olla familiar y despertarte temprano para alcanzar el bus." },
    canDo: [
      { en: "Say what you want to drink after heat or work", es: "Decir qué quieres beber después del calor o trabajo" },
      { en: "Name simple cooking actions and dishes", es: "Nombrar acciones y platos simples de cocina" },
      { en: "Talk about alarms, waking up, and getting up early", es: "Hablar de alarmas, despertarse y madrugar" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Bring a cold cup, a soup pot, and an alarm drawing to separate tables. Students choose thirst, cooking, or morning by touching the object. Keep tomar algo covered until the cup is chosen.", es: "Trae vaso frío, olla y alarma dibujada a mesas separadas. Tocan thirst, cooking o morning según el objeto. Mantén something cold to drink oculto hasta que elijan el vaso." },
      presentation: { en: "Offer the cup first and write tomar algo beside agua de panela. Move to the pot for cocinar sancocho and hacer almuerzo. End at the alarm with me despierto, because morning language needs a clock.", es: "Ofrece el vaso y escribe something cold to drink junto a agua de panela. Pasa a la olla con cook sancocho y make lunch. Termina en la alarma con wake up." },
      practice: { en: "Bring a cup, pot, and alarm drawing. Students accept agua de panela with tomar algo, name cocinar sancocho at the pot, and use me despierto only when the alarm rings today early.", es: "Trae vaso, olla y alarma dibujada. Practican something cold to drink con el vaso, cook sancocho con la olla, y wake up cuando suena la alarma temprano." },
      production: { en: "Make Sunday morning on a finca. A host offers a drink after the sun, assigns sancocho jobs, and reminds everyone about the early bus. The exchange ends with madrugar, not another food order.", es: "Monta una mañana de finca. Ofrecen algo frío, reparten tareas para cook, y recuerdan el bus temprano. El intercambio termina con get up early, no con otro pedido." },
      exitTicket: { en: "Point to the alarm. Learners write Me despierto temprano or I wake up early. If they use cooking language, the morning scene has not landed.", es: "Señala la alarma. Escriben I wake up early. Si usan lenguaje de cocina, la escena de la mañana no quedó clara." },
      homework: { en: "Make a morning strip with three drawings: cold drink, cooking pot, alarm. Label them tomar algo, cocinar sancocho, and me despierto temprano; do not let drink language enter the pot.", es: "Hacen una tira de mañana con tres dibujos: bebida fría, olla y alarma. Escriben something cold to drink, cook sancocho y I wake up early; drink no entra en la olla." },
      support: { en: "Use two alarm cards. Despierto a mi amigo has another person on it; me despierto temprano has only the learner. Point to the picture before choosing the verb.", es: "Usa dos tarjetas de alarma. Wake up puede ser abrir los ojos; get up exige pies en el piso. El estudiante toca ojos o pies antes de completar la línea." },
      stretch: { en: "Have fast finishers run breakfast backward from the alarm. They wake up early, ask for something cold to drink, and help cook sancocho without using tomar for the pot.", es: "Haz que quienes terminan pronto organicen el desayuno desde la alarma hacia atrás. Se despiertan temprano, piden something cold to drink y cocinan sancocho sin usar drink para la olla." },
      errors: [
        { en: "They say \"Bebo un tinto for coffee\", copying English in drinks, cooking, and morning. Stop it with \"Tomo un tinto\" because Colombian Spanish often uses tomar for coffee. Put the repair above Bebo un tinto for coffee, cross out the false words, and restart Santa Marta agua de panela.", es: "Dicen \"take coffee\" porque traducen desde el español en bebidas, cocina y mañana. Cámbialo por \"drink coffee\" y repasa drink, porque take no nombra beber en esta escena. Pon la reparación sobre take coffee, tacha las palabras falsas y reinicia agua de panela." },
        { en: "Expect \"Despierto temprano\" when pressure rises in drinks, cooking, and morning. The repair is \"Me despierto temprano\" because waking yourself needs the reflexive form. Students repeat it with one new drinks, cooking, and morning detail so it is not just copying.", es: "Espera \"wake up from bed and leave\" cuando sube la presión en bebidas, cocina y mañana. La reparación es \"get up early\", porque get up marca levantarse, no solo abrir los ojos. Repiten la línea con un detalle nuevo de bebidas, cocina y mañana para que no sea copia." }
      ]
    }
  },
  "27-developing-moving-your-body": {
    mission: { en: "Suggest movement, respond to pressure and keep yourself safe when walking, running or swimming.", es: "Proponer movimiento, responder a presión y cuidarte al caminar, correr o nadar." },
    canDo: [
      { en: "Suggest a walk that sounds social rather than like a route", es: "Proponer una caminata que suene social y no como ruta" },
      { en: "Negotiate running pace and move something out of the way", es: "Negociar el ritmo al correr y mover algo del camino" },
      { en: "Explain swimming limits in a river setting", es: "Explicar límites al nadar en un río" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Put students on an imaginary Cartagena street after dinner. Ask for one suggestion that keeps the night open. If every answer sounds like tourism, the class needs dar una vuelta. Hold caminar until students ask for it.", es: "Ubica a todos en una calle después de cenar. Pide una sugerencia que deje la noche abierta. Si todo suena a tour, necesitan walk for a bit y wander around." },
      presentation: { en: "Write ¿Caminamos un rato? and Caminemos under the street scene. Ask why neither sounds like a route. Then contrast the vendor's camine, which pulls people toward earrings, not exercise. Keep the board anchored in caminar.", es: "Escribe Shall we walk for a bit? y Let's walk bajo la calle. Pregunta por qué no suenan a ruta turística. Luego contrasta Come on over, que atrae a la gente al puesto." },
      practice: { en: "Use three movement stations. At the first, students invite a walk; at the second, they set a running pace with corramos suave; at the third, they decide if the water da pie. Let caminar carry the drill.", es: "Trabaja en tres estaciones. En la primera invitan con walk; en la segunda ajustan ritmo con run easy; en la tercera deciden si can touch bottom. Cada estación tiene una respuesta correcta." },
      production: { en: "Run the Cali river path as a problem-solving jog. A chair blocks the way, the sun is getting strong, and one partner wants race pace. Students must move the chair and renegotiate speed. Make caminar necessary in the scene.", es: "Haz el trote por el río como problema real. Una chair bloquea el camino, el sol sube y alguien corre demasiado. Deben move the chair over y renegociar pace sin cortar el plan. La escena debe necesitar \"walk\"." },
      exitTicket: { en: "Show two pictures: a person jogging and a chair in the path. Students write correr for one and correr la silla for the other, proving they caught the extra meaning. Check caminar, not a list.", es: "Muestra dos dibujos: una persona running y una chair en el camino. Escriben run para uno y move the chair over para el otro. Así revisas el segundo sentido. Revisa \"walk\", no una lista." },
      homework: { en: "Students map a ten-minute walk from their week and write a two-line invitation for it. Then add one safety sentence from the river scene using corriente or da pie. Bring caminar back next class.", es: "Dibujan una caminata de diez minutos de su semana y escriben una invitación de dos líneas. Después añaden una frase de seguridad con current o touch bottom. Traen \"walk\" de vuelta." },
      support: { en: "For students stuck on caminar, remove the route map. Give two choices: ¿Caminamos un rato? and ¿Dónde queda? They choose social invitation or direction before speaking.", es: "Si walk, wander y run se cruzan, usa tres dibujos: stroll, race y blocked path. El estudiante apunta primero; después dice Let's walk o move this chair según el dibujo." },
      stretch: { en: "Ask early finishers to make the river warning respectful. They must tell an adult swimmer not to trust the calm water, using no se confíe without sounding like a scold. Push caminar into a new register.", es: "A los rápidos, pídeles una advertencia amable en el río. Deben usar don't get overconfident y get out if you feel the current sin sonar como regaño. Lleva \"walk\" a otro tono." },
      errors: [
        { en: "They answer a vendor with literal \"camine\" as if ordered to march. Show the earrings line and gloss \"cámine\" as \"come on over\" in that market voice.", es: "Dicen \"we make a walk\" porque piensan en dar una vuelta. Escribe \"Let's walk\" and \"wander around\"; English does not need make there." },
        { en: "They say \"nado bueno\" at the river. Put \"nado bien\" under the subject and mark bien as the word for how the action is done.", es: "Dicen \"I swim good.\" Cambia good por well in \"I swim well.\" Good describes a noun; well describes the swimming." }
      ]
    }
  },
  "28-developing-winning-losing-choosing": {
    mission: { en: "Talk about results, losses and choices without bragging, panicking or sounding politically vague in public.", es: "Hablar de resultados, pérdidas y elecciones sin alardear, entrar en pánico ni sonar vago." },
    canDo: [
      { en: "Say who won and who earned respect without gloating", es: "Decir quién ganó y quién se ganó respeto sin presumir" },
      { en: "Explain a missed bus, lost ID and wasted time", es: "Explicar un bus perdido, una cédula perdida y tiempo desperdiciado" },
      { en: "Choose a candidate and give one reason for the choice", es: "Elegir un candidato y dar una razón de la elección" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Put a scoreboard, an ID card and a ballot on the board. Students say one sentence for each. Listen for whether ganar does too much work before you introduce earned respect. Add one reason.", es: "Pon un marcador, an ID card y una papeleta. Piden una frase para cada imagen. Escucha si win hace demasiado trabajo antes de enseñar earn, miss y choose. Guarda \"earned\" hasta que lo pidan." },
      presentation: { en: "Begin with the soccer tertulia: hoy ganamos bien. Then add se ganó el respeto and ganar plata in smaller writing. Ask which one is a result and which one is deserved over time.", es: "Empieza con we won fair en la charla de fútbol. Luego escribe the coach earned respect y earn money. Pregunta cuál habla del partido y cuál de lo que se merece o recibe." },
      practice: { en: "Students sort nine cards under partido, cédula and candidato. They must use perder el bus, se me perdió and elegir with the right column, then explain one choice. Let ganar carry the drill. Require a reason.", es: "Clasifican nueve tarjetas bajo match, ID y candidate. Deben escoger won, earned, lost, missed, choose o elect según la columna. La explicación breve vale más que llenar rápido." },
      production: { en: "Act out the Bucaramanga mess before the appointment. The ID vanishes, the bus leaves, and a cousin wants to blame someone. Students report the facts without making everything sound lost. Make ganar necessary in the scene.", es: "Representa el enredo antes de la cita. The ID is lost, the bus is missed y el tiempo se pierde. Deben explicar el problema sin usar lose para todo. La escena debe necesitar \"earned\"." },
      exitTicket: { en: "Give two stems: se me ___ la cédula and ___ el bus. Students choose perdió and perdí, then translate the bus line as missed, not lost. Check ganar, not a list.", es: "Entrega dos espacios: I ___ my ID y I ___ the bus. Deben escribir lost y missed. Esa diferencia decide si pueden contar la emergencia. Revisa \"earned\", no una lista." },
      homework: { en: "Students write a sports or school result from their life. Require one line for winning and one for earning or passing, so ganar stops being a single English bucket.", es: "Escriben un resultado de deporte o estudio. Debe haber una línea con win y otra con earn o pass, para que ganar no sea una sola caja. Traen \"earned\" de vuelta." },
      support: { en: "If everything becomes ganar, place three labels on the desk: match, money, respect. Students put ganamos, gana plata and se ganó respeto under the right label before building sentences.", es: "Si todo sale como win, usa tres etiquetas: game, money y respect. El estudiante coloca won, earns y earned respect antes de escribir. La columna decide el verbo." },
      stretch: { en: "Fast pairs hold the Pereira meeting. They compare two candidates, use elegir and votar por separately, and make one polite challenge about propaganda or accountability. Push ganar into a new register.", es: "Los rápidos hacen una reunión vecinal. Comparan dos candidates, separan choose, pick, elect y vote for, y añaden una pregunta sobre accountability. Lleva \"earned\" a otro tono." },
      errors: [
        { en: "They use ganar for everything and say \"ganó respeto\" like a trophy. Add \"se ganó el respeto\"; the reflexive shows respect was earned over time.", es: "Dicen \"we earned the match.\" Escribe \"we won the match\" y \"the coach earned respect\" en dos columnas. Los partidos se ganan; el dinero y el respeto se ganan con trabajo." },
        { en: "They say \"perdí el bus\" correctly but then \"me perdí la cédula.\" Keep \"se me perdió la cédula\" for the missing thing and \"me perdí\" for a person lost in streets.", es: "Dicen \"I lost the bus.\" Cámbialo a \"I missed the bus\". Lose sirve para la cédula; miss sirve para buses, citas y oportunidades que no alcanzaste." }
      ]
    }
  },
  "29-developing-sending-and-sharing": {
    mission: { en: "Send, receive, share and route objects to the right person when one errand has too many moving parts.", es: "Enviar, recibir, compartir y mandar objetos a la persona correcta cuando un mandado tiene demasiadas piezas." },
    canDo: [
      { en: "Send an envelope with tracking and confirm the receipt", es: "Enviar un sobre con guía y confirmar el comprobante" },
      { en: "Meet someone, receive a package and ask whether cards are accepted", es: "Recibir a alguien, recoger un paquete y preguntar si aceptan tarjeta" },
      { en: "Share a link with context and place object pronouns correctly", es: "Compartir un enlace con contexto y ubicar bien los pronombres de objeto" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Bring an envelope, a package notice and a phone message to the desk. Students decide which one leaves, which arrives and which gets shared. Their choices expose the pronoun problem early. Hold enviar until students ask for it.", es: "Trae un envelope, un aviso de package y un mensaje de phone. Deciden qué se envía, qué se recoge y qué se comparte. Así aparece temprano el problema de send it to me." },
      presentation: { en: "Start at Servientrega with Necesito enviar este sobre. Write guía beside the envelope, not as abstract vocabulary. Then move to te lo mando ya and show where te and lo sit. Point to both.", es: "Empieza en el mostrador con I need to send this envelope. Pon tracking junto al sobre. Después pasa a send it to me y marca el orden, porque ahí se rompe el inglés." },
      practice: { en: "Give students a messy family chat. They underline the object, circle the receiver and choose te lo mando, se lo reenvío or mándamelo. Every answer must point to two people or things. Let enviar carry the drill.", es: "Entrega un chat familiar enredado. Subrayan el objeto, encierran quién recibe y eligen send it to me, send it back o forward it to them. Cada respuesta debe mostrar dos lugares." },
      production: { en: "Run the Cúcuta arrival. One person meets the traveler, another receives the package, and the café card machine fails. Students must keep recibir for each event without losing the errand thread. Make enviar necessary in the scene.", es: "Haz la llegada a Cúcuta. Una persona meets the traveler, otra picks up the package y falla el card machine. Deben usar meet, receive y take cards según el evento. La escena debe necesitar \"send\"." },
      exitTicket: { en: "Ask students to repair mando lo ya. They write lo mando ya and then one command, mándamelo. This tiny check catches the pronoun placement that blocks the whole chat. Check enviar, not a list.", es: "Pide reparar send me it. Escriben send it to me y luego send it back. Esta salida revisa el orden que más bloquea el chat familiar." },
      homework: { en: "Students write a real text message about sending one document or photo. It must include who gets it and by when. Pronouns are allowed only if the noun appeared first. Bring enviar back next class.", es: "Escriben un mensaje real sobre sending one file or photo. Debe decir who gets it y by when. Pueden usar it solo después de nombrar el objeto." },
      support: { en: "For support, use colored cards: blue for the thing, yellow for the person. Build te lo mando physically before writing it. The colors carry the grammar until the student can. Make enviar the small rescue.", es: "Para apoyo, usa tarjetas de color: azul para thing, amarillo para person. Arman send it to me físicamente antes de escribir. El color sostiene el orden." },
      stretch: { en: "Early finishers add failure: the chat drops, the receipt photo is blurry, or the card machine fails. They must reroute the object and explain the new plan clearly. Push enviar into a new register.", es: "Quienes terminan pronto agregan falla: chat caído, receipt borroso o card machine dañado. Deben reroute the file y explicar el plan nuevo sin perder a la persona que recibe. Lleva \"send\" a otro tono." },
      errors: [
        { en: "They put the pronoun at the end: \"mando lo ya.\" Move it before the conjugated verb: \"lo mando ya\"; then show \"mándamelo\" only for the command.", es: "Dicen \"send me it\" en el chat familiar. Sustitúyelo por \"send it to me\" y márcalo como el orden más seguro cuando aparecen dos objetos." },
        { en: "They use recibir for both the package and the friend at the terminal. Keep \"te vine a recibir\" for meeting a person and \"recibir un paquete\" for the thing.", es: "Dicen \"I will receive you at the station.\" Muestra \"I'll meet you at the station\". Receive suena a paquete o visita formal, no a amiga en llegadas." }
      ]
    }
  },
  "30-developing-keeping-house": {
    mission: { en: "Keep a borrowed or shared home working by cleaning, washing and fixing what affects other people.", es: "Mantener una casa compartida funcionando al limpiar, lavar y arreglar lo que afecta a otros." },
    canDo: [
      { en: "Divide cleaning jobs before guests arrive", es: "Repartir tareas de aseo antes de que lleguen invitados" },
      { en: "Explain laundry needs and ask when clothes will be ready", es: "Explicar necesidades de lavandería y preguntar cuándo estará la ropa" },
      { en: "Call about a repair and also sort out the evening plan", es: "Llamar por un arreglo y cuadrar el plan de la noche" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Scatter three drawings: sandy floor, damp clothes, broken hinge. Ask what students would actually do first in a borrowed house. Their answers separate cleaning, washing and fixing needs. Hold limpiar until students ask for it. Name the room.", es: "Reparte tres dibujos: sand on the floor, damp clothes y broken hinge. Pregunta qué harían primero en una casa prestada. Sus respuestas separan clean, wash y fix." },
      presentation: { en: "Use the beach house first. Write hagamos aseo over the whole room and limpio los vidrios over one task. The distinction matters before the laundromat line se la lavamos appears. Keep the board anchored in limpiar.", es: "Empieza con la casa. Escribe let's clean para el cuarto entero y clean the windows para una tarea. Luego presenta we'll wash them en lavandería, porque wash necesita otro contexto." },
      practice: { en: "Students receive job tickets from the house: windows, floor, clothes, sneakers, hinge. They choose limpiar, lavar or arreglar, then add one object pronoun only where the original dialogue requires it. Say who benefits.", es: "Da tiquetes de tareas: windows, floor, clothes, sneakers y hinge. Eligen clean, wash o fix, y añaden for you solo en lavandería. No todo problema de casa usa el mismo verbo." },
      production: { en: "Stage the Pereira repair call. The closet door fails before a guest arrives, and the caller still has to get ready. Students ask the price, send a photo and arrange the visit. Make limpiar necessary in the scene.", es: "Representa la llamada de reparación. La puerta no cierra antes de que llegue un invitado, y alguien must get ready. Deben ask the price, send a photo y set the time. La escena debe necesitar \"clean\"." },
      exitTicket: { en: "Show la sala and la ropa. Students choose hago aseo or lavo for each. If they use lavar for the living room, send them back to the house picture. Check limpiar, not a list.", es: "Muestra living room y clothes. Escogen clean o wash para cada una. Si usan wash para el cuarto, vuelven al dibujo y nombran qué toca limpiar." },
      homework: { en: "Students list three real house tasks. One must be cleaning a surface, one washing something, and one fixing or arranging a plan. They write who will do each. Bring limpiar back next class.", es: "Hacen una lista de tres tareas reales: clean a surface, wash something y fix or arrange a plan. Escriben quién hará cada una y cuándo." },
      support: { en: "If a student uses one verb for the whole house, hand them water, cloth and tool icons. They match the icon first, then say limpiar, lavar or arreglar with the noun.", es: "Si un estudiante usa clean para todo, dale íconos de water, cloth y tool. Empareja el ícono antes de decir wash, clean o fix con el objeto." },
      stretch: { en: "Ask fast students to combine the hinge and the social plan. They must use arreglar once for the door and once for the evening, making the listener understand both. Push limpiar into a new register.", es: "A los rápidos, pídeles mezclar repair y plan. Usan fix para la bisagra y sort out para la salida, y explican por qué arrange no arregla la puerta. Lleva \"clean\" a otro tono." },
      errors: [
        { en: "They say \"lavo la sala\" for the whole room. Put \"hago aseo\" above the room and \"lavo la ropa\" above clothes; lavar needs water or dishes.", es: "Dicen \"make cleaning\". Escribe \"clean the living room\" y \"do the cleaning\". Make no carga la tarea de la casa en inglés." },
        { en: "They drop the double pronoun in \"se la lavamos.\" Draw the clothes as la ropa and the client as le becoming se; the laundry line needs both.", es: "Dicen \"we wash it you.\" Cámbialo a \"we'll wash them for you\". El inglés usa for you en vez de amontonar pronombres de objeto." }
      ]
    }
  },
  "31-developing-body-and-routine": {
    mission: { en: "Move bodies through the day: get up, sit down, give a seat and dress for the place.", es: "Mover el cuerpo durante el día: levantarte, sentarte, ceder puesto y vestirte para el lugar." },
    canDo: [
      { en: "Get up for transport and signal the bus clearly", es: "Levantarte para el transporte y señalar el bus" },
      { en: "Offer a seat and choose where to sit", es: "Ofrecer un puesto y escoger dónde sentarte" },
      { en: "Ask what to wear and explain what looks good", es: "Preguntar qué ponerte y explicar qué se ve bien" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Begin with an alarm, a workshop chair and festival clothes. Students give commands they already know. Notice whether they tell themselves to get up or accidentally lift an object. Hold levantarse until students ask for it.", es: "Empieza con alarm, workshop chair y festival clothes. Dan órdenes que ya conozcan. Observa si dicen get up, sit down y wear, o si mezclan lift, seat y dress." },
      presentation: { en: "Put levántate ya next to ya me levanté. Have students touch their own chest for the reflexive. Then contrast levanta la mano so they feel the difference between body and object. Keep the board anchored in levantarse.", es: "Escribe get up now junto a I'm up. Pregunta por qué no aparece myself. Luego contrasta raise your hand para mostrar que lift o raise sí toma un objeto." },
      practice: { en: "Use chairs for the Pasto workshop. Students must seat an older woman, then sit themselves. Say sentar a la señora while moving the chair, and me siento aquí only after choosing their place. Let levantarse carry the drill.", es: "Usa sillas para el taller. Deben seat an older woman y luego sit down. Dicen Please sit here para ofrecer puesto, y I'll sit here solo cuando escogen su propia silla. La práctica gira en \"get\"." },
      production: { en: "Move to the Yopal festival. A cousin lends a light shirt, a child needs help dressing, and the bus time is close. Students solve clothing and departure without one long clothing list. Make levantarse necessary in the scene.", es: "Pasa al festival. Alguien presta a light shirt, un niño needs dressing y se acerca la hora del bus. Deben usar get dressed, dress the baby y wear comfortable shoes." },
      exitTicket: { en: "Ask for two mini-lines: I get up early and I raise my hand. Students translate both into Spanish, proving levantar and levantarse are not the same action.", es: "Pide dos líneas pequeñas: I sit here y I seat the older lady. Deben escoger sit o seat. Esta salida revela si el objeto está claro. Revisa \"get\", no una lista." },
      homework: { en: "Students write tomorrow morning in four steps: wake, get up, get dressed and leave. Add one public-space line offering a seat to someone who needs it. Bring levantarse back next class.", es: "Escriben la mañana de mañana en cuatro pasos: wake, get up, get dressed and leave. Añaden una línea de espacio público con Please sit here." },
      support: { en: "For support, use the student's body. They stand for me levanto, raise a hand for levanto la mano, and move a chair for siento a alguien. Then write only one line. Make levantarse the small rescue.", es: "Para apoyo, usa el cuerpo. Se paran para get up, levantan la mano para raise your hand y mueven una silla para seat someone. Después escriben solo una línea." },
      stretch: { en: "Fast students handle politeness at the workshop. They arrive late, offer a chair to an older participant and explain where they will sit without sounding heroic. Push levantarse into a new register.", es: "Los rápidos trabajan la cortesía del taller. Llegan tarde, ofrecen seat a una persona mayor y explican dónde they'll sit sin hacerse protagonistas. Lleva \"get\" a otro tono." },
      errors: [
        { en: "They say \"levanto temprano\" and leave out themselves. Add se or me: \"me levanto temprano.\" Without the reflexive, levantar means lift something else.", es: "Dicen \"I am up me\". Pon \"I'm up\" en el tablero y pregunta qué sobra. En inglés no hace falta myself para levantarse de la cama. Repite get up una vez. Conecta dressed después." },
        { en: "They use sentar for their own chair: \"sento aquí.\" Contrast \"siento a la señora\" with \"me siento aquí\"; one seats someone, one sits down.", es: "Dicen \"I seat here.\" Cámbialo a \"I sit here\". Seat necesita otra persona o una forma pasiva, como \"everyone is seated.\"" }
      ]
    }
  },
  "32-developing-likes-and-dislikes": {
    mission: { en: "Say what attracts you, what you prefer and what you dislike strongly without insulting the people around you.", es: "Decir qué te atrae, qué prefieres y qué te disgusta mucho sin insultar a quienes te rodean." },
    canDo: [
      { en: "Name festival things you like and clarify romantic interest", es: "Nombrar cosas del festival que te gustan y aclarar interés romántico" },
      { en: "Choose shade or stage seats and soften the preference", es: "Escoger sombra o escenario y suavizar la preferencia" },
      { en: "Express dislike without using hate for every annoyance", es: "Expresar disgusto sin usar odio para cualquier molestia" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Show a float, a shady tree and a loud speaker. Students rank them silently, then explain one choice. You are listening for whether they can separate liking, preference and strong dislike. Hold gustar until students ask for it.", es: "Muestra una sculpture, un árbol con sombra y un speaker fuerte. Ordenan en silencio y explican una elección. Escucha si separan like, prefer y really don't like." },
      presentation: { en: "Start with me gusta la música and me gustan las carrozas. Put the liked thing in a box and make it control the verb. Only then add me cae bien for Daniel. Keep the board anchored in gustar.", es: "Empieza con I like the music y I like the sculptures more. Encierra el objeto que gusta y mueve more al final. Después añade I think he's nice para separar gusto romántico de simpatía." },
      practice: { en: "Students get singular and plural festival cards. They build me gusta or me gustan, then choose prefiero for shade decisions. Keep odiar off the table until softer dislike works. Let gustar carry the drill.", es: "Da tarjetas de festival singular y plural. Construyen I like it o I like them, luego usan I prefer para elegir sombra. Deja hate fuera hasta que really don't like funcione." },
      production: { en: "Run the Quibdó sound check. One student likes the music, one cannot stand the volume, and one dislikes a neighbor's behavior. They must protect people while naming the problem. Make gustar necessary in the scene.", es: "Haz el sound check. A uno le gusta la música, otro can't stand the volume y otro says the neighbor rubs me the wrong way. Deben quejarse sin atacar a la persona. La escena debe necesitar \"like\"." },
      exitTicket: { en: "Give two prompts: una carroza and varias carrozas. Students write me gusta or me gustan. This tiny check tells you whether the backwards agreement landed. Check gustar, not a list.", es: "Da dos prompts: the sculpture y the sculptures. Escriben I like it o I like them, y luego una frase con I prefer. Revisa objeto y orden." },
      homework: { en: "Students write three real preferences for an event: one thing they like, one seat they prefer and one sound or behavior they dislike softly. Ban odio unless it is truly strong. Bring gustar back next class.", es: "Escriben tres preferencias reales: something I like, a seat I prefer y one thing I really don't like. No usan hate si solo es molestia." },
      support: { en: "If gustar reverses, put the student on the left and the float on the right. The arrow points from float to person. Change only the float from singular to plural.", es: "Si like more sale en orden español, usa flechas. La cosa queda después de like, y more va al final. Practican primero I like the sculptures more." },
      stretch: { en: "Early finishers make a tactful complaint to the rehearsal organizer. They must avoid odio, use no me llama la atención or no soporto, and suggest one practical fix. Push gustar into a new register.", es: "A los rápidos, dales una queja diplomática. Deben evitar hate, usar really don't like o doesn't appeal to me, y proponer bajar el volumen o cambiar de puesto." },
      errors: [
        { en: "They write \"yo gusto las carrozas.\" Put \"me gustan las carrozas\" beside a plural drawing; the floats are the subject, so gustan changes.", es: "Dicen \"I like more the sculptures.\" Mueve more después del objeto: \"I like the sculptures more.\" En inglés la cosa queda junta antes de comparar." },
        { en: "They use odio for loud volume. Write \"no me gusta nada este volumen\" first and save \"odio\" for a real strong feeling; the softer phrase protects the room.", es: "Dicen \"I hate the volume\" por una molestia leve. Ofrece \"I really don't like this volume\"; hate es más fuerte y puede sonar personal." }
      ]
    }
  },
  "33-developing-explaining-and-showing": {
    mission: { en: "Handle moments when people do not understand by explaining causes, showing details, and identifying exactly which thing you mean.", es: "Manejar momentos en que alguien no entiende, explicando causas, mostrando detalles e identificando exactamente a qué cosa te refieres." },
    canDo: [
      { en: "Explain why a route changed and repeat only the point the other person needs", es: "Explicar por qué cambió una ruta y repetir solo el punto necesario" },
      { en: "Ask to see a bag or part and describe its shape, use, and difference", es: "Pedir que te muestren una mochila o pieza y describir forma, uso y diferencia" },
      { en: "Identify the right phone, person, or object with a short relative clause", es: "Identificar el teléfono, la persona o el objeto correcto con una cláusula breve" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Set the room up as the Neiva bus stop after rain. One student missed the driver, one understood half, and one is waiting at another corner. Ask what words they already have for cause, route, and which object. The gap is a listener who needs the route made clear. Hold explícame back until confusion is real.", es: "Monta el salón como el paradero de Neiva después de lluvia. Una persona no oyó al conductor, otra entendió a medias y otra espera en otra esquina. Pregunta qué inglés tienen para cause, route y which object. El hueco es un oyente que necesita la ruta clara." },
      presentation: { en: "Use the first detour line for explícame, then add te explico only after learners name who needs the help. Put the pronoun in another color and ask why the explanation feels unfinished without it. The pronoun shows who the explanation is for.", es: "Usa la primera línea del desvío con explain to me, luego agrega let me explain cuando nombren quién necesita ayuda. Escribe to me en otro color y pregunta por qué explain me falla. To me muestra quién recibe la explicación." },
      practice: { en: "Give pairs three trays from the Florencia counter and two backpack requests from Pasto. They choose between que, el que, and ¿me muestra? for each card, then justify the choice with object, person, or description. A vague phone description must keep the tray locked.", es: "Da tres bandejas del mostrador de Florencia y dos pedidos de mochila de Pasto. Escogen entre that, which y could you show me para cada tarjeta, y justifican con objeto, persona o descripción. Una descripción vaga debe dejar bloqueada la bandeja." },
      production: { en: "Run a repair-counter scene with four similar phones. The clerk refuses vague descriptions, so the customer must identify the phone, explain the repair history, and negotiate release without touching the wrong tray. No phone leaves the counter until the relative clause identifies it. Use el que to unlock the correct tray. Say celular que traje before any release.", es: "Haz una escena de mostrador con cuatro celulares parecidos. El empleado rechaza descripciones vagas; el cliente debe identificar el teléfono, explicar la reparación y negociar la entrega sin tocar la bandeja equivocada. Ningún teléfono sale hasta que that or which lo identifique." },
      exitTicket: { en: "Ask for one sentence that tells Paula the detour using le expliqué. Under it, learners write who receives the explanation and what information can be safely left out. Paula must receive the summary, not the whole bus story.", es: "Pide una oración que cuente a Paula el desvío con explained it to her. Debajo, escriben quién recibe la explicación y qué información puede omitirse sin perder claridad. Paula recibe el resumen, no toda la historia del bus." },
      homework: { en: "Choose either the Pasto backpack or the Leticia clamp. Write eight lines in which the seller guesses wrong twice, then the buyer fixes the problem by shape, use, and comparison. The seller should guess wrong until shape and use are precise. Let descríbamela solve the unknown clamp.", es: "Escoge la mochila de Pasto o la abrazadera de Leticia. Escribe ocho líneas en inglés donde el vendedor se equivoca dos veces y el comprador corrige con shape, use y comparison. El vendedor debe equivocarse hasta que shape y use sean precisos." },
      support: { en: "For descríbamela, cover the noun and give three prompts: shape, job, and like another thing. The stuck learner speaks from the prompts before trying the full sentence with the clerk. Keep the noun covered until shape and use produce descríbamela.", es: "Para describe it, tapa el nombre del objeto y entrega tres pistas: shape, job y like another thing. El estudiante bloqueado habla desde esas pistas antes de intentar la frase completa. Mantén tapado el sustantivo hasta que describe it salga por función y forma." },
      stretch: { en: "Give early finishers a phone that belongs to someone else’s cousin. They must use cuyo or whose to prevent the clerk from releasing the wrong device, then defend the decision. Cuyo matters because ownership prevents the wrong repair release.", es: "Da a los adelantados un teléfono que pertenece al primo de otra persona. Deben usar whose para impedir que entreguen el aparato equivocado y luego defender la decisión. Whose importa porque la propiedad evita entregar el celular equivocado." },
      errors: [
        { en: "They write \"¿Me explica por qué?\". Replace it with \"Explícame por qué.\". For tú, attach me to the command and keep the accent; otherwise the request sounds like a formal fragment.", es: "Cuando alguien dice \"Explain me why\", no lo corrijas con traducción. Pon \"Explain to me why\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"El celular quien traje ayer\". Replace it with \"El celular que traje ayer\". Use que for the phone. Quien is for people, not objects waiting in repair trays.", es: "Si aparece \"The phone who I brought yesterday\", detén la ronda y escribe \"The phone I brought yesterday\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "34-developing-invitations": {
    mission: { en: "Accept, offer and refuse invitations in a way that keeps generosity clear and relationships warm.", es: "Aceptar, ofrecer y rechazar invitaciones dejando clara la generosidad y cuidando la relación." },
    canDo: [
      { en: "Understand when an invitation means the other person pays", es: "Entender cuándo una invitación significa que la otra persona paga" },
      { en: "Accept food or drink without waiting for repeated pressure", es: "Aceptar comida o bebida sin esperar que insistan" },
      { en: "Refuse a plan softly and leave the next occasion open", es: "Rechazar un plan con suavidad y dejar abierta la próxima ocasión" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Ask who pays when a friend says I invite you. Let students argue briefly, then reveal Carolina's tinto. The point is generosity, not the dictionary meaning of invitar. Keep the debate brief.", es: "Pregunta quién paga si alguien dice I invite you. Deja una discusión corta y muestra el café de Carolina. El punto es distinguir invite, treat y It's on me." },
      presentation: { en: "Write te invito a un tinto beside va por mi cuenta. Ask which words prove money is included. Then add acepto con mucho gusto so students see acceptance without waiting for pressure. Keep the board anchored in invitar.", es: "Escribe It's on me junto a I'll buy you a coffee. Pregunta cuál paga el café. Después añade Yes, please y I'd love some para aceptar sin esperar que la otra persona insista. Ancla el tablero en \"invite\"." },
      practice: { en: "Use three invitation cards: coffee, snacks and birthday. Students choose invito, acepto or me queda difícil. Each answer must preserve warmth; reject cold lines even when grammar is correct. Let invitar carry the drill.", es: "Usa tres tarjetas: coffee, snacks y gig. Escogen It's on me, Yes please o I can't make it. Cada respuesta debe cuidar la relación; una frase fría no pasa solo por ser correcta. La práctica gira en \"invite\"." },
      production: { en: "Stage Popayán snacks. Doña Marta offers champús once, not three times. Students must accept or refuse immediately and politely, then explain why waiting for insistence misreads the scene. Make invitar necessary in the scene. No second offer.", es: "Representa la merienda. La anfitriona ofrece tea and cookies una vez, no tres. Deben aceptar con Yes, please o rechazar con No, thank you sin esperar presión. La escena debe necesitar \"invite\"." },
      exitTicket: { en: "Give the bad refusal rechazo tu invitación. Students rewrite it as no puedo or de pronto la próxima. The check is tone, because the grammar alone can still hurt. Check invitar, not a list.", es: "Da la frase mala I reject your invitation. La cambian por I can't make it o Maybe next time. La salida revisa tono, no solo gramática. Revisa \"invite\", no una lista." },
      homework: { en: "Students write two invitations from their week: one they pay for and one they cannot accept. They must include the money clue in the first and a warm door open in the second. Bring invitar back next class.", es: "Escriben dos invitaciones reales: una que pagan y una que no aceptan. La primera usa It's on me o I'll get this; la segunda deja abierta una próxima vez. Traen \"invite\" de vuelta." },
      support: { en: "For support, separate invitation from payment with two icons: calendar and coin. Put invitar under the calendar first, then add yo invito only when the coin is visible.", es: "Para apoyo, separa event y payment con dos dibujos. Invite va con calendario; It's on me va con moneda. El estudiante señala el dibujo antes de contestar." },
      stretch: { en: "Give fast students ahí te cuento. They decide when it is a useful soft maybe and when it becomes dishonest. Then they write a clearer refusal for Lucía's birthday. Push invitar into a new register.", es: "A los rápidos, dales I'll let you know. Deciden cuándo sirve y cuándo suena evasivo. Luego escriben una negativa más clara para el gig. Lleva \"invite\" a otro tono." },
      errors: [
        { en: "They hear \"te invito\" and only understand come along. Put \"va por mi cuenta\" beside it; in this coffee scene, invitar means the speaker pays.", es: "Dicen \"I invite you a coffee.\" Cámbialo por \"I'll buy you a coffee\" o \"It's on me\". Invite sirve para el evento, no para pagar." },
        { en: "They refuse with \"rechazo tu invitación\" and freeze the birthday mood. Give them \"uy, no puedo\" and \"de pronto la próxima\"; the no stays warm.", es: "Dicen \"I reject your invitation.\" Pon \"I can't make it\" debajo y pregunta cuál cuida a la persona. Reject suena como rechazar la relación." }
      ]
    }
  },
  "35-developing-deciding-and-getting": {
    mission: { en: "Move a shared plan forward by choosing, getting what is missing, offering help, and naming the condition that decides it.", es: "Hacer avanzar un plan compartido, escogiendo, consiguiendo lo que falta, ofreciendo ayuda y nombrando la condición que decide." },
    canDo: [
      { en: "Choose between real options and explain what finally decides the plan", es: "Escoger entre opciones reales y explicar qué decide finalmente el plan" },
      { en: "Find or offer something useful without sounding pushy or vague", es: "Conseguir u ofrecer algo útil sin sonar intenso ni vago" },
      { en: "State what will happen if a payment, time, or weather condition holds", es: "Decir qué pasará si se cumple un pago, un horario o una condición del clima" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Draw the Neiva afternoon as three doors: river, movie, staying inside. Students rank them for heat, money, and energy using language they already know before decidir appears. The heat should make indecision feel costly.", es: "Dibuja la tarde en Neiva como tres puertas: río, cine y quedarse adentro. Ordenan las opciones por heat, money y energy con inglés conocido antes de ver make up your mind. El calor debe hacer costosa la indecisión." },
      presentation: { en: "Put no me decido beside me decidí por el río. Ask where the stuck moment ends and the choice begins. Add consigo from the charger scene only after the class separates choosing from obtaining. Choice and obtaining stay separate on the board.", es: "Pon I can’t make up my mind junto a I decided on the river. Pregunta dónde termina la duda. Agrega get hold of desde el cargador cuando separen choice de obtaining. Choice y obtaining quedan separados en el tablero." },
      practice: { en: "Use a shop map of Pasto with stationery store, pharmacy, and phone kiosk. Learners complete charger questions with consigo or conseguí, then reject one place because it cannot solve Alex’s problem. The wrong shop must not count as getting the charger.", es: "Usa un mapa de Pasto con papelería, farmacia y puesto de celulares. Completan preguntas con can get o managed to get, luego descartan un lugar porque no resuelve el problema. La tienda equivocada no cuenta como getting the charger." },
      production: { en: "Stage the Leticia boat boarding. One passenger has bags, one has a reservation worry, and one controls the seats. The group must offer help and still decide whether the cabin deposit happens before noon. A seat offer changes the cabin decision only if someone accepts. Let le ofrezco change who sits.", es: "Representa el embarque en Leticia. Una persona lleva bolsas, otra se preocupa por la reserva y otra maneja los asientos. Ofrecen ayuda y deciden si el depósito se paga antes del mediodía. La oferta de asiento cambia la reserva solo si alguien acepta." },
      exitTicket: { en: "Collect one real conditional about the cabin: si pagas before noon plus the result. Reject any sentence that puts future tense inside the si clause. The cabin is held only through a clean si clause.", es: "Recoge una condición real sobre la habitación: if you pay before noon más el resultado. Rechaza cualquier oración que ponga will dentro de la parte con if. La habitación se guarda solo con un if limpio." },
      homework: { en: "Write a message to Laura choosing the river, movie, or quiet option. Include one failed attempt to find a charger and one offer of help that someone can accept or refuse. Laura should see a choice, a failed errand, and a real offer. Use ofrezco only for help someone may refuse.", es: "Escribe un mensaje a Laura escogiendo río, cine o descanso. Incluye un intento fallido de conseguir cargador y una oferta de ayuda que alguien pueda aceptar o rechazar. Laura debe ver choice, failed errand y real offer." },
      support: { en: "When decidirse por slips, give two columns: still choosing and choice made. Students place no me decido, decida, and me decidí por before they write new sentences. Do not add another option until the learner chooses a column.", es: "Cuando decide on se resbala, da dos columnas: still choosing y choice made. Ubican make up your mind, decide between y decided on antes de escribir frases nuevas. No añadas otra opción hasta que escoja still choosing o choice made." },
      stretch: { en: "Ask strong students to add a weather change after the deposit. They must keep the real conditional clean and renegotiate the plan without turning every sentence into a promise. Weather should force renegotiation, not a pile of promises.", es: "Pide a los avanzados añadir un cambio de clima después del depósito. Mantienen limpio el first conditional y renegocian el plan sin convertir cada frase en promesa. El clima debe forzar renegociación, no muchas promises." },
      errors: [
        { en: "They write \"Decido por el río\". Replace it with \"Me decido por el río\". Use decidirse por when the person settles on an option; decidir alone names the act of deciding.", es: "Cuando alguien dice \"I decide for the museum\", no lo corrijas con traducción. Pon \"I decide on the museum\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Si pagarás hoy, guardan la cabaña\". Replace it with \"Si pagas hoy, guardan la cabaña\". After si for a real condition, use the present in Spanish, not the future.", es: "Si aparece \"If you will pay today, they will hold it\", detén la ronda y escribe \"If you pay today, they will hold it\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "36-developing-looking-after-people": {
    mission: { en: "Look after people with practical care, safety warnings, and support that does not promise more than you can give.", es: "Cuidar a la gente con ayuda práctica, advertencias de seguridad y apoyo que no promete más de lo que puedes dar." },
    canDo: [
      { en: "Tell someone how you will look after a child, house, or task", es: "Decir cómo cuidarás a una niña, una casa o una tarea" },
      { en: "Organize simple protection for people during a risky moment", es: "Organizar protección sencilla para la gente en un momento de riesgo" },
      { en: "Support a friend morally while keeping money and promises clear", es: "Apoyar moralmente a una amiga dejando claros el dinero y las promesas" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Start with a care inventory: child, house, neighbors, friend. Students sort actions they know into watch, warn, and stand with before cuidar appears. The first sort separates care, safety, and loyalty. Sort the risky ones aloud.", es: "Empieza con inventario de cuidado: niña, casa, vecinos, amiga. Clasifican acciones conocidas en watch, warn y stand with antes de que aparezca look after. La primera clasificación separa care, safety y loyalty." },
      presentation: { en: "Use Gracias por cuidar a Lucía to show that the person cared for needs a. Contrast it with cuidar la casa so learners see why the child and the house behave differently. Lucía gets personal a; the house does not.", es: "Usa Thanks for looking after Lucía para mostrar la frase completa. Compárala con take care of the house y pregunta por qué care alone no sirve para supervisar a alguien. Look after Lucía no funciona como care alone." },
      practice: { en: "Give pairs Quibdó rain instructions with one missing verb form. They choose protejo for what I do, proteja for the polite instruction, and proteger de when naming the danger. The danger decides whether proteger de is needed.", es: "Entrega instrucciones de lluvia en Quibdó con un verbo faltante. Escogen protect, keep safe o protect from según hablen de acción, resultado o amenaza. La amenaza decide si hace falta protect from." },
      production: { en: "Run the neighborhood-board meeting from Pasto. The friend wants moral support, another person asks about money, and the speaker must back her publicly without promising expenses. The friend leaves with backing, not a money pledge. Say apoyar before any talk of money.", es: "Haz la reunión barrial de Pasto. La amiga necesita apoyo moral, otra persona pregunta por dinero, y quien habla debe respaldarla en público sin prometer gastos. La amiga sale con backing, no con promesa de dinero." },
      exitTicket: { en: "Ask for one warning with proteja or protect from. It must name the person at risk and the danger, not just say be careful. A warning without the danger is not protective yet.", es: "Pide una advertencia con protect from. Debe nombrar la persona en riesgo y el peligro, no solo decir be careful. Una advertencia sin peligro nombrado aún no protege." },
      homework: { en: "Write a night-shift note for Lucía’s aunt. Include what you will watch, what the child must not do, and one warm closing with cuídate. Cuídate should close care, not replace the instructions.", es: "Escribe una nota para la tía que trabaja de noche. Incluye qué vas a watch, qué no debe hacer la niña y un cierre natural con take care. Take care cierra el cuidado, no reemplaza instrucciones." },
      support: { en: "If apoyar becomes pay for, separate three cards: emotional, practical, financial. The learner chooses one before speaking, then adds a sentence refusing the kind they cannot give. Make them name emotional, practical, or financial support before the noun.", es: "Si support se vuelve pagar, separa tres tarjetas: emotional, practical, financial. El estudiante escoge una antes de hablar y añade una frase rechazando el tipo que no puede dar. Haz que digan emotional, practical o financial antes de support." },
      stretch: { en: "Give confident learners a flood rumor that could cause panic. They must protect older adults with calm instructions and correct one exaggerated message from the group chat. The rumor must become calmer by the time it reaches older adults. Use proteger to calm the rumor.", es: "Da a los avanzados un rumor de inundación que puede causar pánico. Deben keep people safe con instrucciones tranquilas y corregir un mensaje exagerado del chat. El rumor debe llegar más calmado a los adultos mayores." },
      errors: [
        { en: "They write \"Cuido Lucía esta noche\". Replace it with \"Cuido a Lucía esta noche\". Use personal a with the child; Lucía is not an object like the house.", es: "Cuando alguien dice \"I care Lucía tonight\", no lo corrijas con traducción. Pon \"I look after Lucía tonight\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Yo protego a los niños\". Replace it with \"Yo protejo a los niños\". Proteger changes g to j in protejo so the sound stays right before o.", es: "Si aparece \"I support with money my friend\", detén la ronda y escribe \"I support my friend morally\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "37-developing-making-and-breaking": {
    mission: { en: "Talk about making something on purpose and reporting what broke without sounding careless, guilty, or imprecise.", es: "Hablar de crear algo con intención y reportar lo que se dañó sin sonar descuidado, culpable ni impreciso." },
    canDo: [
      { en: "Describe the brand or object you want to create and why it needs a plan", es: "Describir la marca u objeto que quieres crear y por qué necesita plan" },
      { en: "Explain how people will build something and what each part is for", es: "Explicar cómo se construirá algo y para qué sirve cada parte" },
      { en: "Report broken glass or a failed device clearly without taking false blame", es: "Reportar un vidrio roto o aparato dañado claramente sin culparte de más" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Put a loose notebook, a brand label, and a broken-window sketch on the table. Learners say what already exists, what needs building, and what got damaged. The objects separate invention from damage before grammar starts. Name crear before the label exists.", es: "Pon una libreta suelta, una etiqueta de marca y un dibujo de vidrio roto. Dicen en inglés qué exists, qué needs building y qué got damaged. Los objetos separan invention de damage antes de la gramática. Usa create antes de vender la marca." },
      presentation: { en: "Write crear una marca, then ask why vender libretas sueltas is not enough. Add creé only after students locate the finished action in the fair story. Creé belongs only after the brand exists.", es: "Escribe create a brand y pregunta por qué selling loose notebooks no alcanza. Agrega created cuando ubiquen la acción terminada en la historia de la feria. Created aparece solo después de existir la marca." },
      practice: { en: "Use the Tunja garden plan as a parts check. Students label frame, base, soil, and plants, then choose construyo or construyeron depending on who is responsible. A garden bed without frame and base is not built.", es: "Usa la huerta de Tunja como revisión de partes. Etiquetan frame, base, soil y plants, luego escogen build o built según quién sea responsable. Sin frame y base todavía no está built." },
      production: { en: "Turn the Quibdó room into a damage report. The guest explains the pane, the wind, and the fan while the owner decides whether it is accident, neglect, or normal storm damage. The owner must hear accident rather than confession. Use se me rompió when the wind matters.", es: "Convierte el cuarto de Quibdó en reporte de daños. El huésped explica el vidrio, el viento y el ventilador mientras la dueña decide si fue accidente, descuido o daño normal de tormenta. La dueña debe oír accident, no confession. Usa it broke para evitar culpa directa." },
      exitTicket: { en: "Collect one careful accident sentence with se me rompió. It must report the broken thing and the cause without making the learner sound guilty on purpose. The cause matters because wind changes responsibility.", es: "Recoge una frase cuidadosa con it broke. Debe reportar el objeto dañado y la causa sin hacer sonar culpable a quien habla. La causa importa porque wind cambia responsabilidad." },
      homework: { en: "Design a three-line pitch for the notebook brand and a three-line report for the broken pane. The two texts must use different levels of responsibility. The brand pitch and damage report should not share a tone. Let crear carry the pitch.", es: "Diseña un pitch de tres líneas para la marca de libretas y un reporte de tres líneas sobre el vidrio. Los dos textos deben manejar distinta responsabilidad. El pitch y el damage report no deben sonar igual. Usa create para la marca, no make." },
      support: { en: "When se me rompió fails, draw three circles: thing, accidental me, past verb. Fill vidrio first, add me second, and only then conjugate romper. Keep the learner away from yo rompí for the rest of the hour.", es: "Cuando it broke se confunde con I broke it, dibuja dos columnas: accident y blame. El estudiante mueve window pane, fan y gust antes de hablar. Mantén al estudiante lejos de I broke it durante el resto de la hora." },
      stretch: { en: "Ask early finishers to negotiate who repairs the window. They need roto for the state, se dañó for the fan, and one sentence that keeps peace with the owner. Roto names the state; se dañó keeps the fan separate.", es: "Pide a los adelantados negociar quién arregla el vidrio. Usan broken para el estado, stopped working para el ventilador y una frase que conserve la relación. Broken nombra estado; stopped working separa el ventilador." },
      errors: [
        { en: "They write \"Quiero creer una marca\". Replace it with \"Quiero crear una marca\". Separate crear from creer; one makes a brand, the other believes something.", es: "Cuando alguien dice \"I want to make a brand\", no lo corrijas con traducción. Pon \"I want to create a brand\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Rompí el vidrio con el viento\". Replace it with \"Se me rompió el vidrio con el viento\". Use se me rompió when reporting the accident without claiming you deliberately broke it.", es: "Si aparece \"The window damaged\", detén la ronda y escribe \"The window pane broke\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "38-developing-life-and-loss": {
    mission: { en: "Speak about birth, death, and strong feelings with enough care to fit the family moment you are in.", es: "Hablar de nacimiento, muerte y sentimientos fuertes con el cuidado necesario para encajar en el momento familiar." },
    canDo: [
      { en: "Ask where someone was born and connect the answer to a family story", es: "Preguntar dónde nació alguien y conectar la respuesta con una historia familiar" },
      { en: "Offer a short condolence and leave space instead of filling silence", es: "Dar un pésame breve y dejar espacio en vez de llenar el silencio" },
      { en: "Recognize when kill is an everyday exaggeration about hunger or laughter", es: "Reconocer cuándo matar o kill es una exageración cotidiana sobre hambre o risa" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Spread old family photos on four desks: baby, wedding, move, funeral. Students choose which questions are safe before anyone sees nació, murió, or pésame. Safety of the question matters more than number of questions.", es: "Reparte fotos familiares en cuatro mesas: bebé, boda, mudanza, funeral. Escogen qué preguntas son seguras antes de ver was born, died o condolences. La seguridad de la pregunta vale más que la cantidad." },
      presentation: { en: "Ask Doña Elvira nació aquí? and let the class hear the respect before analyzing nació. Add nacieron with the children in the family tree, so agreement becomes visible. The family tree makes plural birth visible.", es: "Pregunta Were you born here? con tono respetuoso y marca was born. Agrega were born para los hijos del árbol familiar y muestra que inglés no usa born solo. El árbol familiar vuelve visible was y were." },
      practice: { en: "Give pairs a small family tree from Neiva. They ask two birthplace questions, then choose one condolence line for the Mompox novenario and explain why it is short. The condolence card wins by being short.", es: "Entrega un árbol familiar pequeño de Neiva. Hacen dos preguntas con born, luego escogen una frase de condolencia para el novenario y explican por qué debe ser breve. La tarjeta de condolence gana por ser breve." },
      production: { en: "Hold a quiet novenario doorway scene. One learner greets the family, one says what happened, and one responds. The goal is to leave comfort, not to win speaking time. Silence is a successful outcome in this room.", es: "Haz una escena silenciosa en la puerta del novenario. Una persona saluda a la familia, otra cuenta qué pasó y otra responde. La meta es consolar, no hablar más. El silencio cuenta como buen resultado en esta sala." },
      exitTicket: { en: "Collect one birthplace question with nació or nacieron, plus one condolence that contains no explanation. Cross out any sentence that tries to fill the silence. Any explanation after the condolence weakens the ticket.", es: "Recoge una pregunta de nacimiento con was born o were born y un pésame sin explicación. Tacha cualquier frase que intente llenar el silencio. Cualquier explicación después del pésame debilita la salida." },
      homework: { en: "Write two short texts: one respectful question about a grandparent’s birthplace and one joking Popayán line about hunger or laughter. Keep the emotional weight different. The joke must never borrow the weight of the loss. Keep me mata only in the joke.", es: "Escribe dos textos breves: una pregunta respetuosa sobre nacimiento y una broma de Popayán sobre hunger o laughter. Mantén distinto el peso emocional. El chiste nunca debe tomar el peso de la pérdida." },
      support: { en: "For nació versus nacieron, point to one person, then two children. Have the learner move a single verb card between them until the number feels obvious. Stop when the verb card stays under the right number.", es: "Para was born y were born, señala una persona y luego dos hijos. El estudiante mueve la tarjeta del verbo hasta que la diferencia de número sea obvia. Detente cuando la tarjeta verbal quede bajo el número correcto." },
      stretch: { en: "Invite quick students to retell the family photo story from a cousin’s view. They must include one birth, one loss, and one matar joke without making the loss casual. The matar joke must remain outside the condolence moment.", es: "Invita a los adelantados a contar la foto desde la mirada de un primo. Incluyen birth, loss y un chiste con kill sin volver casual la pérdida. El chiste con kill queda fuera del pésame." },
      errors: [
        { en: "They write \"¿Dónde nació sus hijos?\". Replace it with \"¿Dónde nacieron sus hijos?\". Make nacer agree with the children; the subject is plural even when the question starts with dónde.", es: "Cuando alguien dice \"Where born your grandmother?\", no lo corrijas con traducción. Pon \"Where was your grandmother born?\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Estoy muerto por el hambre\". Replace it with \"Me mata el hambre\". Use me mata el hambre for joking hunger. Estoy muerto sounds heavier and changes the social weight.", es: "Si aparece \"My dad dead on Monday\", detén la ronda y escribe \"My dad died on Monday\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "39-developing-planning-a-trip": {
    mission: { en: "Plan a weekend with rooms, visits, friends and routes by separating intention, destination and deadline.", es: "Planear un fin de semana con cuartos, visitas, amigos y rutas separando intención, destino y plazo." },
    canDo: [
      { en: "Book rooms and confirm what remains reserved", es: "Reservar cuartos y confirmar qué queda reservado" },
      { en: "Plan visits to relatives, museums and friends with different levels of formality", es: "Planear visitas a familiares, museos y amigos con distinta formalidad" },
      { en: "Choose between purpose, route, recipient and deadline words", es: "Escoger entre palabras de propósito, ruta, destinatario y fecha límite" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Put a blank weekend calendar on the wall. Students place rooms, aunt, museum, river and package on different days. Their first plan shows whether destination, visit and deadline are already distinct. Hold reservar until students ask for it.", es: "Pon un calendario de fin de semana en blanco. Ubican rooms, aunt, museum, river y package en días distintos. El primer plan muestra si separan destination, visit y deadline. Guarda \"through\" hasta que lo pidan." },
      presentation: { en: "Begin with the Mompox call: quisiera reservar dos cuartos. Put apartar underneath as a temporary hold. Ask what changes when the deposit appears, because that is the planning consequence. Mark the deposit.", es: "Empieza con I'd like to book two rooms. Escribe hold debajo como reserva temporal. Pregunta qué cambia cuando aparece deposit; así book y hold quedan ligados al hotel. Ancla el tablero en \"through\"." },
      practice: { en: "Students work through four counters: hotel, aunt's house, river plan, cargo desk. Each station allows only one target: reservar, visitar a, cuadrar or por/para. They rotate after one correct exchange. Record the answer.", es: "Pasan por cuatro estaciones: hotel, aunt, weekend plan y cargo. Cada una permite una forma: book, visit someone, work it out o for/by/through. Rotan después de un intercambio correcto." },
      production: { en: "Act out the Buenaventura cargo counter. One package goes ahead, one traveler leaves for Cali, and the route passes through Cali later. Students must choose por or para from the physical map. Make reservar necessary in the scene.", es: "Representa el cargo counter. Un paquete va ahead, una persona leaves for Fort Worth y la ruta passes through Waco. Deben escoger for, to, by o through mirando el mapa." },
      exitTicket: { en: "Draw two arrows: toward Cali and through Cali. Students write para on one and por on the other, then add one English gloss. It catches the module's biggest decision. Check reservar, not a list.", es: "Dibuja dos flechas: destination y route. Escriben for o through y añaden una frase corta. Así ves si el mapa de viaje quedó claro. Revisa \"through\", no una lista. Compara con \"book\" solo al final." },
      homework: { en: "Students plan one real weekend in five bullets: room, visit, friend, route and deadline. Require one por or para sentence, not a list of places. Bring reservar back next class.", es: "Planean un fin de semana real en cinco puntos: room, visit, friend, route y deadline. Deben incluir una frase con for, to, by o through, no solo lugares." },
      support: { en: "If por and para blur, remove the nouns and use arrows only. A forward arrow gets para; a path line gets por. Add Buenaventura and Cali after the choice is stable. Make reservar the small rescue.", es: "Si for tapa todo, quita los sustantivos y usa flechas. Destination toma to o for; route toma through; deadline toma by. Agrega ciudades después. Haz de \"through\" el rescate. Compara con \"book\" solo al final." },
      stretch: { en: "Early finishers call the posada back with a change. They must hold one room, release another and keep the tone courteous enough for a real booking. Push reservar into a new register.", es: "Quienes avanzan llaman de nuevo al hotel. Deben change a booking, hold one room y cancel another politely, como si la reserva importara de verdad. Lleva \"through\" a otro tono." },
      errors: [
        { en: "They say \"reservar\" when the owner is only holding rooms. Write \"apartar\" for the temporary hold and \"reservar\" after the deposit; the money changes the status.", es: "Dicen \"reserve two rooms\" en una llamada normal. Muestra \"book two rooms\" como opción cotidiana; reserve funciona, pero book suena más natural para hotel." },
        { en: "They choose por for every English for. Draw arrows: \"salgo para Cali\" points forward, while \"paso por Cali\" crosses through; direction and route are different.", es: "Dicen \"I go for Fort Worth.\" Cámbialo a \"I'm leaving for Fort Worth\" o \"going to Fort Worth\"; for marca destino solo con el verbo de viaje bien armado." }
      ]
    }
  },
  "40-extending-devices-and-how-things-work": {
    mission: { en: "Diagnose a device problem by naming what turns on, what shuts off, and whether it works before negotiating repair or payment.", es: "Diagnosticar un problema de aparatos nombrando qué se enciende, qué se apaga y si funciona antes de negociar arreglo o pago." },
    canDo: [
      { en: "Tell a technician to turn on or shut off a fan, router, breaker, or meter", es: "Decirle a un técnico que encienda o apague un ventilador, router, breaker o medidor" },
      { en: "Report whether a device funciona after a specific test", es: "Informar si un aparato funciona después de una prueba específica" },
      { en: "Use a repair diagnosis to argue for the next warranty or payment step", es: "Usar un diagnóstico de reparación para argumentar el siguiente paso de garantía o pago" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Put a dead router, a fan, and a fake prepaid-meter slip on the repair table. Before teaching encender, ask learners to separate switch actions from the wider question of whether the device funciona. Spanish checkpoint: encender becomes useful before apagar; students say why.", es: "Ponga un router dañado, un ventilador y un recibo de medidor en la mesa. Antes de enseñar turn on, pida separar acciones de switch de la pregunta mayor: whether it works. Punto de control: \"turn on\" sirve antes de \"turn off\"; explican por qué." },
      presentation: { en: "Demonstrate encender with the fan button, then apagar with a safety reason: the fridge overheats. Only after the class can report those actions, use funcionar for the router diagnosis. The board ends with encender, apagar, and one reason funcionar belongs later.", es: "Modele turn on con el botón del ventilador y turn off por seguridad: la nevera se recalienta. Cuando ya reporten esas acciones, use work para diagnosticar el router. El tablero termina con \"turn on\", \"turn off\" y una razón para aplazar \"work\"." },
      practice: { en: "Repair tickets move across three stations. At the fan station students command encender; at the breaker box they justify apagar; at the router they decide whether funcionar is the only honest answer. Every answer cites the cue that forced encender or blocked apagar.", es: "Los reportes pasan por tres estaciones. En fan usan turn on; en breaker justifican turn off; en router deciden si work es la única respuesta honesta. Cada respuesta cita la pista que exige \"turn on\" o bloquea \"turn off\"." },
      production: { en: "Run a warranty counter. The customer wants money back, the technician wants another test, and the clerk needs one precise sentence with encender before approving the next step. The final decision must include encender and survive one objection.", es: "Haga un mostrador de garantía. Cliente pide devolución, técnica quiere otra prueba y ventanilla exige una frase exacta con turn on antes de aprobar el siguiente paso. La decisión final debe incluir \"turn on\" y resistir una objeción." },
      exitTicket: { en: "Before leaving, each learner diagnoses the router: change \"el router no encende\" to \"el router no enciende\" and add one warranty line using encender for the fan or meter.", es: "Antes de salir, diagnostican el aparato: cambian \"light the fan\" por \"turn on the fan\" y añaden una línea de garantía que use turn on con ventilador o medidor." },
      homework: { en: "Write the shop note left after closing: what was turned on, what had to be shut off, and whether the router finally worked. The note must support a real refund decision. Students underline the Spanish form encender where it carries the decision.", es: "Escriben en inglés la nota de cierre: what was turned on, what was turned off, and whether the router worked. La nota debe justificar o negar reembolso. Subrayan la forma inglesa \"turn on\" donde sostiene la decisión." },
      support: { en: "Students stuck on encender usually point instead of naming the switch action. Give them a two-card frame, switch plus result, and remove the pointing option before they speak.", es: "Quienes se traban con turn on suelen señalar en vez de nombrar la acción. Dé dos tarjetas, switch y result, y quite la posibilidad de apuntar antes de hablar." },
      stretch: { en: "Add a landlord who says the tenant broke the router. Fast groups must concede one possible misuse, then defend the repair request with funcionar and evidence from the prepaid meter. The added challenge must still keep encender accurate in context.", es: "Agregue una arrendadora que culpa al inquilino. Grupos rápidos conceden un mal uso posible y defienden la reparación con work y evidencia del medidor. El reto añadido conserva \"turn on\" correcto dentro del contexto." },
      errors: [
        { en: "Device repair: they write \"el router no encende\" because transfer overpowers the Device repair scene. Put \"el router no enciende\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Device repair: dicen \"light the fan\" por transferencia del español en aparatos. Corrija a \"turn on the fan\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"encender\" where this step needs \"apagar\". Name the aparatos speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"turn on\" cuando la escena necesita \"turn off\". Nombre al hablante de aparatos, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "41-developing-allowing-and-preventing": {
    mission: { en: "Read rules and route advice so you can say what is allowed, what blocks you, and what to avoid.", es: "Leer reglas y consejos de ruta para decir qué se permite, qué te bloquea y qué debes evitar." },
    canDo: [
      { en: "Explain what a sign allows or forbids without arguing with the rule", es: "Explicar qué permite o prohíbe un aviso sin pelear con la regla" },
      { en: "Say what prevents access and ask for another usable path", es: "Decir qué impide el acceso y pedir otra ruta útil" },
      { en: "Advise someone how to avoid a crowd, traffic jam, or lonely block", es: "Aconsejar cómo evitar una multitud, un trancón o una cuadra sola" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Stand at an imaginary library door with a bottle, laptop, and empanada. Learners predict which items pass, then separate rule language from personal preference. The bottle and empanada make rule language necessary.", es: "Párate en una puerta imaginaria con botella, portátil y empanada. Predicen qué pasa y separan rule language de personal preference. La botella y la empanada hacen necesaria la regla." },
      presentation: { en: "Write no se permite entrar con comida as a sign, not a spoken complaint. Ask who is doing the allowing. When no person appears, circle se. Se is the sign’s missing rule-maker.", es: "Escribe Food isn’t allowed como aviso, no como queja personal. Pregunta quién permite. Cuando no aparece persona, encierra isn’t allowed. Isn’t allowed cubre al autor invisible del aviso." },
      practice: { en: "Post a taped-off Riohacha boardwalk on the wall. Students match impide pasar, no dejar pasar, and zona en arreglo to three worker explanations. Tape across the path should force impide, not advice.", es: "Pega en la pared un paseo de Riohacha cerrado con cinta. Emparejan prevents access, work area y won’t let me through con tres explicaciones del trabajador. La cinta en el camino exige prevents, no advice." },
      production: { en: "Turn Manizales into a route desk. One learner has an appointment, one knows the market crowd, and one warns about a lonely block while proposing an alternate path. The route must avoid both traffic and the lonely block. Use evite for the alternate route.", es: "Convierte Manizales en punto de rutas. Una persona tiene cita, otra conoce el tráfico del mercado y otra advierte sobre la cuadra sola mientras propone otro camino. La ruta evita traffic y lonely block a la vez." },
      exitTicket: { en: "Ask for one library rule using se permite or no se permite. It must name the item and the place, not just allowed or forbidden. A rule with no place still feels unfinished.", es: "Pide una regla de biblioteca con is allowed o isn’t allowed. Debe nombrar el objeto y el lugar, no solo allowed o forbidden. Una regla sin lugar queda incompleta." },
      homework: { en: "Make a three-rule sign for a study room and a two-line route warning for the market. Use one formal rule and one friendly warning. One line should sound like a sign, the other like a person.", es: "Haz un aviso de tres reglas para una sala de estudio y una advertencia de ruta de dos líneas. Usa una regla formal y un aviso amable. Una línea suena a sign y la otra a person." },
      support: { en: "If evitar turns into impedir, give the student two pictures: a blocked path and a chosen alternate route. They say whether the problem stops them or they avoid it. Blocked path and chosen route must stay in different piles.", es: "Si avoid se mezcla con prevent, da dos dibujos: camino bloqueado y ruta alterna escogida. Dicen si el problema stops them o si they avoid it. Blocked path y chosen route quedan en montones distintos." },
      stretch: { en: "Ask advanced learners to soften a city worker’s command. They must keep the boardwalk closed but offer a reason and a safe route around the repair. The worker keeps authority while giving a reason.", es: "Pide a los avanzados suavizar la orden del trabajador. Mantienen cerrado el paseo, pero dan reason y safe route alrededor del arreglo. El trabajador conserva autoridad y da reason. Usa prevent para mantener cerrado el paso." },
      errors: [
        { en: "They write \"No permite entrar comida\". Replace it with \"No se permite entrar con comida\". For a public rule, use se permite; the sign is not a person allowing you.", es: "Cuando alguien dice \"Food does not allow in the room\", no lo corrijas con traducción. Pon \"Food isn’t allowed in the room\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"La cinta me impide de pasar\". Replace it with \"La cinta me impide pasar\". Impedir takes the infinitive directly. Do not add de after it here.", es: "Si aparece \"The tape prevents to pass\", detén la ronda y escribe \"The tape prevents access\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "42-developing-what-matters-to-you": {
    mission: { en: "Say what matters to you, what is still missing, and what you want another person to do without reversing the answer.", es: "Decir qué te importa, qué falta todavía y qué quieres que haga otra persona sin invertir la respuesta." },
    canDo: [
      { en: "Ask about a course and say what parts interest you most", es: "Preguntar por un curso y decir qué partes te interesan más" },
      { en: "Ask permission at a shared table and answer yes or no without confusion", es: "Pedir permiso en una mesa compartida y contestar sí o no sin confusión" },
      { en: "Name what is missing before leaving and ask for support with a move", es: "Nombrar qué falta antes de salir y pedir apoyo para mudarte" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Hand out a fake course flyer from Sincelejo with schedule, cost, and final project. Students mark what matters to them before seeing me interesa. The flyer decides what interests the learner, not the teacher.", es: "Entrega un volante falso de curso en Sincelejo con horario, precio y proyecto final. Marcan qué les importa antes de ver I’m interested in. El volante decide qué interesa, no el profesor." },
      presentation: { en: "Make the backward grammar visible with me interesa el horario and me interesan los proyectos. Draw arrows from the thing to the person, then ask what changes when the thing becomes plural. The arrow must run from course part to person.", es: "Haz visible la estructura de I’m interested in. Escribe I’m interested in the schedule y the projects interest me, luego muestra por qué interesting no describe al estudiante. La flecha va de course part hacia person." },
      practice: { en: "Use the hostel table in Riohacha for permission cards. Half need ¿te importa si...? and half need the answer no, no me importa, because yes reverses the permission. Permission succeeds only when no really means go ahead.", es: "Usa la mesa compartida del hostal para tarjetas de permiso. La mitad necesita Do you mind if...? y la otra mitad responde No, no problem para practicar la inversión. El permiso funciona solo cuando no significa adelante." },
      production: { en: "Stage the Girardot move conversation. The learner wants independence, the father wants caution, and both must state what they want the other person to do before reaching a compromise. The father’s trust is the object of the grammar.", es: "Representa la mudanza en Girardot. Una persona quiere independencia, el papá quiere cuidado, y ambos dicen qué quieren que haga la otra persona antes de acordar. La confianza del papá es el objeto gramatical." },
      exitTicket: { en: "Collect one boat-checklist sentence with me falta or faltan. It must make the missing thing the subject, not the traveler. The missing signature, not the traveler, controls the verb.", es: "Recoge una oración de lista de lancha con we’re missing o still need. Debe nombrar lo que falta antes de decidir si el grupo puede salir. La firma faltante controla el verbo, no quien viaja." },
      homework: { en: "Write two messages: one asking about the course and one asking to move a chair. In each, include the answer you hope to get and the answer you fear. Hope and fear keep the permission answers from reversing. Put me interesa in the course message.", es: "Escribe dos mensajes: uno sobre el curso y otro para mover una silla. En cada uno incluye la respuesta que esperas y la que temes recibir. Hope y fear evitan invertir las respuestas." },
      support: { en: "For me interesa, lock the sentence frame as A mí me interesa ___. The stuck learner changes only the course part three times before adding cost or schedule. Vary only the course part until the backward pattern holds.", es: "Para I’m interested in, fija I’m interested in ___ como marco. El estudiante bloqueado cambia solo el tema del curso tres veces antes de añadir cost o schedule. Cambia solo el tema del curso hasta fijar I’m interested in." },
      stretch: { en: "Ask fast finishers to make the father’s objection stronger with me molesta que. They must respond without erasing his concern or giving up the move. The objection must stay caring, not become a veto.", es: "Pide a los adelantados fortalecer la objeción del papá con It bothers me that. Responden sin borrar la preocupación ni abandonar la mudanza. La objeción sigue siendo cuidado, no veto." },
      errors: [
        { en: "They write \"Me intereso el curso\". Replace it with \"Me interesa el curso\". Interesar works backward for English speakers; the course interests me, so me interesa names the person affected.", es: "Cuando alguien dice \"I am interesting in the course\", no lo corrijas con traducción. Pon \"I am interested in the course\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"¿Te importa si muevo la silla? Sí, no me importa\". Replace it with \"¿Te importa si muevo la silla? No, no me importa\". A yes answer means it bothers you. Practice the answer before the class moves the chair.", es: "Si aparece \"Do you mind if I move this? Yes, no problem\", detén la ronda y escribe \"Do you mind if I move this? No, no problem\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "43-developing-more-less-better": {
    mission: { en: "Discuss change in health, money, and habits by saying what improves, increases, or needs to be reduced.", es: "Hablar de cambios en salud, dinero y hábitos diciendo qué mejora, qué aumenta o qué hay que reducir." },
    canDo: [
      { en: "Tell a sick friend whether you are getting better and what still hurts", es: "Decirle a un amigo enfermo si mejoras y qué sigue molestando" },
      { en: "Discuss a rent increase and separate formal increase from street go up", es: "Hablar de un aumento de arriendo y separar increase formal de go up cotidiano" },
      { en: "Explain how to reduce sugar gradually and report what you already reduced", es: "Explicar cómo reducir azúcar poco a poco y contar qué ya redujiste" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Draw three scales: fever, rent, sugar. Learners place yesterday and today on each scale, using only words they already have for more, less, and better. Three scales keep health, rent, and sugar from blending. Use mejorar for the health scale.", es: "Dibuja tres escalas: fever, rent, sugar. Ubican ayer y hoy en cada una usando solo el inglés que ya tienen para more, less y better. Tres escalas separan health, rent y sugar." },
      presentation: { en: "Start with ¿ya estás mejor? from the soup visit. Show how mejorarse belongs to recovery, then contrast it with aumentar el arriendo from the formal notice. Recovery and rent notice need different change verbs.", es: "Empieza con Are you feeling better? en la visita con sopa. Muestra get better para recuperación y compáralo con the rent will increase en el aviso formal. Recovery y rent notice exigen verbos distintos." },
      practice: { en: "Give three mini-records: temperature, rent notice, lab result. Students choose mejoró, aumenta, or reducir and add one number so the change is measurable. A number proves whether the change went up or down.", es: "Entrega tres registros: temperatura, aviso de arriendo y resultado médico. Escogen improved, increased o reduce y añaden un número para que el cambio sea medible. Un número prueba si el cambio subió o bajó. Usa cut back cuando el azúcar baja." },
      production: { en: "Run the San Andrés nutrition visit. The patient wants one last sweet drink, the nutritionist wants gradual reduction, and they must agree on a plan that survives the week. The week plan must survive one sweet-drink objection.", es: "Representa la consulta en San Andrés. El paciente quiere una última bebida dulce, la nutricionista quiere reducir poco a poco, y acuerdan un plan para la semana. El plan semanal sobrevive una objeción de sweet drink. Usa reduce para el plan semanal. Usa reduced sugar antes del acuerdo." },
      exitTicket: { en: "Ask for one sentence with reduje or I reduced. It must say what changed and whether the change happened at once or little by little. At once or little by little changes the medical advice.", es: "Pide una oración con I reduced. Debe decir qué cambió y si pasó at once o little by little. At once o little by little cambia el consejo médico." },
      homework: { en: "Track one habit for two days: sugar, sleep, water, or spending. Write four lines that show what improved, what increased, and what you reduced. The tracked habit supplies the evidence for reduce. Write reduje beside the tracked habit.", es: "Sigue un hábito dos días: sugar, sleep, water o spending. Escribe cuatro líneas que muestren qué improved, qué increased y qué reduced. El hábito observado da evidencia para reduce." },
      support: { en: "If aumentar and reducir blur together, give up and down arrows with rent and sugar pictures. The learner points first, then chooses the verb. Pointing comes before verbs so direction is settled first.", es: "Si increase y reduce se mezclan, da flechas hacia arriba y abajo con imágenes de rent y sugar. El estudiante señala primero y luego escoge el verbo. Primero señala dirección; después escoge increase o reduce." },
      stretch: { en: "Have quick students challenge the nutrition plan politely. They must defend one small pleasure while still accepting a measurable reduction. The patient keeps one pleasure but loses the old amount.", es: "Haz que los adelantados cuestionen el plan nutricional con cortesía. Defienden un gusto pequeño y aceptan una reducción medible. El paciente conserva un gusto y pierde la cantidad vieja." },
      errors: [
        { en: "They write \"Estoy mejorando de la fiebre\". Replace it with \"Me estoy mejorando de la fiebre\". Use the reflexive when the person is recovering. Mejorar alone fits a result or skill more easily.", es: "Cuando alguien dice \"I am bettering from the fever\", no lo corrijas con traducción. Pon \"I’m getting better from the fever\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Redují el azúcar\". Replace it with \"Reduje el azúcar\". Reducir has reduje in the preterite. Put it beside conduje if they know that pattern.", es: "Si aparece \"The rent will augment next month\", detén la ronda y escribe \"The rent will increase next month\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "44-developing-getting-back-to-people": {
    mission: { en: "Keep social trust by answering, letting people know, and promising only what you will actually do.", es: "Mantener la confianza respondiendo, avisando y prometiendo solo lo que de verdad vas a hacer." },
    canDo: [
      { en: "Ask whether someone answered and explain when a message was left on read", es: "Preguntar si alguien contestó y explicar cuándo un mensaje quedó en visto" },
      { en: "Tell relatives when you will let them know and when you mean it", es: "Decir a familiares cuándo avisarás y cuándo lo dices en serio" },
      { en: "Make a promise after a delay and state how you will keep it", es: "Hacer una promesa después de una demora y decir cómo la cumplirás" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Draw four message bubbles: sent, read, answered, ignored. Students decide which one damages the outing plan before contestar appears. Use the reply map now. The damaged plan comes from silence, not vocabulary.", es: "Dibuja cuatro mensajes: sent, read, answered, ignored. Deciden cuál daña el plan de salida antes de trabajar answer y reply. El plan se daña por silencio, no por vocabulario." },
      presentation: { en: "Use ¿te contestó Lina? for the phone and message problem. Contrast contestar el teléfono with responder a un mensaje so the class sees what changes and what does not. The phone can be answered; the message can be replied to.", es: "Usa Did Lina answer? para el problema del teléfono. Contrasta answer the phone con reply to a message para que vean cuándo aparece la preposición. Answer sirve para phone; reply to sirve para message." },
      practice: { en: "Give learners six San Andrés message screenshots in words. They label answered, left on read, or still nothing, then choose whether the next line should be annoyed or patient. Register decides whether left on read is fair or too harsh. Contrast dejar en visto with waiting kindly.", es: "Entrega seis pantallazos escritos de San Andrés. Marcan answered, left on read o still nothing, luego deciden si la respuesta debe sonar molesta o paciente. El registro decide si left on read es justo o duro." },
      production: { en: "Set the Manizales apology after a real delay. One friend heard yo miro a ver, one waited, and the speaker must make only one promise that can be kept. Only one promise may survive the apology.", es: "Monta la disculpa de Manizales después de una demora real. Un amigo oyó I’ll see, otro esperó, y quien habla hace solo una promesa que pueda cumplir. Solo una promise puede sobrevivir la disculpa." },
      exitTicket: { en: "Collect one message with avíseme cuando llegue or let me know when you arrive. It must include the moment that triggers the reply. The arrival moment triggers the family reply.", es: "Recoge un mensaje con let me know when you arrive. Debe incluir el momento que activa la respuesta, no solo una petición general. La llegada activa la respuesta familiar." },
      homework: { en: "Write a family travel thread for Sincelejo: departure, arrival, and one change. Include one sincere aviso and one vague yo te aviso that postpones the answer. One aviso must be sincere and one must postpone.", es: "Escribe un chat familiar de viaje a Sincelejo: salida, llegada y un cambio. Incluye un let me know sincero y un I’ll let you know que aplaza. Un let me know es sincero y otro aplaza." },
      support: { en: "For dejar en visto, do not start with grammar. Give two situations: a busy cousin and a rude friend. Ask when left on read is fair to say. Judge the relationship before you allow left on read.", es: "Para leave someone on read, no empieces por gramática. Da dos situaciones: primo ocupado y amigo grosero. Pregunta cuándo la frase es justa. Juzga la relación antes de permitir left on read." },
      stretch: { en: "Ask fast finishers to repair trust without overpromising. They must include te lo prometo once, then replace a second promise with a softer Colombian phrase. The repaired trust should use fewer promises, not more.", es: "Pide a los adelantados reparar confianza sin prometer de más. Usan I promise una vez y reemplazan una segunda promesa con una frase más suave. La confianza reparada usa menos promises, no más." },
      errors: [
        { en: "They write \"Contéstame a mi mensaje\". Replace it with \"Contéstame el mensaje\". Contestar can take the thing answered directly; do not force a because English says answer to sometimes.", es: "Cuando alguien dice \"She answered to my message\", no lo corrijas con traducción. Pon \"She answered my message\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Prometo de avisarte\". Replace it with \"Prometo avisarte\". Prometer takes the infinitive without de. Keep the promise small enough to be believable.", es: "Si aparece \"I promise you that I notify you\", detén la ronda y escribe \"I promise I’ll let you know\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "45-developing-getting-ready": {
    mission: { en: "Get ready for family and friends by testing, preparing and organizing before the plan starts moving.", es: "Alistarte para familia y amigos probando, preparando y organizando antes de que el plan se mueva." },
    canDo: [
      { en: "Taste food and try on clothing without mixing the verbs", es: "Probar comida y medirte ropa sin mezclar los verbos" },
      { en: "Prepare objects and get yourself ready for an early outing", es: "Preparar objetos y alistarte para una salida temprana" },
      { en: "Organize food, transport and money before the group argues", es: "Organizar comida, transporte y dinero antes de que el grupo discuta" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Put a spoon, a shirt, a backpack and a food list on the table. Students decide what can be tasted, tried on, prepared or organized. The objects teach the verb boundaries. Hold probar until students ask for it.", es: "Pon spoon, shirt, backpack y food list sobre la mesa. Deciden qué se puede taste, try on, get ready u organize. Los objetos marcan los límites del verbo." },
      presentation: { en: "Start in the kitchen: prueba el sancocho. Then move the same probar to the shirt with me pruebo. Ask what changed in the body before introducing preparar la mochila. Touch the object.", es: "Empieza con taste the sancocho. Luego pasa a try the shirt on y pregunta qué cambió. Después presenta get the bag ready para separar preparar un objeto de get ready." },
      practice: { en: "Students receive four preparation cards: soup, shirt, backpack, weekend plan. They choose pruebo, me pruebo, preparo or organizo and add one reason from the scene. Let probar carry the drill. Say it aloud twice.", es: "Da cuatro tarjetas: stew, shirt, bag y weekend trip. Escogen taste, try on, get ready o organize, y añaden una razón corta desde la escena. Repiten con otra persona." },
      production: { en: "Set the San Andrés boat errand for an early departure. Coffee is fresh, sunscreen is missing, and the backpack is half done. Students divide tasks before anyone can leave. Make probar necessary in the scene.", es: "Monta la salida temprano. Coffee is freshly made, falta sunscreen y the bag is not ready. Deben repartir tareas con make coffee, get ready y get the bag ready." },
      exitTicket: { en: "Show shirt and soup. Students write me pruebo for one and pruebo for the other. If they add intentar, the clothing and food distinction needs another pass. Check probar, not a list.", es: "Muestra shirt y stew. Escriben try on para la camisa y taste para la comida. Si aparece attempt, vuelve a la diferencia entre probar y intentar. Revisa \"ready\", no una lista." },
      homework: { en: "Students write a getting-ready checklist for one real event. It must include one thing to taste or test, one item of clothing and one shared task to organize. Bring probar back next class.", es: "Escriben una lista para alistarse a un evento real. Debe incluir something to taste or test, one clothing item y one plan to organize. Traen \"ready\" de vuelta." },
      support: { en: "For support, hand the student two sentence backs: pruebo ___ and me pruebo ___. They choose between spoon and shirt first. Add preparar only after that contrast is safe. Make probar the small rescue.", es: "Para apoyo, entrega dos marcos: taste ___ y try ___ on. Eligen spoon o shirt primero. Añade get ready solo cuando esa diferencia ya no se mueva." },
      stretch: { en: "Ask fast students to organize the Girardot river plan with money missing. They must assign food, transport and departure time, then repair one friend who changes the plan. Push probar into a new register.", es: "A los rápidos, dales el paseo al río con money missing. Deben organize food, arrange transport y set departure time, y luego responder a un amigo que cambia todo. Lleva \"ready\" a otro tono." },
      errors: [
        { en: "They say \"intento la camisa\" after English try. Put \"me pruebo la camisa\" and \"pruebo el sancocho\" together; clothing needs the reflexive.", es: "Dicen \"I attempt the shirt.\" Sustitúyelo por \"I try the shirt on\". Attempt sirve para una acción difícil, no para ropa en un cuarto." },
        { en: "They use preparar for the person: \"preparo y salimos.\" Add me: \"me preparo.\" The backpack is prepared; the person gets ready.", es: "Dicen \"I prepare myself\" en un plan casual. Ofrece \"I get ready\"; prepare myself suena formal o dramático para bloqueador y gorra." }
      ]
    }
  },
  "46-extending-figuring-things-out": {
    mission: { en: "Build a case from clues by saying what you found out, what contradicts it, and what follows from the evidence.", es: "Construir un caso a partir de pistas diciendo qué averiguaste, qué lo contradice y qué se deduce de la evidencia." },
    canDo: [
      { en: "State a discovery with descubrí que from a house name, bill, oil check, or order record", es: "Declarar un hallazgo con descubrí que a partir de un nombre de casa, factura, revisión de aceite u orden" },
      { en: "Use sin embargo to keep a contradictory clue in the argument", es: "Usar sin embargo para mantener una pista contradictoria dentro del argumento" },
      { en: "Draw an actionable conclusion with por lo tanto instead of another guess", es: "Sacar una conclusión accionable con por lo tanto en vez de otra suposición" }
    ],
    teaching: {
      minutes: 75,
      warmUp: { en: "Tape the old house name beside the water bill and ask for theories. Do not give descubrí que yet; first make students label which statements are clues and which are guesses. Spanish checkpoint: descubrí que becomes useful before sin embargo; students say why.", es: "Pegue el nombre antiguo junto a la factura y pida teorías en inglés. No dé I found out todavía; primero separan clues de guesses. Punto de control: \"I found out\" sirve antes de \"however\"; explican por qué." },
      presentation: { en: "Use descubrí que for the moment a clue changes the story. Bring in sin embargo when the oil check contradicts the first theory, and reserve por lo tanto for the decision. The board ends with descubrí que, sin embargo, and one reason por lo tanto belongs later.", es: "Use I found out cuando una pista cambia la historia. Entre however con el aceite que contradice la primera teoría y deje therefore para la decisión. El tablero termina con \"I found out\", \"however\" y una razón para aplazar \"therefore\"." },
      practice: { en: "Teams sort clue cards from the house, bill, oil, and missing order. They must choose discovery, contrast, or consequence before writing descubrí que, sin embargo, or por lo tanto. Every answer cites the cue that forced descubrí que or blocked sin embargo.", es: "Equipos clasifican tarjetas de casa, factura, aceite y orden perdida. Escogen discovery, contrast o consequence antes de escribir I found out, however o therefore. Cada respuesta cita la pista que exige \"I found out\" o bloquea \"however\"." },
      production: { en: "Hold a missing-order hearing. One side argues from the bill, the other from the oil record; the chair accepts only a conclusion introduced by por lo tanto. The final decision must include descubrí que and survive one objection.", es: "Haga audiencia por la orden perdida. Un lado argumenta con la factura, otro con el registro de aceite; presidencia acepta solo conclusión con therefore. La decisión final debe incluir \"I found out\" y resistir una objeción." },
      exitTicket: { en: "Students close the case file by changing \"lo descubrí leyendo el letrero\" to \"lo descubrí escuchando la historia\"; the added line must show whether descubrí que or sin embargo fits.", es: "Cierran el expediente cambiando \"review the oil\" por \"check the oil\"; la línea nueva debe mostrar si I found out o however organiza la prueba." },
      homework: { en: "Prepare a case memo with three short paragraphs: clue found, contradiction noticed, action recommended. At least one paragraph must begin with sin embargo and change the reader's mind. Students underline the Spanish form descubrí que where it carries the decision.", es: "Redactan en inglés un memo de caso: clue found, contradiction noticed, action recommended. Un párrafo empieza con however y debe cambiar la lectura. Subrayan la forma inglesa \"I found out\" donde sostiene la decisión." },
      support: { en: "The hard point is not vocabulary; it is reasoning order. Give students colored slips for evidence, contrast, and result, then let the connector appear only after the slip is chosen.", es: "Lo difícil no es vocabulario sino orden lógico. Dé tiras evidence, contrast y result; el conector en inglés aparece solo después de elegir la tira." },
      stretch: { en: "Ask early finishers to defend the weaker explanation. They may admit one bad clue, but they must still build a chain ending in por lo tanto. The added challenge must still keep descubrí que accurate in context.", es: "Pida defender la explicación débil. Pueden admitir una pista mala, pero deben armar una cadena que termine con therefore. El reto añadido conserva \"I found out\" correcto dentro del contexto." },
      errors: [
        { en: "Case solving: they write \"lo descubrí leyendo el letrero\" because transfer overpowers the Case solving scene. Put \"lo descubrí escuchando la historia\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Case solving: dicen \"review the oil\" por transferencia del español en casos. Corrija a \"check the oil\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"descubrí que\" where this step needs \"sin embargo\". Name the casos speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"I found out\" cuando la escena necesita \"however\". Nombre al hablante de casos, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "47-extending-paperwork-and-payments": {
    mission: { en: "Complete a paper transaction by handing over the right document, stating what proof remains, and asking the person what they charge.", es: "Completar un trámite entregando el documento correcto, diciendo qué prueba queda y preguntando a la persona cuánto cobra." },
    canDo: [
      { en: "Hand over a label, lease page, or ID copy with entregar and state where proof stays", es: "Entregar una etiqueta, contrato o copia de cédula con entregar y decir dónde queda la prueba" },
      { en: "Say what still needs firmar before the office can close the file", es: "Decir qué falta firmar antes de que la oficina pueda cerrar el expediente" },
      { en: "Ask ¿cuánto me cobra? for a mechanic's service rather than a generic price", es: "Preguntar ¿cuánto me cobra? por el servicio de un mecánico y no por un precio genérico" }
    ],
    teaching: {
      minutes: 70,
      warmUp: { en: "Create a shipping window with a package label and a mechanic's quote. Students list what must cross the counter, what needs firmar, and when price becomes personal. Spanish checkpoint: entregar becomes useful before firmar; students say why.", es: "Arme una ventanilla con etiqueta y cotización. La clase dice en inglés qué cruza el mostrador, qué se debe sign y cuándo el precio depende de la persona. Punto de control: \"drop off\" sirve antes de \"sign\"; explican por qué." },
      presentation: { en: "Show entregar by physically moving the ID copy across the desk. Put firmar on the lease page, then model ¿cuánto me cobra? as a service question to the mechanic. The board ends with entregar, firmar, and one reason ¿cuánto me cobra? belongs later.", es: "Muestre drop off moviendo la copia de cédula por la mesa. Ponga sign en el contrato y How much do you charge? como pregunta al mecánico. El tablero termina con \"drop off\", \"sign\" y una razón para aplazar \"How much do you charge?\"." },
      practice: { en: "Learners rotate through package, lease, ID, and repair desks. The repair desk rejects cuánto cuesta unless the line names the mechanic and the service being charged. Every answer cites the cue that forced entregar or blocked firmar.", es: "Rotan por paquete, contrato, cédula y reparación. La mesa del mecánico rechaza price alone si no nombran servicio y persona que cobra. Cada respuesta cita la pista que exige \"drop off\" o bloquea \"sign\"." },
      production: { en: "Stage a lost-document complaint. The clerk denies receiving the ID copy; the customer reconstructs the trail using entregar before negotiating the mechanic's charge. The final decision must include entregar and survive one objection.", es: "Represente una queja por documento perdido. Ventanilla niega recibir la copia; cliente reconstruye el rastro con drop off antes de negociar el cobro. La decisión final debe incluir \"drop off\" y resistir una objeción." },
      exitTicket: { en: "At the office door, students repair \"¿cuánto cuesta revisarlo?\" to \"¿cuánto me cobra por revisarlo?\" and add one receipt line with entregar or firmar.", es: "En la puerta de la oficina reparan \"deliver it in reception\" como \"drop it off at the front desk\" y agregan una línea con drop off o sign." },
      homework: { en: "Write two office messages: one confirms the dropped-off paper, the other asks the mechanic for an exact charge. Firmar should appear only where a signature is actually needed. Students underline the Spanish form entregar where it carries the decision.", es: "Escriben dos mensajes en inglés: uno confirma papel entregado y otro pregunta el cobro exacto al mecánico. Sign solo aparece donde haga falta firma. Subrayan la forma inglesa \"drop off\" donde sostiene la decisión." },
      support: { en: "Students confuse entregar with delivery in general. Hand them a counter diagram: document starts on my side, ends on office side, and proof stays with me.", es: "Confunden drop off con entregar a domicilio. Dé un dibujo de ventanilla: document empieza conmigo, termina en office, y proof queda en mi mano." },
      stretch: { en: "Add a clerk who says the lease rule changed. Stronger pairs concede the new rule but argue the signed copy still obligates the office. The added challenge must still keep entregar accurate in context.", es: "Agregue una funcionaria que cambió la regla del contrato. Parejas avanzadas conceden la norma nueva y defienden que la copia firmada obliga. El reto añadido conserva \"drop off\" correcto dentro del contexto." },
      errors: [
        { en: "Paper trail: they write \"¿cuánto cuesta revisarlo?\" because transfer overpowers the Paper trail scene. Put \"¿cuánto me cobra por revisarlo?\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Paper trail: dicen \"deliver it in reception\" por transferencia del español en papeleo. Corrija a \"drop it off at the front desk\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"entregar\" where this step needs \"firmar\". Name the papeleo speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"drop off\" cuando la escena necesita \"sign\". Nombre al hablante de papeleo, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "48-extending-in-the-kitchen": {
    mission: { en: "Direct a pressured kitchen by attaching commands to the right ingredient, pace, and seasoning decision.", es: "Dirigir una cocina bajo presión uniendo las órdenes al ingrediente, ritmo y decisión de sal correctos." },
    canDo: [
      { en: "Use córtelo to tell a cook exactly what to cut and how", es: "Usar córtelo para decirle a una cocinera exactamente qué cortar y cómo" },
      { en: "Slow a cooking step with mézclelo despacio when the masa or sauce needs control", es: "Frenar un paso de cocina con mézclelo despacio cuando la masa o salsa necesita control" },
      { en: "Correct a salt instruction with échale sal without using tirar", es: "Corregir una instrucción de sal con échale sal sin usar tirar" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Put fish strips and a bowl of coconut sauce in view. Learners direct a silent cook with gestures first; stop when Spanish needs a clear object in córtelo. Spanish checkpoint: córtelo becomes useful before mézclelo despacio; students say why.", es: "Ponga pescado y salsa de coco a la vista. Dirigen a una cocinera muda con gestos; detenga cuando el inglés necesite un objeto claro para cut it. Punto de control: \"cut it into strips\" sirve antes de \"mix it slowly\"; explican por qué." },
      presentation: { en: "Cut one paper fish while saying córtelo, then slow the spoon for mézclelo despacio. Introduce échale sal only when the sauce is bland, not as a random seasoning list. The board ends with córtelo, mézclelo despacio, and one reason échale sal belongs later.", es: "Corte un pescado de papel con cut it into strips y mueva la cuchara despacio para mix it slowly. Add salt entra cuando la salsa está simple. El tablero termina con \"cut it into strips\", \"mix it slowly\" y una razón para aplazar \"add salt\"." },
      practice: { en: "Pairs run six kitchen commands under time pressure. Object-pronoun cards stay visible for córtelo and mézclelo, while the salt card blocks the false verb tirar. Every answer cites the cue that forced córtelo or blocked mézclelo despacio.", es: "Parejas cumplen seis órdenes de cocina contra reloj. Tarjetas de objeto apoyan cut it y mix it; la sal bloquea la traducción throw. Cada respuesta cita la pista que exige \"cut it into strips\" o bloquea \"mix it slowly\"." },
      production: { en: "Run a service problem: the tamal masa is late and a customer is waiting. The head cook assigns cutting, mixing, and salting without blaming the helper. The final decision must include córtelo and survive one objection.", es: "Haga un servicio tenso: la masa se retrasa y espera un cliente. Jefatura reparte 'cut it into strips', 'mix it slowly' y 'add salt' sin convertirlo en pelea. La decisión final debe incluir \"cut it into strips\" y resistir una objeción." },
      exitTicket: { en: "The cook's ticket is the check: replace \"tirar sal\" with \"échale sal\" and add one command where córtelo or mézclelo despacio names a real ingredient.", es: "El ticket de cocina verifica: cambian \"cut the light\" por \"the power went out\" y agregan una orden con cut it into strips o mix it slowly." },
      homework: { en: "Write the next-shift kitchen note. It must include one cutting instruction, one pace warning, and one salt correction that would prevent a real ruined sauce. Students underline the Spanish form córtelo where it carries the decision.", es: "Escriben en inglés una nota para el siguiente turno: corte, ritmo y corrección de sal que evitaría dañar la salsa. Subrayan la forma inglesa \"cut it into strips\" donde sostiene la decisión." },
      support: { en: "The obstacle is the tiny object word, not the cooking verb. Put the ingredient card under the command and make students tap it before saying córtelo.", es: "La dificultad es el objeto pequeño, no el verbo de cocina. Ponga la tarjeta de ingrediente bajo la orden y la tocan antes de decir cut it." },
      stretch: { en: "Add a power outage during the order. Quick groups distinguish kitchen commands from the accident report and decide what food can still be served. The added challenge must still keep córtelo accurate in context.", es: "Agregue un apagón durante el pedido. Grupos rápidos separan órdenes de cocina del reporte de accidente y deciden qué plato aún sale. El reto añadido conserva \"cut it into strips\" correcto dentro del contexto." },
      errors: [
        { en: "Kitchen pressure: they write \"tirar sal\" because transfer overpowers the Kitchen pressure scene. Put \"échale sal\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Kitchen pressure: dicen \"cut the light\" por transferencia del español en cocina. Corrija a \"the power went out\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"córtelo\" where this step needs \"mézclelo despacio\". Name the cocina speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"cut it into strips\" cuando la escena necesita \"mix it slowly\". Nombre al hablante de cocina, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "49-extending-tears-and-laughter": {
    mission: { en: "Handle comfort, humor, and a public photo without turning sympathy or laughter into an insult.", es: "Manejar consuelo, humor y una foto pública sin convertir la empatía o la risa en insulto." },
    canDo: [
      { en: "Comfort someone with no llore when the moment calls for sympathy", es: "Consolar a alguien con no llore cuando el momento pide empatía" },
      { en: "Choose between reírse con and reírse de when a joke risks mockery", es: "Elegir entre reírse con y reírse de cuando un chiste corre riesgo de burla" },
      { en: "Organize a group photo with sonrían while keeping consent and tone clear", es: "Organizar una foto grupal con sonrían manteniendo claro el consentimiento y el tono" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Show the fallen ice cream, then a theater joke that lands badly. Students choose comfort, shared humor, or photo direction before any Spanish phrase appears. Spanish checkpoint: no llore becomes useful before reírse con; students say why.", es: "Muestre el helado caído y luego un chiste incómodo. El grupo elige en inglés comfort, shared humor o photo direction antes de ver frases. Punto de control: \"don't cry\" sirve antes de \"laugh with\"; explican por qué." },
      presentation: { en: "Model no llore in the ice-cream scene with a low voice. Move to reírse con for the joke recovery, and save sonrían for the group photo. The board ends with no llore, reírse con, and one reason sonrían belongs later.", es: "Modele don't cry con voz baja ante el helado. Pase a laugh with para reparar el chiste y deje smile para organizar la foto. El tablero termina con \"don't cry\", \"laugh with\" y una razón para aplazar \"smile\"." },
      practice: { en: "Students sort response cards by social risk. A card with río de ti can survive only if the speaker intends mockery; otherwise they repair the pronoun. Every answer cites the cue that forced no llore or blocked reírse con.", es: "Clasifican tarjetas por riesgo social. I laughed of you se repara porque el problema no es tono sino preposición y burla. Cada respuesta cita la pista que exige \"don't cry\" o bloquea \"laugh with\"." },
      production: { en: "Stage a school event where one joke almost humiliates a classmate before the photo. The host has to repair with reírse con and still get consent for sonreír. The final decision must include no llore and survive one objection.", es: "Represente un acto escolar donde un chiste casi humilla antes de la foto. La anfitriona repara con laugh with y pide smile sin imponer. La decisión final debe incluir \"don't cry\" y resistir una objeción." },
      exitTicket: { en: "Learners repair the social mistake by changing \"río de ti\" to \"me río de ti\"; the second line must show whether reírse con would be kinder.", es: "Reparan la burla cambiando \"I laughed of you\" por \"I laughed at you\"; la segunda frase decide si laugh with sería más amable." },
      homework: { en: "Write the apology text sent after the event. It must separate laughing with someone from laughing at someone and include one concrete line of comfort. Students underline the Spanish form no llore where it carries the decision.", es: "Escriben en inglés la disculpa posterior. Debe separar laugh with de laugh at e incluir una frase concreta de consuelo. Subrayan la forma inglesa \"don't cry\" donde sostiene la decisión." },
      support: { en: "Stuck students often know the words but miss the social target. Give them three cards: comfort, include, mock; they choose one before selecting no llore or reírse con.", es: "Quienes se traban conocen vocabulario pero no riesgo social. Dé tarjetas comfort, include, mock; eligen una antes de usar don't cry o laugh with." },
      stretch: { en: "Ask stronger groups to defend a joke that was almost acceptable. They must concede the hurt and propose a cleaner public line. The added challenge must still keep no llore accurate in context.", es: "Pida defender un chiste casi aceptable. Deben conceder el daño y proponer una frase pública más limpia. El reto añadido conserva \"don't cry\" correcto dentro del contexto." },
      errors: [
        { en: "Emotional tact: they write \"río de ti\" because transfer overpowers the Emotional tact scene. Put \"me río de ti\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Emotional tact: dicen \"I laughed of you\" por transferencia del español en emociones. Corrija a \"I laughed at you\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"no llore\" where this step needs \"reírse con\". Name the emociones speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"don't cry\" cuando la escena necesita \"laugh with\". Nombre al hablante de emociones, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "50-developing-coming-back-and-becoming": {
    mission: { en: "Talk about coming back, staying as instructed, and becoming something different without flattening every change into get.", es: "Hablar de volver, quedarse según la instrucción y convertirse en otra cosa sin reducir todo cambio a get." },
    canDo: [
      { en: "Describe returning home after years away and what feels familiar or strange", es: "Describir volver a casa después de años y qué se siente familiar o extraño" },
      { en: "Follow and give formal instructions to remain seated until a crossing ends", es: "Seguir y dar instrucciones formales para remain seated hasta terminar el cruce" },
      { en: "Explain how a building became a workshop rather than only changed appearance", es: "Explicar cómo un edificio became a workshop y no solo cambió de apariencia" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Show a sketch of the Ibagué family house with three changed landmarks. Learners mark what they recognize, what feels strange, and what still feels like home. Changed landmarks make homecoming emotional before it is grammatical.", es: "Muestra un dibujo de la casa familiar en Ibagué con tres lugares cambiados. Marcan what they recognize, what feels strange y what feels like home. Los lugares cambiados vuelven emocional el regreso." },
      presentation: { en: "Put regresaste at the doorway, not on a travel map. Ask who is receiving the return. Then contrast regresar with volver as a warmer or more formal choice. The doorway makes regresar point toward people.", es: "Pon came back en la puerta de la casa, no en un mapa. Pregunta quién recibe el regreso y contrasta return con come back por cercanía y formalidad. La puerta hace que come back apunte a personas." },
      practice: { en: "Use the Montería boat as a safety notice. Students transform stay seated into permanezcan sentados, then decide which lines sound like a friend and which sound like staff. Boat language stays formal because it is a safety notice.", es: "Usa la lancha de Montería como aviso de seguridad. Pasan remain seated a instrucciones completas y deciden qué líneas suenan a amigo y cuáles a personal. El idioma de lancha sigue formal por seguridad." },
      production: { en: "Walk through the Arauca warehouse visit. One neighbor remembers storage, one sees the workshop now, and one explains the change as a new identity, not fresh paint. Paint is not enough; the warehouse needs a new identity. Use se convirtió for the new identity.", es: "Recorre la bodega de Arauca. Una persona recuerda el depósito, otra ve el taller actual y otra explica el cambio como identidad nueva, no pintura reciente. Paint no basta; warehouse necesita identidad nueva." },
      exitTicket: { en: "Ask for one sentence with se convirtió en or became a workshop. It must name the old thing and the new thing. Old thing plus new thing proves convertirse en.", es: "Pide una oración con became a workshop. Debe nombrar qué era antes y qué es ahora. Old thing y new thing prueban became." },
      homework: { en: "Describe a place you returned to after time away. Include one thing still yours, one thing changed, and one instruction someone gave you there. The returned place must contain both recognition and distance. Name regresé when the place receives you.", es: "Describe un lugar al que volviste después de tiempo. Incluye algo todavía tuyo, algo cambiado y una instrucción que alguien te dio allí. El lugar de regreso contiene reconocimiento y distancia." },
      support: { en: "If convertirse en becomes ponerse, draw two changes: angry person and warehouse workshop. The learner chooses which change is mood and which is identity. Mood change and identity change must not share one verb.", es: "Si become se vuelve get para todo, dibuja dos cambios: persona brava y bodega taller. El estudiante escoge mood o identity antes de hablar. Mood change e identity change no comparten verbo." },
      stretch: { en: "Have quick learners argue whether Alex belongs at home or feels like a visitor. They must use regresar once and defend the emotional result. Alex’s belonging is the argument, not the scenery.", es: "Haz que los adelantados discutan si Alex pertenece a casa o se siente visitante. Usan come back una vez y defienden el resultado emocional. La pertenencia de Alex es el argumento, no el paisaje." },
      errors: [
        { en: "They write \"Regresé en la casa\". Replace it with \"Regresé a la casa\". Use a with regresar for destination. En only says where you are located.", es: "Cuando alguien dice \"I returned to home\", no lo corrijas con traducción. Pon \"I came back home\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"La bodega se puso taller\". Replace it with \"La bodega se convirtió en taller\". Ponerse fits a state like ponerse bravo; convertirse en marks a real new identity.", es: "Si aparece \"The warehouse converted in a workshop\", detén la ronda y escribe \"The warehouse became a workshop\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "51-developing-belonging": {
    mission: { en: "Work out what belongs in a price, a chat, or a group, and repair the moment when someone is left out.", es: "Averiguar qué pertenece a una tarifa, a un chat o a un grupo, y reparar cuando alguien queda por fuera." },
    canDo: [
      { en: "Ask what a room rate includes and what costs extra", es: "Preguntar qué incluye una tarifa y qué cuesta extra" },
      { en: "Explain that someone was excluded from a chat by accident or by rule", es: "Explicar que alguien quedó excluido del chat por accidente o por regla" },
      { en: "Ask whether you belong to a group or only feel part of it", es: "Preguntar si perteneces a un grupo o solo te sientes parte" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Write a room price, a team chat, and a bike group on the board. Students decide what is inside each circle and who is outside it. The circles make price, chat, and group membership visible. Ask incluye when the price circle closes.", es: "Escribe una tarifa, un chat de equipo y un grupo de bici en el tablero. Deciden what is included y quién queda outside. Los círculos muestran price, chat y membership." },
      presentation: { en: "Start with ¿la tarifa incluye desayuno? and physically put breakfast inside the price box. Move taxes outside to introduce se paga aparte. Breakfast physically moves inside the price box. Check the box physically.", es: "Empieza con Does the rate include breakfast? y mete breakfast dentro de la caja de precio. Saca taxes para presentar extra. Breakfast entra físicamente en la caja de precio." },
      practice: { en: "Use the Buenaventura tournament chat. Each card says why Javi is missing: accident, rule, or invitation failure. Learners choose excluir or dejar por fuera. Javi’s absence must be accident, rule, or failed invitation.", es: "Usa el chat del torneo de Buenaventura. Cada tarjeta dice por qué falta Javi: accidente, regla o invitación fallida. Escogen exclude o leave out. La ausencia de Javi es accident, rule o failed invitation." },
      production: { en: "Run the Arauca cycling-group conversation. A newcomer wants to ride Sunday, the organizer checks registration, and the group decides whether belonging is official or social. Official membership and welcome feeling can disagree. Use pertenezco for official membership.", es: "Haz la conversación del grupo de bici en Arauca. Una persona nueva quiere salir el domingo, la organizadora revisa registro y deciden si belonging es oficial o social. Official membership y welcome feeling pueden no coincidir. Usa belong cuando el registro importe." },
      exitTicket: { en: "Collect one rate question with incluye and one answer naming what costs extra. The answer must settle money, not just vocabulary. The answer must settle what the guest pays.", es: "Recoge una pregunta de tarifa con include y una respuesta que nombre lo extra. La respuesta debe resolver dinero, no solo vocabulario. La respuesta resuelve qué paga el huésped." },
      homework: { en: "Make a small booking note for Montería. Ask about breakfast, air conditioning, and taxes, then write the reply you would need before paying. The reply decides whether the booking is safe. Use incluye before asking about taxes.", es: "Haz una nota de reserva para Montería. Pregunta por breakfast, air conditioning y taxes, luego escribe la respuesta necesaria antes de pagar. La respuesta decide si la reserva es segura." },
      support: { en: "If pertenecer sounds abstract, draw the bike group as a membership card and a Sunday ride. The learner says whether each person belongs officially or only feels welcome. Membership card and Sunday ride separate belonging from welcome.", es: "Si belong suena abstracto, dibuja el grupo como tarjeta de miembro y salida dominical. El estudiante dice quién belongs officially y quién only feels welcome. Membership card y Sunday ride separan belong de welcome." },
      stretch: { en: "Give advanced learners a dispute: a rule excludes one player unfairly. They must propose a fix that includes Javi without breaking the tournament rules. The fix includes Javi without breaking the tournament. Make incluye repair the unfair rule.", es: "Da a los avanzados un conflicto: una regla excluye injustamente a un jugador. Proponen una solución que includes Javi sin romper reglas del torneo. La solución includes Javi sin romper el torneo." },
      errors: [
        { en: "They write \"Incluye con desayuno\". Replace it with \"Incluye desayuno\". Incluir takes the included item directly. Con makes the room sound accompanied by breakfast.", es: "Cuando alguien dice \"Does include breakfast?\", no lo corrijas con traducción. Pon \"Does the rate include breakfast?\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Pertenezco en el grupo\". Replace it with \"Pertenezco al grupo\". Use pertenecer a for membership. En only says where someone is physically placed.", es: "Si aparece \"I belong in the bike group\", detén la ronda y escribe \"I belong to the bike group\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "52-developing-what-happened": {
    mission: { en: "Tell what happened and how it turned out, choosing a street version, a written account, or a personal reaction.", es: "Contar qué pasó y cómo resultó, escogiendo una versión cotidiana, una crónica escrita o una reacción personal." },
    canDo: [
      { en: "Explain what happened when rain ruined a plan and suggest another option", es: "Explicar qué pasó cuando la lluvia dañó un plan y proponer otra opción" },
      { en: "Write a calm account of what happened without sounding alarmist", es: "Escribir un relato calmado de lo ocurrido sin sonar alarmista" },
      { en: "Say how an errand turned out and why the result feels strange", es: "Decir cómo salió una vuelta y por qué el resultado parece raro" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Tell the class the lookout plan failed, but do not say why. Students ask only questions they already know until rain, timing, and an alternative route appear. Withholding the cause makes real questions necessary.", es: "Cuenta que falló el plan del mirador, sin decir por qué. Hacen solo preguntas conocidas hasta que aparezcan rain, timing y another option. Ocultar la causa hace necesarias preguntas reales." },
      presentation: { en: "Write ¿qué fue lo que ocurrió? beside ¿qué pasó? Ask which one sounds like the lesson text and which one sounds more street-level. Ocurrió sounds shaped; pasó sounds street-level. Mark the tone difference.", es: "Escribe What exactly happened? junto a What happened? Pregunta cuál pide detalle y cuál sirve para una conversación rápida. What exactly happened pide forma; what happened sirve rápido." },
      practice: { en: "Give three mixed accounts: Ibagué rain, Montería raffle, Arauca errand. Learners sort ocurrió, sucedió, and resultó by street talk, written account, and final outcome. The genre chooses the verb before the story expands.", es: "Entrega tres relatos mezclados: lluvia, rifa y vuelta. Clasifican what happened, there was y turned out según conversación, informe escrito y resultado final. El género escoge el verbo antes de ampliar la historia." },
      production: { en: "Teams defend different versions of the Arauca appointment problem. One says the office failed, one says the group misunderstood, and one reports the result calmly. Blame changes the account, so teams must defend evidence.", es: "Los equipos defienden versiones del problema de cita en Arauca. Uno culpa la oficina, otro el malentendido y otro reporta el resultado con calma. Blame cambia el relato, así que defienden evidence." },
      exitTicket: { en: "Ask for one sentence with resultó ser or turned out to be. It must include the expectation and the surprise. Expectation plus surprise proves resultar.", es: "Pide una oración con turned out to be. Debe incluir lo esperado y la sorpresa. Expectation más surprise prueban turned out." },
      homework: { en: "Write a neighborhood update about the raffle in five lines. Use facts first, then one sentence saying how the plan turned out. Facts first keeps the raffle note calm. Use sucedió for the written neighbor note.", es: "Escribe una actualización barrial de cinco líneas sobre la rifa. Usa facts primero y luego una oración que diga how it turned out. Facts primero mantiene calmado el informe." },
      support: { en: "For se me ocurrió, put idea in the subject box and me in the receiver box. Students stop trying to make the person do the occurring. The idea is the subject; the person receives it.", es: "Para An idea occurred to me, pon idea en la casilla de sujeto y to me en receptor. Así dejan de hacer que la persona ejecute el verbo. Idea es sujeto; to me recibe la ocurrencia." },
      stretch: { en: "Ask quick learners to make the written account less alarmist. They must remove blame words while keeping the facts about the raffle confusion. Less blame should still leave the confusion understandable. Keep sucedió after removing blame words.", es: "Pide a los adelantados volver menos alarmista el informe. Quitan palabras de culpa y conservan los facts sobre la confusión de la rifa. Menos blame debe dejar comprensible la confusión." },
      errors: [
        { en: "They write \"Me ocurrió una idea\". Replace it with \"Se me ocurrió una idea\". Ideas occur to you in Spanish. Use se me ocurrió, not ocurrir as a normal transitive verb.", es: "Cuando alguien dice \"It occurred me an idea\", no lo corrijas con traducción. Pon \"An idea occurred to me\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Resultó largo la vuelta\". Replace it with \"La vuelta resultó larga\". Make the adjective agree with la vuelta, and put the thing that turned out before the result.", es: "Si aparece \"The errand resulted longer\", detén la ronda y escribe \"The errand turned out longer\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "53-developing-deals-and-demands": {
    mission: { en: "Make agreements, meet obligations, and demand a fair answer only when the situation gives you the right to do it.", es: "Hacer acuerdos, cumplir compromisos y exigir una respuesta justa solo cuando la situación te da derecho a hacerlo." },
    canDo: [
      { en: "Agree on a repair price and date without confusing it with agreeing with an opinion", es: "Acordar precio y fecha de una reparación sin confundirlo con agree with" },
      { en: "Talk about turning thirty, meeting a time, and keeping a promise", es: "Hablar de turning thirty, meet a time y keep a promise" },
      { en: "Demand a refund with evidence while keeping request and demand separate", es: "Exigir un refund con evidencia separando request de demand" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Put three papers on the desk: estimate, birthday invitation, complaint form. Students decide which paper needs agreement, which needs a promise, and which needs evidence. The three papers separate plan, celebration, and complaint. Put acordar on the estimate only.", es: "Pon tres papeles: cotización, invitación de cumpleaños y formulario de queja. Deciden cuál necesita agreement, cuál promise y cuál evidence. Los tres papeles separan plan, celebration y complaint." },
      presentation: { en: "Use ¿acordamos el arreglo para el viernes? with a calendar square. Contrast it with estoy de acuerdo so learners separate a fixed repair plan from an opinion. The calendar square keeps agreement tied to date and price.", es: "Usa Did we agree on Friday? con un calendario. Contrasta agree on con agree with para separar plan de reparación y opinión. El calendario ata agree on a fecha y precio." },
      practice: { en: "Give a repair chart with price, date, leak, and materials. Students complete acordamos lines, then catch the one card that really means acordarse de. Acordarse de is the decoy, not another repair agreement.", es: "Entrega una tabla de reparación con precio, fecha, gotera y materiales. Completan líneas con agreed on y detectan la tarjeta que significa remember. Remember es la trampa, no otro acuerdo de arreglo." },
      production: { en: "Hold the Buenaventura complaint counter. The customer has proof, the clerk offers delay, and the class decides when exigir is justified and when solicitar is enough. Evidence decides whether exigir is fair.", es: "Haz el mostrador de quejas en Buenaventura. El cliente trae pruebas, la empleada aplaza y la clase decide cuándo demand se justifica y cuándo request basta. Evidence decide si demand es justo." },
      exitTicket: { en: "Collect one refund demand with exijo or I demand. It must include the right, the evidence, and the answer requested. A demand without a requested answer is just anger.", es: "Recoge una exigencia de reembolso con I demand. Debe incluir el derecho, la evidencia y la respuesta solicitada. Demand sin respuesta solicitada es solo enojo." },
      homework: { en: "Write two versions of the roof-leak message: one to settle date and price, one to say you agree with an opinion. Keep the verbs different. The two messages prove agree on and agree with differ. Use acordamos for the repair message.", es: "Escribe dos versiones del mensaje por la gotera: una para fijar fecha y precio, otra para agree with una opinión. Mantén distintos los verbos. Los dos mensajes prueban la diferencia agree on y agree with." },
      support: { en: "If cumplir gets reduced to birthdays, show three cards: turn thirty, meet a deadline, keep a promise. Learners match each card to a different obligation. Cumplir must leave the birthday party and enter obligations.", es: "Si cumplir se reduce a birthdays, muestra turn thirty, meet a deadline y keep a promise. Relacionan cada tarjeta con una obligación distinta. Keep a promise saca birthday hacia obligaciones." },
      stretch: { en: "Give early finishers weak evidence for a refund. They must decide whether to demand, request, or wait, and defend the tone they choose. Weak evidence should lower the force of the complaint. Reserve exigir for evidence that holds.", es: "Da a los adelantados evidencia débil para un reembolso. Deciden si demand, request o wait, y defienden el tono escogido. Evidencia débil baja la fuerza de complaint." },
      errors: [
        { en: "They write \"Estoy acordado con el precio\". Replace it with \"Estoy de acuerdo con el precio\". Acordar sets a plan; estar de acuerdo gives an opinion or acceptance. Do not mix the two.", es: "Cuando alguien dice \"We accorded Friday\", no lo corrijas con traducción. Pon \"We agreed on Friday\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Exijo que me devuelven la plata\". Replace it with \"Exijo que me devuelvan la plata\". After exigir que, use the subjunctive because you are demanding an action, not reporting it.", es: "Si aparece \"I exig a refund\", detén la ronda y escribe \"I demand a refund\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "54-developing-weighing-it-up": {
    mission: { en: "Weigh options with other people by discussing calmly, comparing evidence, and saying what the answer depends on.", es: "Sopesar opciones con otras personas discutiendo con calma, comparando evidencia y diciendo de qué depende la respuesta." },
    canDo: [
      { en: "Open a calm discussion about a project without starting a fight", es: "Abrir una discusión calmada sobre un proyecto sin empezar pelea" },
      { en: "Compare two phone plans using price, coverage, and data as evidence", es: "Comparar dos planes usando precio, cobertura y datos como evidencia" },
      { en: "Answer it depends and name the weather, car, or timing condition", es: "Responder it depends y nombrar la condición de clima, carro u horario" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Draw a poster draft, two phone plans, and a muddy farm road. Learners list what evidence would change their mind in each case. Evidence, not preference, is what can change minds. Rank the evidence quickly. Use comparar only after evidence appears.", es: "Dibuja un afiche, dos planes de celular y un camino embarrado. Enumeran qué evidence cambiaría su decisión en cada caso. Evidence, no preference, puede cambiar decisiones. Haz una lista breve. Usa compare cuando haya evidencia real." },
      presentation: { en: "Put discutir el afiche on the board and ask whether anyone is fighting yet. Add pelear only after students hear that discutir can mean review calmly. Discutir is allowed to stay calm in this poster room.", es: "Pon discuss the poster en el tablero y pregunta si alguien está peleando. Agrega argue cuando oigan que discuss puede ser una revisión tranquila. Discuss puede seguir calmado en este afiche." },
      practice: { en: "Use two Florencia phone-plan cards with data, coverage, and price. Students must compare with one category at a time before saying no hay comparación. One category at a time prevents fake comparison.", es: "Usa dos tarjetas de planes con datos, cobertura y precio. Comparan con una categoría a la vez antes de decir there is no comparison. Una categoría por vez evita comparación falsa." },
      production: { en: "Plan the Arauca farm route under uncertain weather. One group trusts the borrowed car, one fears the rain, and one answers depende with conditions. Depende must name weather, car, or timing. Force a final route.", es: "Planea la ruta a la finca con clima incierto. Un grupo confía en el carro prestado, otro teme la lluvia y otro responde it depends con condiciones. It depends nombra weather, car o timing." },
      exitTicket: { en: "Ask for one answer beginning depende or it depends. The next words must name the factor, not dodge the decision. The factor after depende is the whole point.", es: "Pide una respuesta que empiece it depends. Las palabras siguientes deben nombrar el factor, no esquivar la decisión. El factor después de it depends es el punto." },
      homework: { en: "Compare two real phone plans from memory or imagination. Write four facts, then choose one plan and explain what your choice depends on. The chosen plan must rest on a stated condition. End with depende plus one named condition.", es: "Compara dos planes de celular reales o inventados. Escribe cuatro facts, escoge uno y explica what your choice depends on. El plan elegido descansa en una condición clara." },
      support: { en: "For depender de, use a hinge drawing: route on one side, weather on the other. The student says the hinge word before building the full sentence. The hinge makes de or on unavoidable.", es: "Para depend on, dibuja una bisagra: route a un lado, weather al otro. El estudiante dice on antes de construir la oración completa. La bisagra vuelve obligatorio on." },
      stretch: { en: "Ask fast finishers to chair the poster meeting. They must keep discutir calm while making one real change to the design. A calm meeting still has to alter the poster.", es: "Pide a los adelantados dirigir la reunión del afiche. Mantienen discuss sin pelea y logran un cambio real en el diseño. Una reunión calmada todavía cambia el poster." },
      errors: [
        { en: "They write \"Discutimos por el afiche\". Replace it with \"Discutimos el afiche\". Use discutir directly for reviewing the poster. Por makes it sound like a fight over it.", es: "Cuando alguien dice \"We discussed about the poster\", no lo corrijas con traducción. Pon \"We discussed the poster\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Depende en el carro\". Replace it with \"Depende del carro\". Depender takes de in Spanish, even when English wants on.", es: "Si aparece \"It depends of the car\", detén la ronda y escribe \"It depends on the car\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "55-developing-meaning-and-growth": {
    mission: { en: "Ask what something means, build a project step by step, and calculate whether time or money will be enough.", es: "Preguntar qué significa algo, desarrollar un proyecto paso a paso y calcular si el tiempo o la plata alcanzan." },
    canDo: [
      { en: "Ask what a word means and explain what you meant without a false friend", es: "Preguntar What does it mean y explicar I mean sin falso amigo" },
      { en: "Describe how a workshop or skill develops over time", es: "Describir cómo un workshop o skill develops con el tiempo" },
      { en: "Say whether money or time is enough and what you managed to do", es: "Decir si tienes enough money o time y qué managed to hacer" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Write guabina on the board with no translation. Students guess from music, place, and announcement, then mark which guesses are meaning and which are associations. Guabina forces guessing before definition. Delay the dictionary answer.", es: "Escribe fiddle en el tablero sin traducción. Adivinan por music, place y announcement, luego separan meaning de associations. Hazlo ahora. Fiddle obliga a adivinar antes de definir." },
      presentation: { en: "Ask ¿qué significa guabina? and answer with significa que only once. Then contrast querer decir so learners can ask about meaning without saying significar every time. Meaning and intention share a verb but not a job.", es: "Pregunta What does fiddle mean? y contesta una vez. Luego contrasta I mean para mostrar que mean sirve para significado y para aclarar intención. Meaning e intention comparten verbo, no función." },
      practice: { en: "Give pairs a workshop plan with empty steps: materials, camera skills, final exhibit. They choose desarrollar un taller or desarrollar habilidades for each step. Materials and skills develop on different timelines. Name the next step.", es: "Entrega un plan de taller con pasos vacíos: materiales, habilidades de cámara, muestra final. Escogen develop a workshop o develop skills en cada paso. Materials y skills se desarrollan en ritmos distintos." },
      production: { en: "Run the Arauca grocery calculation. Diego has money, groceries, taxi fare, and a call time; the pair must decide what alcanza and what gets cut. The taxi fare competes with groceries and the call.", es: "Haz las cuentas del mercado en Arauca. Diego tiene plata, comida, taxi y hora de llamada; la pareja decide what there is enough money for y qué se recorta. Taxi fare compite con groceries y call." },
      exitTicket: { en: "Collect one sentence with no me alcanza la plata. It must name the purchase that fails and one possible adjustment. The failed purchase reveals the budget problem.", es: "Recoge una oración con I don’t have enough money. Debe nombrar la compra que falla y un ajuste posible. La compra fallida revela el problema de budget." },
      homework: { en: "Write a note for Lina’s photography workshop. Name one material to develop, one skill to practice, and one budget limit that may not reach. The workshop note links development to a money limit. Use desarrollar for the workshop material.", es: "Escribe una nota para el taller de fotografía. Nombra un material to develop, una skill para practicar y un límite de presupuesto. La nota conecta develop con límite de dinero." },
      support: { en: "If alcanzar becomes reach, put coins beside groceries. Ask whether the money travels across the table or simply is enough. Then write the English sentence. Coins do not travel; they either cover the list or fail.", es: "Si alcanzar se vuelve reach, pon monedas junto al mercado. Pregunta si el dinero viaja por la mesa o simplemente is enough, y escribe la frase. Las monedas no viajan; cubren la lista o fallan." },
      stretch: { en: "Ask advanced learners to explain guabina to a visitor without using a dictionary definition. They must include one example and one clarification with o sea. An example should explain more than a dictionary line.", es: "Pide a los avanzados explicar fiddle a un visitante sin definición de diccionario. Incluyen un ejemplo y una aclaración con I mean. Un example explica más que una definición." },
      errors: [
        { en: "They write \"¿Qué quiere decir guabina? means what?\". Replace it with \"¿Qué significa guabina?\". Keep the Spanish question in Spanish. Do not bolt an English question onto it.", es: "Cuando alguien dice \"What means fiddle?\", no lo corrijas con traducción. Pon \"What does fiddle mean?\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"No alcanzo la plata\". Replace it with \"No me alcanza la plata\". The money is what is enough or not; me marks the person affected.", es: "Si aparece \"The money does not reach me\", detén la ronda y escribe \"I don’t have enough money\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "56-developing-love-and-plenty": {
    mission: { en: "Choose the right weight for love and plenty, so warmth, romance, leftovers, and spare time do not get mixed up.", es: "Escoger el peso correcto para amor y abundancia, sin mezclar cariño, romance, sobras y tiempo de sobra." },
    canDo: [
      { en: "Respond warmly to te quiero without rushing into te amo", es: "Responder con calidez a Love you sin convertirlo todo en romance" },
      { en: "Say what food or time is left after lunch and what can be saved", es: "Decir qué food is left over y qué time to spare queda" },
      { en: "Separate literal love from liking, caring, and loving a place", es: "Separar I love you de I like you, I care about you y love a place" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Put three goodbye lines on the board: friendly, romantic, and family. Students place te quiero mucho before you reveal why te amo is heavier. Relationship cards keep affection from becoming one word.", es: "Pon tres despedidas en el tablero: amistad, romance y familia. Ubican Love you antes de revelar por qué I love you puede pesar más. Las tarjetas de relación evitan una sola palabra para afecto." },
      presentation: { en: "Use Camila’s Barichara goodbye to contrast te quiero and te amo. Ask what relationship the line protects, then show why a direct translation can rush the moment. The goodbye protects friendship from a rushed romance reading.", es: "Usa la despedida de Barichara para contrastar I love you, Love you y I care about you. Pregunta cuál protege amistad y cuál puede sonar romántica. La despedida protege friendship de una lectura romántica." },
      practice: { en: "Give pairs six farewell cards with relationship clues. They choose te quiero, te amo, or amo esta ciudad, then explain which line would make the scene awkward. The awkward line is the one students must notice.", es: "Entrega seis tarjetas de despedida con pistas de relación. Escogen Love you, I love you o I love this city y explican qué frase volvería incómoda la escena. La frase incómoda es la que deben notar." },
      production: { en: "Set the Florencia lunch table after everyone has eaten. One person wants to pack rice, one wants coffee, and one decides what sobra without insulting the host. The host’s face decides how leftovers are mentioned.", es: "Monta la mesa de Florencia después del almuerzo. Una persona quiere guardar arroz, otra quiere café, y otra decide what is left over sin ofender a la anfitriona. La cara de la anfitriona decide cómo decir leftovers." },
      exitTicket: { en: "Ask for one leftovers sentence with sobró or left over. It must name the food and what will happen to it. Food plus next action proves sobrar.", es: "Pide una oración de sobras con left over. Debe nombrar la comida y qué pasará con ella. Food más next action prueba left over." },
      homework: { en: "Write two tiny scenes: a ceramics goodbye and a family table cleanup. Keep love language out of the food scene and leftover language out of the goodbye. The two scenes should not leak language into each other. Keep te quiero inside the goodbye. Use sobró only at the table.", es: "Escribe dos escenas mínimas: una despedida de taller y una recogida de mesa familiar. No mezcles love language con leftovers. Las dos escenas no deben contaminarse." },
      support: { en: "If te quiero and te amo feel identical, give relationship cards: friend, partner, city, parent. The learner chooses the safest line before speaking. Choose the relationship before choosing the love phrase. Use te amo only after the relationship card. Write te quiero beside amar before choosing.", es: "Si I love you y Love you suenan idénticos, da tarjetas de relación: friend, partner, city, parent. El estudiante escoge la frase más segura antes de hablar. Escoge relationship antes de escoger I love you." },
      stretch: { en: "Have fast finishers rescue a foot-in-mouth moment. Someone answered te quiero with te amo; they must repair the warmth without joking it away. The repair must keep warmth without pretending nothing happened.", es: "Haz que los adelantados reparen una metida de pata. Alguien respondió Love you demasiado fuerte; deben conservar cariño sin convertirlo en chiste. La reparación conserva warmth sin fingir que no pasó nada." },
      errors: [
        { en: "They write \"Te amo mucho, amiga\". Replace it with \"Te quiero mucho, amiga\". Te amo is too heavy for this friendly goodbye. Use te quiero mucho unless the relationship is romantic or deeply intimate.", es: "Cuando alguien dice \"I like you, said to a close friend leaving\", no lo corrijas con traducción. Pon \"Love you, said to a close friend leaving\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"La comida sobrated\". Replace it with \"Sobró comida\". Do not invent an English-looking Spanish verb. Sobró comida is the natural report after lunch.", es: "Si aparece \"The food sobrated\", detén la ronda y escribe \"There is food left over\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "57-extending-thinking-it-over": {
    mission: { en: "Keep a serious decision open while acknowledging a surprise, a changed plan, or someone you did not recognize.", es: "Mantener abierta una decisión importante mientras reconoces una sorpresa, un plan cambiado o a alguien que no reconociste." },
    canDo: [
      { en: "Delay an answer politely with lo voy a considerar instead of giving a false yes", es: "Aplazar una respuesta con cortesía usando lo voy a considerar en vez de dar un sí falso" },
      { en: "Use imagínate que to introduce a changed trip or unexpected consequence", es: "Usar imagínate que para introducir un viaje cambiado o una consecuencia inesperada" },
      { en: "Say no te reconocí without turning the old-classmate moment into an accusation", es: "Decir no te reconocí sin convertir el encuentro con un antiguo compañero en acusación" }
    ],
    teaching: {
      minutes: 70,
      warmUp: { en: "Place the border job offer beside a changed trip plan. Students mark which decisions are final, delayed, or imagined; delay creates the need for lo voy a considerar. Spanish checkpoint: lo voy a considerar becomes useful before imagínate que; students say why.", es: "Ponga la oferta de frontera junto al viaje cambiado. En inglés marcan decisiones finales, aplazadas o imaginadas; la demora exige I'll consider it. Punto de control: \"I'll consider it\" sirve antes de \"imagine if\"; explican por qué." },
      presentation: { en: "Treat lo voy a considerar as a respectful delay, not indecision. Use imagínate que for the surprising trip change and no te reconocí with the old classmate photo. The board ends with lo voy a considerar, imagínate que, and one reason no te reconocí belongs later.", es: "Presente I'll consider it como pausa respetuosa, no evasión. Use imagine if con el viaje cambiado y I didn't recognize you con la foto antigua. El tablero termina con \"I'll consider it\", \"imagine if\" y una razón para aplazar \"I didn't recognize you\"." },
      practice: { en: "Learners answer pressure lines from an employer, a friend, and a classmate. They must decide whether the line needs delay, imagination, or recognition before speaking. Every answer cites the cue that forced lo voy a considerar or blocked imagínate que.", es: "Responden presiones de empleador, amiga y compañero. Deciden si la frase pide delay, imagination o recognition antes de hablar. Cada respuesta cita la pista que exige \"I'll consider it\" o bloquea \"imagine if\"." },
      production: { en: "Hold a family meeting about the border job. One person wants the salary, another fears the move, and the candidate keeps the decision open without sounding vague. The final decision must include lo voy a considerar and survive one objection.", es: "Haga reunión familiar sobre el empleo. Alguien quiere el salario, otra persona teme la mudanza y quien decide usa I'll consider it sin sonar vacío. La decisión final debe incluir \"I'll consider it\" y resistir una objeción." },
      exitTicket: { en: "Open decision exit ticket: rewrite \"si habría sabido\" as \"si hubiera sabido\" inside the job-offer reply. Add a second sentence showing why the speaker still has not accepted.", es: "Open decision salida: cambian \"I will think in it\" por \"I'll think it over\" en la respuesta al empleo. Añaden una segunda frase que mantiene abierta la decisión." },
      homework: { en: "Write tomorrow's message to the employer. It must include lo voy a considerar, one imagined consequence, and a clear point that would change the decision. Students underline the Spanish form lo voy a considerar where it carries the decision.", es: "Escriben en inglés el mensaje del día siguiente: I'll consider it, una consecuencia imaginada y un dato que cambiaría la decisión. Subrayan la forma inglesa \"I'll consider it\" donde sostiene la decisión." },
      support: { en: "The support is a stance map. Students stand on accept, delay, or refuse before using lo voy a considerar so the phrase does not become hesitation noise.", es: "Use un mapa de postura: accept, delay, refuse. Se paran antes de decir I'll consider it para que no sea una muletilla." },
      stretch: { en: "Add a late counteroffer. Early finishers revise their position and explain what they would have done if they had known sooner. The added challenge must still keep lo voy a considerar accurate in context.", es: "Agregue una contraoferta tardía. Quienes avanzan explican qué habrían hecho con información previa. El reto añadido conserva \"I'll consider it\" correcto dentro del contexto." },
      errors: [
        { en: "Open decision: they write \"si habría sabido\" because transfer overpowers the Open decision scene. Put \"si hubiera sabido\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Open decision: dicen \"I will think in it\" por transferencia del español en decisiones. Corrija a \"I'll think it over\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"lo voy a considerar\" where this step needs \"imagínate que\". Name the decisiones speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"I'll consider it\" cuando la escena necesita \"imagine if\". Nombre al hablante de decisiones, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "58-extending-showing-up": {
    mission: { en: "Report public presence by separating introducing a speaker, attending a hearing, participating in a drill, and helping a neighbor.", es: "Informar presencia pública separando presentar a un ponente, asistir a una audiencia, participar en un simulacro y ayudar a una vecina." },
    canDo: [
      { en: "Use presentar to introduce the speaker rather than to say who attended", es: "Usar presentar para introducir al ponente y no para decir quién asistió" },
      { en: "Say asistir a a hearing when the other person assumes you meant helping", es: "Decir asistir a una audiencia cuando la otra persona cree que quisiste decir ayudar" },
      { en: "Assign who will participar en a flood drill and who only attended", es: "Asignar quién va a participar en un simulacro y quién solo asistió" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Arrange the room as a hearing: speaker chair, public seats, volunteer table. Students label who introduces, who attends, and who helps outside the room. Spanish checkpoint: presentar becomes useful before asistir a; students say why.", es: "Organice una audiencia: silla de ponente, público y mesa voluntaria. En inglés separan introduce, attend y help fuera del salón. Punto de control: \"introduce\" sirve antes de \"attend\"; explican por qué." },
      presentation: { en: "Use presentar with the speaker card, not with being present. Move a name tag into the hearing for asistir a, then use participar en for the drill volunteer. The board ends with presentar, asistir a, and one reason participar en belongs later.", es: "Use introduce con la tarjeta de ponente, no con estar presente. Lleve name tag a attend y chaleco de simulacro a participate. El tablero termina con \"introduce\", \"attend\" y una razón para aplazar \"participate\"." },
      practice: { en: "Agenda cards contain deliberate false friends. Students repair asistí a mi vecina as help, while hearing-room cards require asistir a without apology. Every answer cites the cue that forced presentar or blocked asistir a.", es: "Tarjetas de agenda traen falsos amigos. Reparan assist to the hearing como attend the hearing y distinguen ayudar a la vecina. Cada respuesta cita la pista que exige \"introduce\" o bloquea \"attend\"." },
      production: { en: "Run a flood-drill briefing. The coordinator introduces the speaker, logs attendees, and assigns participants while a reporter challenges each verb choice publicly. The final decision must include presentar and survive one objection.", es: "Haga una reunión de simulacro. Coordinación introduces speaker, registra attendees y asigna participants mientras una periodista cuestiona verbos. La decisión final debe incluir \"introduce\" y resistir una objeción." },
      exitTicket: { en: "On the hearing agenda, students change \"asistí a mi vecina\" to \"ayudé a mi vecina\" and add one separate sentence with asistir a the hearing.", es: "En la agenda reparan \"assist to the hearing\" como \"attend the hearing\" y añaden otra frase donde introduce o participate no se confunda con help." },
      homework: { en: "Write the public notice for the drill. It has to introduce one speaker, invite residents to attend, and ask two neighbors to participate in a task. Students underline the Spanish form presentar where it carries the decision.", es: "Redactan en inglés el aviso: introduce one speaker, invite residents to attend y pedir a dos vecinos que participate. Subrayan la forma inglesa \"introduce\" donde sostiene la decisión." },
      support: { en: "The hard part is the false friend. Give two badges, attend and help; the Spanish target is asistir a, not ayudar, before the sentence is formed.", es: "El obstáculo es el falso amigo. Dé dos escarapelas, attend y help; la persona usa la correcta antes de armar la frase." },
      stretch: { en: "Add a neighbor who truly needs help during the hearing. Strong groups must report both facts without letting assist replace attend. The added challenge must still keep presentar accurate in context.", es: "Agregue una vecina que sí necesita ayuda durante la audiencia. Grupos fuertes reportan ambos hechos sin dejar que assist reemplace attend. El reto añadido conserva \"introduce\" correcto dentro del contexto." },
      errors: [
        { en: "Public presence: they write \"asistí a mi vecina\" because transfer overpowers the Public presence scene. Put \"ayudé a mi vecina\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Public presence: dicen \"assist to the hearing\" por transferencia del español en presencia pública. Corrija a \"attend the hearing\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"presentar\" where this step needs \"asistir a\". Name the presencia pública speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"introduce\" cuando la escena necesita \"attend\". Nombre al hablante de presencia pública, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "59-extending-staying-in-touch": {
    mission: { en: "Recover a broken call by naming the contact, explaining the signal failure, and restarting the agenda efficiently.", es: "Recuperar una llamada rota nombrando el contacto, explicando la falla de señal y retomando la agenda con eficiencia." },
    canDo: [
      { en: "Say me comunico con plus the right person from a guide or family list", es: "Decir me comunico con más la persona correcta de una lista de guía o familia" },
      { en: "Report se me cayó la señal without blaming the speaker or the device vaguely", es: "Reportar se me cayó la señal sin culpar vagamente al hablante o al aparato" },
      { en: "Restart a meeting with continuemos after summarizing what was missed", es: "Retomar una reunión con continuemos después de resumir lo perdido" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Freeze a video-call screen with a guide waiting. Students decide who to contact, what failed, and whether the meeting can continue without repeating everything. Spanish checkpoint: comunicarse con becomes useful before se me cayó la señal; students say why.", es: "Congele una videollamada con la guía esperando. La clase dice en inglés a quién contactar, qué falló y si se puede continue sin repetir todo. Punto de control: \"get in touch with\" sirve antes de \"my signal dropped\"; explican por qué." },
      presentation: { en: "Model me comunico con from the family contact list. Drop the connection mid-sentence for se me cayó la señal, then restart with continuemos. The board ends with comunicarse con, se me cayó la señal, and one reason continuemos belongs later.", es: "Modele get in touch with desde la lista familiar. Corte la conexión para my signal dropped y reinicie la agenda con let's continue. El tablero termina con \"get in touch with\", \"my signal dropped\" y una razón para aplazar \"let's continue\"." },
      practice: { en: "Pairs run short calls where one instruction disappears. They must name the person, report se me cayó la señal, and resume with continuemos in under thirty seconds. Every answer cites the cue that forced comunicarse con or blocked se me cayó la señal.", es: "Parejas hacen llamadas donde se pierde una instrucción. Nombran contacto, reportan my signal dropped y retoman con let's continue en treinta segundos. Cada respuesta cita la pista que exige \"get in touch with\" o bloquea \"my signal dropped\"." },
      production: { en: "Stage a trip-planning call among the guide and two relatives. The guide refuses to repeat the whole plan unless the caller repairs the signal problem efficiently. The final decision must include comunicarse con and survive one objection.", es: "Haga llamada de viaje entre guía y familiares. La guía no repite todo si quien llama no repara my signal dropped con eficiencia. La decisión final debe incluir \"get in touch with\" y resistir una objeción." },
      exitTicket: { en: "The call log closes with \"comunico con Marcela\" repaired to \"me comunico con Marcela\"; students add a restart line using continuemos.", es: "La bitácora cierra corrigiendo \"my signal fell\" a \"my signal dropped\"; añaden una frase para retomar con let's continue." },
      homework: { en: "Write the follow-up message after the failed call: whom you contacted, what the signal did, and which agenda item should continue tomorrow. Students underline the Spanish form comunicarse con where it carries the decision.", es: "Escriben en inglés el seguimiento: a quién contactaron, qué pasó con signal, y qué punto should continue mañana. Subrayan la forma inglesa \"get in touch with\" donde sostiene la decisión." },
      support: { en: "Students lose the reflexive shape in me comunico con. Give a contact log with my name already printed so they only choose the person after con.", es: "Pierden la estructura de get in touch with porque piensan en llamar directo. Dé bitácora con subject y person ya separados." },
      stretch: { en: "Add a second failure while directions are being given. Early finishers summarize the missing step and keep the call cooperative rather than blaming the speaker. The added challenge must still keep comunicarse con accurate in context.", es: "Agregue otra caída mientras dan indicaciones. Quienes avanzan resumen el paso perdido y sostienen cooperación sin culpar. El reto añadido conserva \"get in touch with\" correcto dentro del contexto." },
      errors: [
        { en: "Signal recovery: they write \"comunico con Marcela\" because transfer overpowers the Signal recovery scene. Put \"me comunico con Marcela\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Signal recovery: dicen \"my signal fell\" por transferencia del español en contacto. Corrija a \"my signal dropped\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"comunicarse con\" where this step needs \"se me cayó la señal\". Name the contacto speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"get in touch with\" cuando la escena necesita \"my signal dropped\". Nombre al hablante de contacto, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "60-extending-cause-and-halt": {
    mission: { en: "Write or say a usable incident report that separates stopping, causing damage, and producing a result.", es: "Escribir o decir un reporte de incidente útil que separe detenerse, causar daño y producir un resultado." },
    canDo: [
      { en: "Ask a taxi to stop at the corner with ¿me para? rather than a literal stop order", es: "Pedirle a un taxi que pare en la esquina con ¿me para? y no con una orden literal" },
      { en: "State what causó el daño in a bakery or street problem", es: "Decir qué causó el daño en un problema de panadería o calle" },
      { en: "Name what produjo inundaciones or another result after the cause is clear", es: "Nombrar qué produjo inundaciones u otro resultado después de aclarar la causa" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Put a taxi corner map beside photos of a bakery machine and storm drains. Students decide what should stop, what caused damage, and what resulted. Spanish checkpoint: ¿me para? becomes useful before causó el daño; students say why.", es: "Ponga mapa de taxi junto a máquina de panadería y desagües. En inglés distinguen halt, cause y result antes de ver verbos. Punto de control: \"pull over\" sirve antes de \"caused the damage\"; explican por qué." },
      presentation: { en: "Use ¿me para? only in the taxi-corner request. Move to causó el daño with the bakery machine, then produjo inundaciones with the blocked drains. The board ends with ¿me para?, causó el daño, and one reason produjo inundaciones belongs later.", es: "Use pull over solo en la esquina de taxi. Pase a caused the damage con la máquina y a produced floods con desagües tapados. El tablero termina con \"pull over\", \"caused the damage\" y una razón para aplazar \"produced floods\"." },
      practice: { en: "Incident cards force three choices: request a halt, assign a cause, or name a result. The mud card checks that produjo is not replaced by a regularized form. Every answer cites the cue that forced ¿me para? or blocked causó el daño.", es: "Tarjetas de incidente obligan a escoger halt, cause o result. La tarjeta de barro revisa produced sin confundirlo con caused. Cada respuesta cita la pista que exige \"pull over\" o bloquea \"caused the damage\"." },
      production: { en: "Hold a neighborhood complaint meeting. The taxi driver, baker, and resident all defend themselves; the chair must produce one actionable cause report. The final decision must include ¿me para? and survive one objection.", es: "Haga reunión barrial. Taxista, panadera y residente se defienden; presidencia formula un reporte accionable con caused the damage. La decisión final debe incluir \"pull over\" y resistir una objeción." },
      exitTicket: { en: "The incident slip asks students to fix \"produció barro\" as \"produjo barro\" and add one taxi-corner request with ¿me para?.", es: "La ficha de incidente corrige \"stop me in the corner\" a \"pull over at the corner\" y añade una causa con caused the damage o produced floods." },
      homework: { en: "Write a municipal note with three bullets: where the taxi should pull over, probable cause of damage, and documented flooding result. Students underline the Spanish form ¿me para? where it carries the decision.", es: "Redactan en inglés una nota municipal: where to pull over, probable cause y resultado de flooding documentado. Subrayan la forma inglesa \"pull over\" donde sostiene la decisión." },
      support: { en: "Cause and result collapse for many students. Use arrow cards: one stops movement for ¿me para?, one points back to causó, and one points forward to produjo.", es: "Cause y result se mezclan. Use flechas: una detiene movimiento, otra apunta atrás a caused, otra adelante a produced floods." },
      stretch: { en: "Introduce a witness who disputes the timeline. Strong groups concede uncertainty but still choose the most likely cause and one immediate halt. The added challenge must still keep ¿me para? accurate in context.", es: "Incluya testigo que contradice el horario. Grupos fuertes conceden duda y eligen causa probable más una acción inmediata. El reto añadido conserva \"pull over\" correcto dentro del contexto." },
      errors: [
        { en: "Cause report: they write \"produció barro\" because transfer overpowers the Cause report scene. Put \"produjo barro\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Cause report: dicen \"stop me in the corner\" por transferencia del español en causas. Corrija a \"pull over at the corner\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"¿me para?\" where this step needs \"causó el daño\". Name the causas speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"pull over\" cuando la escena necesita \"caused the damage\". Nombre al hablante de causas, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "61-extending-getting-it-done": {
    mission: { en: "Report practical progress honestly by saying what you managed to get, what signatures remain, and what the task is about.", es: "Reportar avances prácticos con honestidad diciendo qué lograste conseguir, qué firmas faltan y de qué se trata la gestión." },
    canDo: [
      { en: "Say logré conseguir cita when effort produced a real appointment", es: "Decir logré conseguir cita cuando el esfuerzo produjo una cita real" },
      { en: "Explain which firmas still need reunir before the file moves", es: "Explicar qué firmas falta reunir antes de que avance el expediente" },
      { en: "Ask what the workshop or office task is about before joining it", es: "Preguntar de qué se trata un taller o trámite antes de entrar" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Show an appointment slip locked inside a folder of missing signatures. Students divide the task into achieved progress, remaining collection, and unclear purpose. Spanish checkpoint: logré conseguir cita becomes useful before reunir firmas; students say why.", es: "Muestre una cita dentro de una carpeta sin firmas. En inglés separan progress achieved, signatures missing y purpose unclear. Punto de control: \"managed to get\" sirve antes de \"gather signatures\"; explican por qué." },
      presentation: { en: "Teach logré conseguir cita as progress after effort, not simple possession. Reunir firmas belongs to the folder; ¿de qué se trata? belongs at the workshop door. The board ends with logré conseguir cita, reunir firmas, and one reason ¿de qué se trata? belongs later.", es: "Enseñe managed to get como avance con esfuerzo, no posesión. Gather signatures vive en la carpeta y What is it about? en la puerta. El tablero termina con \"managed to get\", \"gather signatures\" y una razón para aplazar \"What is it about?\"." },
      practice: { en: "Project-board cards move between done, blocked, and question columns. Students may write logré only when a card shows effort plus result. Every answer cites the cue that forced logré conseguir cita or blocked reunir firmas.", es: "Tarjetas de tablero pasan por done, blocked y question. Solo usan managed to get cuando aparece esfuerzo más resultado. Cada respuesta cita la pista que exige \"managed to get\" o bloquea \"gather signatures\"." },
      production: { en: "Run a community-office check-in. The coordinator demands proof, not optimism, so each team shows the appointment and negotiates a realistic signature plan. The final decision must include logré conseguir cita and survive one objection.", es: "Haga control en oficina comunitaria. Coordinación exige pruebas, no optimismo; cada equipo muestra cita y negocia plan real para signatures. La decisión final debe incluir \"managed to get\" y resistir una objeción." },
      exitTicket: { en: "Students update the project board by changing \"logré una cita\" to \"logré conseguir cita\" and adding a next step for reunir firmas.", es: "Actualizan el tablero corrigiendo \"I achieved an appointment\" a \"I managed to get an appointment\" y agregan un paso con gather signatures." },
      homework: { en: "Write a progress email to a supervisor. Include logré conseguir cita, explain the signature gap, and ask one honest question about what the workshop covers. Students underline the Spanish form logré conseguir cita where it carries the decision.", es: "Escriben en inglés correo de avance: managed to get an appointment, brecha de firmas y una pregunta honesta sobre scope. Subrayan la forma inglesa \"managed to get\" donde sostiene la decisión." },
      support: { en: "Students translate logro as achievement and overstate the result. Give a proof strip: effort, result, still missing; they fill all three before using logré.", es: "Traducen managed como logro total y exageran. Dé tira effort, result, still missing; la llenan antes de decir managed to get." },
      stretch: { en: "Add a supervisor who says the appointment is not enough. Fast groups defend the progress while naming the next measurable step. The added challenge must still keep logré conseguir cita accurate in context.", es: "Agregue supervisora que dice que la cita no basta. Grupos rápidos defienden avance y nombran el próximo paso medible. El reto añadido conserva \"managed to get\" correcto dentro del contexto." },
      errors: [
        { en: "Practical progress: they write \"logré una cita\" because transfer overpowers the Practical progress scene. Put \"logré conseguir cita\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Practical progress: dicen \"I achieved an appointment\" por transferencia del español en gestiones. Corrija a \"I managed to get an appointment\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"logré conseguir cita\" where this step needs \"reunir firmas\". Name the gestiones speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"managed to get\" cuando la escena necesita \"gather signatures\". Nombre al hablante de gestiones, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "62-extending-habits-and-worth": {
    mission: { en: "Choose a trip plan by weighing current habits, physical fit, and whether the safer or slower option is worth it.", es: "Elegir un plan de viaje sopesando hábitos actuales, espacio físico y si la opción más segura o lenta vale la pena." },
    canDo: [
      { en: "Use suelo for a current dawn routine rather than an old habit", es: "Usar suelo para una rutina actual de madrugada y no para un hábito viejo" },
      { en: "Say no quepo when a person or backpack truly does not fit", es: "Decir no quepo cuando una persona o morral de verdad no cabe" },
      { en: "Decide whether a boat ride vale la pena because of cost, safety, or time", es: "Decidir si un paseo en lancha vale la pena por costo, seguridad o tiempo" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Mark a dawn walk, a tiny car, backpacks, and a boat option on a plan. Students separate current habit, physical fit, and value judgment. Spanish checkpoint: suelo becomes useful before no quepo; students say why.", es: "Marque caminata temprana, carro pequeño, morrales y lancha. En inglés separan current habit, fit físico y value judgment. Punto de control: \"usually\" sirve antes de \"doesn't fit\"; explican por qué." },
      presentation: { en: "Use suelo for what happens nowadays, not old routine. Test no quepo with the backpacks, then ask whether the boat ride vale la pena. The board ends with suelo, no quepo, and one reason vale la pena belongs later.", es: "Use usually para hábito actual, no pasado. Pruebe doesn't fit con morrales y pregunte si la lancha is worth it. El tablero termina con \"usually\", \"doesn't fit\" y una razón para aplazar \"worth it\"." },
      practice: { en: "Groups sort travel statements by clock, space, and value. The old-habit card forces a repair from ahora solía salir to ahora suelo salir. Every answer cites the cue that forced suelo or blocked no quepo.", es: "Clasifican frases de viaje por clock, space y value. La tarjeta de hábito pasado obliga a separar usually de used to. Cada respuesta cita la pista que exige \"usually\" o bloquea \"doesn't fit\"." },
      production: { en: "Plan the visitor's trip. The driver says the bags will not fit, the walker defends dawn, and the group decides whether the boat is worth it. The final decision must include suelo and survive one objection.", es: "Planean el viaje de una visita. Conductor usa 'doesn't fit', caminante defiende la rutina de madrugada y el grupo decide si 'worth it' aplica. La decisión final debe incluir \"usually\" y resistir una objeción." },
      exitTicket: { en: "On the travel plan, students replace \"ahora solía salir\" with \"ahora suelo salir\" and add one choice where vale la pena depends on cost.", es: "En el plan de viaje cambian \"I use to get up early\" por \"I used to get up early\" y añaden una línea con usually o worth it." },
      homework: { en: "Write a recommendation for the visitor with one normal habit, one space limit, and one final worth-it judgment tied to cost or safety. Students underline the Spanish form suelo where it carries the decision.", es: "Escriben en inglés una recomendación: normal habit, space limit y juicio worth it ligado a costo o seguridad. Subrayan la forma inglesa \"usually\" donde sostiene la decisión." },
      support: { en: "The trap is time, not vocabulary. Give a two-line timeline for old and current habit; students place the event before choosing suelo or solía.", es: "La trampa es temporal, no léxica. Dé línea used to / usually; colocan el hábito antes de escoger la forma inglesa." },
      stretch: { en: "Add a cheaper but less safe transport option. Early finishers concede the cost advantage and defend whether the safer choice is worth it. The added challenge must still keep suelo accurate in context.", es: "Agregue transporte más barato pero inseguro. Quienes avanzan conceden el costo y defienden si la opción segura vale la pena. El reto añadido conserva \"usually\" correcto dentro del contexto." },
      errors: [
        { en: "Worth deciding: they write \"ahora solía salir\" because transfer overpowers the Worth deciding scene. Put \"ahora suelo salir\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Worth deciding: dicen \"I use to get up early\" por transferencia del español en valor. Corrija a \"I used to get up early\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"suelo\" where this step needs \"no quepo\". Name the valor speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"usually\" cuando la escena necesita \"doesn't fit\". Nombre al hablante de valor, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "63-extending-falling-and-getting-on": {
    mission: { en: "Describe social chemistry without confusing first impressions, attraction, ongoing relationships, and who receives the news.", es: "Describir química social sin confundir primeras impresiones, atracción, relaciones continuas y quién recibe la noticia." },
    canDo: [
      { en: "Use me cae bien for a first impression of a friend's brother", es: "Usar me cae bien para una primera impresión del hermano de un amigo" },
      { en: "Use me llevo bien for repeated contact with in-laws or family", es: "Usar me llevo bien para trato repetido con suegros o familia" },
      { en: "Choose le cuento to decide who should hear the update", es: "Escoger le cuento para decidir quién debe recibir la noticia" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Show the friend's brother arriving at the river with in-laws nearby. Students decide whether the sentence describes attraction, first impression, relationship history, or telling news. Spanish checkpoint: me cae bien becomes useful before me llevo bien; students say why.", es: "Muestre al hermano del amigo llegando al río con suegros cerca. En inglés distinguen attraction, first impression, relationship history y telling news. Punto de control: \"I like him\" sirve antes de \"get along with\"; explican por qué." },
      presentation: { en: "Use me cae bien for a first social impression. Move to me llevo bien only after repeated contact with in-laws, and use le cuento for choosing the news recipient. The board ends with me cae bien, me llevo bien, and one reason le cuento belongs later.", es: "Use I like him como impresión social. Pase a get along with tras trato repetido con suegros y a I'll tell you al escoger destinatario. El tablero termina con \"I like him\", \"get along with\" y una razón para aplazar \"I'll tell you\"." },
      practice: { en: "Learners mark relationship cards as impression, history, or message. Any gustar line must be tested for romance before it can replace me cae bien. Every answer cites the cue that forced me cae bien or blocked me llevo bien.", es: "Marcan tarjetas como impression, history o message. Cualquier I like him se revisa: ¿impresión social o atracción? Cada respuesta cita la pista que exige \"I like him\" o bloquea \"get along with\"." },
      production: { en: "Stage a family lunch after the river catch-up. One person wants to invite the brother, another worries about the in-laws, and the host decides whom to tell. The final decision must include me cae bien and survive one objection.", es: "Haga almuerzo familiar tras el reencuentro. Alguien quiere invitar al hermano, otra persona duda por suegros y anfitrión decide whom to tell. La decisión final debe incluir \"I like him\" y resistir una objeción." },
      exitTicket: { en: "The family note changes \"me gusta él\" to \"me cae bien\"; a second line must prove whether me llevo bien or le cuento is the next move.", es: "La nota familiar repara \"he falls me well\" como \"he seems nice\"; otra frase decide entre get along with e I'll tell you." },
      homework: { en: "Write a voice-note script advising whether to invite him. It must include me cae bien and one line about getting along over time. Students underline the Spanish form me cae bien where it carries the decision.", es: "Escriben en inglés guion de nota de voz sobre invitarlo. Debe incluir I like him y una frase sobre get along with. Subrayan la forma inglesa \"I like him\" donde sostiene la decisión." },
      support: { en: "Caer bien feels backward and can sound romantic if students choose gustar. Use two portraits: spark and easy company; they point before speaking.", es: "Caer bien en inglés no debe sonar como romance obligatorio. Use dos retratos, attraction y easy company; señalan antes de decir 'I like him'." },
      stretch: { en: "Add a rumor that changes the first impression. Strong groups revise their judgment without pretending they know the person well. The added challenge must still keep me cae bien accurate in context.", es: "Agregue un rumor que cambia la impresión. Grupos fuertes revisan el juicio sin fingir una relación profunda. El reto añadido conserva \"I like him\" correcto dentro del contexto." },
      errors: [
        { en: "Relationship reading: they write \"me gusta él\" because transfer overpowers the Relationship reading scene. Put \"me cae bien\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Relationship reading: dicen \"he falls me well\" por transferencia del español en relaciones. Corrija a \"he seems nice\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"me cae bien\" where this step needs \"me llevo bien\". Name the relaciones speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"I like him\" cuando la escena necesita \"get along with\". Nombre al hablante de relaciones, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "64-extending-forms-and-favors": {
    mission: { en: "Ask for paperwork help, a saved seat, or a borrowed object without making the favor sound like an order.", es: "Pedir ayuda con un formulario, un puesto guardado o un objeto prestado sin hacer que el favor suene a orden." },
    canDo: [
      { en: "Ask someone to llene el formulario at the registration desk", es: "Pedirle a alguien que llene el formulario en la mesa de inscripción" },
      { en: "Say guárdame el puesto when the cafe is crowded and the relationship allows it", es: "Decir guárdame el puesto cuando el café está lleno y la relación lo permite" },
      { en: "Use ¿me prestas? for a charger or backpack item while keeping the request balanced", es: "Usar ¿me prestas? para un cargador u objeto de mochila manteniendo equilibrada la petición" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Set a registration desk near a crowded cafe table. Students decide which request is official paperwork, which is social seat-saving, and which asks for an object. Spanish checkpoint: llene el formulario becomes useful before guárdame el puesto; students say why.", es: "Arme inscripción junto a mesa de café llena. En inglés separan official paperwork, seat-saving social y borrowed object. Punto de control: \"fill out\" sirve antes de \"save a seat\"; explican por qué." },
      presentation: { en: "Model llene el formulario with a pen at the desk. Walk to the cafe for guárdame el puesto, then use the charger for ¿me prestas? The board ends with llene el formulario, guárdame el puesto, and one reason ¿me prestas? belongs later.", es: "Modele fill out con lapicero en formulario. Pase al café para save a seat y use el cargador para Can I borrow? El tablero termina con \"fill out\", \"save a seat\" y una razón para aplazar \"Can I borrow?\"." },
      practice: { en: "Request cards send students to desk, table, or backpack. The form card rejects rellenar unless something literally became empty and needs refilling. Every answer cites the cue that forced llene el formulario or blocked guárdame el puesto.", es: "Tarjetas de petición envían a desk, table o backpack. Refill se rechaza en formulario porque no es recipiente vacío. Cada respuesta cita la pista que exige \"fill out\" o bloquea \"save a seat\"." },
      production: { en: "Run a registration line during a crowded break. One student needs the form completed, a seat saved, and a charger, but cannot burden the same friend with everything. The final decision must include llene el formulario and survive one objection.", es: "Haga fila de inscripción durante descanso lleno. Una persona necesita fill out, save a seat y borrow charger sin cargarle todo a la misma amiga. La decisión final debe incluir \"fill out\" y resistir una objeción." },
      exitTicket: { en: "At the registration table, students correct \"rellenar el formulario\" to \"llenar el formulario\" and add one polite favor using guárdame el puesto.", es: "En inscripción cambian \"refill the form\" por \"fill out the form\" y añaden una petición cortés con save a seat o Can I borrow?." },
      homework: { en: "Write two polite messages: one to staff about the form and one to a classmate about the seat. Add only one borrowed-object request. Students underline the Spanish form llene el formulario where it carries the decision.", es: "Escriben en inglés dos mensajes corteses: al personal sobre form y a compañera sobre seat. Añaden solo una petición de borrow. Subrayan la forma inglesa \"fill out\" donde sostiene la decisión." },
      support: { en: "Fill out is idiom, while save a seat is social balance. Give two mini-scenes, office and cafe; students choose the room before llene or guárdame appears.", es: "Fill out es idiom; save a seat depende de relación social. Dé dos escenas, office y cafe, y eligen sala antes de hablar." },
      stretch: { en: "Add a friend who refuses because the favors are uneven. Fast pairs reduce the request and offer a return favor without losing politeness. The added challenge must still keep llene el formulario accurate in context.", es: "Agregue amiga que dice no por carga desigual. Parejas rápidas reducen petición y ofrecen devolver ayuda manteniendo cortesía. El reto añadido conserva \"fill out\" correcto dentro del contexto." },
      errors: [
        { en: "Favor exchange: they write \"rellenar el formulario\" because transfer overpowers the Favor exchange scene. Put \"llenar el formulario\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Favor exchange: dicen \"refill the form\" por transferencia del español en favores. Corrija a \"fill out the form\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"llene el formulario\" where this step needs \"guárdame el puesto\". Name the favores speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"fill out\" cuando la escena necesita \"save a seat\". Nombre al hablante de favores, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "65-extending-being-seen-to": {
    mission: { en: "Update a clinic visit by asking whether the patient has been seen, reporting surgery, and giving a body measurement clearly.", es: "Actualizar una visita clínica preguntando si ya atendieron al paciente, reportando cirugía y dando una medida corporal con claridad." },
    canDo: [
      { en: "Ask ¿ya lo atendieron? after a long wait at reception", es: "Preguntar ¿ya lo atendieron? después de una larga espera en recepción" },
      { en: "Report lo operaron without confusing surgery with general care", es: "Informar lo operaron sin confundir cirugía con atención general" },
      { en: "Give or ask for mide un metro in a chart or measurement conversation", es: "Dar o pedir mide un metro en una ficha o conversación de medidas" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Arrange a clinic waiting room with a surgery bracelet and a height mark. Students decide who is waiting, who has been treated, and what measurement matters. Spanish checkpoint: ¿ya lo atendieron? becomes useful before lo operaron; students say why.", es: "Organice sala de espera con pulsera quirúrgica y marca de estatura. En inglés separan waiting, seen by staff y body measurement. Punto de control: \"be seen\" sirve antes de \"had surgery\"; explican por qué." },
      presentation: { en: "Model ¿ya lo atendieron? at reception. Use lo operaron with the bracelet and mide un metro only when the chart needs a number. The board ends with ¿ya lo atendieron?, lo operaron, and one reason mide un metro belongs later.", es: "Modele be seen en recepción. Use had surgery con la pulsera y How tall are you? cuando la ficha necesita número. El tablero termina con \"be seen\", \"had surgery\" y una razón para aplazar \"How tall are you?\"." },
      practice: { en: "Clinic charts rotate among reception, surgery, and measurement. Students cross out asistir for care status and choose atendieron only when staff actually saw the patient. Every answer cites the cue that forced ¿ya lo atendieron? or blocked lo operaron.", es: "Fichas clínicas rotan por recepción, cirugía y medida. Tachan attended me y escogen be seen solo cuando personal atendió al paciente. Cada respuesta cita la pista que exige \"be seen\" o bloquea \"had surgery\"." },
      production: { en: "Stage a complaint after a long clinic wait. The family member asks about care status, reports surgery accurately, and avoids accusing staff without evidence. The final decision must include ¿ya lo atendieron? and survive one objection.", es: "Represente queja tras larga espera. Familiar pregunta si patient has been seen, actualiza surgery y evita acusar sin evidencia. La decisión final debe incluir \"be seen\" y resistir una objeción." },
      exitTicket: { en: "The clinic exit slip changes \"nadie me asistió\" to \"nadie me ha atendido\" and adds one status line about lo operaron.", es: "La ficha clínica corrige \"nobody attended me\" a \"nobody has seen me\" y añade una actualización con had surgery o How tall are you?." },
      homework: { en: "Write the text sent to a relative from the clinic: whether anyone has seen the patient, what surgery happened, and one measurement question. Students underline the Spanish form ¿ya lo atendieron? where it carries the decision.", es: "Escriben en inglés mensaje desde clínica: whether seen, what surgery happened y una pregunta de height o measurement. Subrayan la forma inglesa \"be seen\" donde sostiene la decisión." },
      support: { en: "The hard part is English medical phrasing, but the Spanish lesson still centers atendieron. Use a clinic timeline with waiting and seen as separate boxes.", es: "La dificultad es frase médica inglesa: attended me no sirve para atención recibida. Use línea waiting / seen con cajas separadas." },
      stretch: { en: "Add a nurse who gives incomplete information. Early finishers ask a follow-up politely and summarize what remains unknown. The added challenge must still keep ¿ya lo atendieron? accurate in context.", es: "Agregue enfermera con información incompleta. Quienes avanzan preguntan con cortesía y resumen lo que aún no saben. El reto añadido conserva \"be seen\" correcto dentro del contexto." },
      errors: [
        { en: "Care update: they write \"nadie me asistió\" because transfer overpowers the Care update scene. Put \"nadie me ha atendido\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Care update: dicen \"nobody attended me\" por transferencia del español en atención médica. Corrija a \"nobody has seen me\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"¿ya lo atendieron?\" where this step needs \"lo operaron\". Name the atención médica speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"be seen\" cuando la escena necesita \"had surgery\". Nombre al hablante de atención médica, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "66-extending-joining-and-parting": {
    mission: { en: "Manage a market and cleanup signup by weighing fish, joining a group, and arranging seats or separation fairly.", es: "Manejar un puesto de mercado y una inscripción de limpieza pesando pescado, uniéndose a un grupo y organizando puestos o separación con justicia." },
    canDo: [
      { en: "Ask ¿cuánto pesa? at the fish scale and understand the answer", es: "Preguntar ¿cuánto pesa? en la balanza de pescado y entender la respuesta" },
      { en: "Say me uno a when joining the cleanup rather than dropping the preposition", es: "Decir me uno a al unirse a la limpieza sin omitir la preposición" },
      { en: "Use separar puestos to keep seating workable for a separated couple or group", es: "Usar separar puestos para que los asientos funcionen para una pareja separada o grupo" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Put a fish scale beside cleanup sign-up sheets and two separated chairs. Students identify measuring, joining, saving seats, and separating people. Spanish checkpoint: ¿cuánto pesa? becomes useful before me uno a; students say why.", es: "Ponga balanza junto a inscripción de limpieza y sillas separadas. En inglés distinguen weighing, joining, saving seats y separating people. Punto de control: \"How much does it weigh?\" sirve antes de \"join\"; explican por qué." },
      presentation: { en: "Ask ¿cuánto pesa? with the fish first. Step onto the cleanup list for me uno a, then move chairs to show separar puestos. The board ends with ¿cuánto pesa?, me uno a, and one reason separar puestos belongs later.", es: "Pregunte How much does it weigh? con el pescado. Entre a la lista con join y mueva sillas para save seats o separate. El tablero termina con \"How much does it weigh?\", \"join\" y una razón para aplazar \"save seats\"." },
      practice: { en: "Event cards mix market purchase, cleanup crew, bus seats, and couple status. The join card is not accepted unless me uno keeps its a. Every answer cites the cue that forced ¿cuánto pesa? or blocked me uno a.", es: "Tarjetas mezclan mercado, limpieza, bus y pareja. Join se revisa por preposición y weigh por no convertirlo en weight. Cada respuesta cita la pista que exige \"How much does it weigh?\" o bloquea \"join\"." },
      production: { en: "Run a river-cleanup sign-up next to the fish stall. A volunteer joins late, two seats must be saved, and the seller interrupts with weight questions. The final decision must include ¿cuánto pesa? and survive one objection.", es: "Monte inscripción de limpieza junto al pescado. Voluntario joins late, se guardan seats y vendedor interrumpe con pregunta de weigh. La decisión final debe incluir \"How much does it weigh?\" y resistir una objeción." },
      exitTicket: { en: "Beside the scale, students repair \"me uno la jornada\" to \"me uno a la jornada\" and add one seating line with separar puestos.", es: "Junto a la balanza corrigen \"How much does it weight?\" a \"How much does it weigh?\" y añaden una línea con join o save seats." },
      homework: { en: "Write the organizer's final note: one weighing question, one late volunteer joining, and one seating arrangement that prevents conflict. Students underline the Spanish form ¿cuánto pesa? where it carries the decision.", es: "Escriben en inglés nota final: pregunta de weigh, voluntario que joins late y arreglo de seats que evita conflicto. Subrayan la forma inglesa \"How much does it weigh?\" donde sostiene la decisión." },
      support: { en: "Students confuse noun and verb in weigh/weight, and they drop the preposition after join. Put scale and group icons beside ¿cuánto pesa? and me uno a.", es: "Confunden weigh con weight y a veces omiten preposición después de join. Dé tarjeta con scale a un lado y group al otro." },
      stretch: { en: "Add a separated couple who both want to join the cleanup. Strong groups design fair seating and explain it without gossip. The added challenge must still keep ¿cuánto pesa? accurate in context.", es: "Agregue pareja separada que quiere unirse a limpieza. Grupos fuertes diseñan puestos justos y explican sin chisme. El reto añadido conserva \"How much does it weigh?\" correcto dentro del contexto." },
      errors: [
        { en: "Joined plans: they write \"me uno la jornada\" because transfer overpowers the Joined plans scene. Put \"me uno a la jornada\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Joined plans: dicen \"How much does it weight?\" por transferencia del español en uniones. Corrija a \"How much does it weigh?\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"¿cuánto pesa?\" where this step needs \"me uno a\". Name the uniones speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"How much does it weigh?\" cuando la escena necesita \"join\". Nombre al hablante de uniones, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "67-extending-out-and-across": {
    mission: { en: "Complete a timed errand route by getting cash, making copies, respecting or challenging a line, and crossing safely.", es: "Completar una ruta de diligencias contra reloj sacando plata, sacando copias, respetando o cuestionando la fila y cruzando con cuidado." },
    canDo: [
      { en: "Use sacar plata at the ATM and sacar copias at the copy shop", es: "Usar sacar plata en el cajero y sacar copias en la fotocopiadora" },
      { en: "Call out saltarse la fila when the boat line creates pressure", es: "Señalar saltarse la fila cuando la fila de lancha crea presión" },
      { en: "Give cruce con cuidado as a safety instruction at the avenue", es: "Dar cruce con cuidado como instrucción de seguridad en la avenida" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Draw the route from ATM to copy shop, boat line, and avenue crossing. Students decide where money, copies, queue behavior, and safety advice belong. Spanish checkpoint: sacar plata becomes useful before saltarse la fila; students say why.", es: "Dibuje ruta: cajero, copias, fila de lancha y avenida. En inglés ubican cash, copies, line behavior y crossing safety. Punto de control: \"withdraw cash\" sirve antes de \"cut in line\"; explican por qué." },
      presentation: { en: "Teach sacar plata at the ATM and sacar copias at the shop as two local uses of sacar. Use saltarse la fila only when the boat line appears. The board ends with sacar plata, saltarse la fila, and one reason cruce con cuidado belongs later.", es: "Enseñe withdraw cash en cajero y make copies en fotocopiadora como acciones distintas. Use cut in line solo ante fila de lancha. El tablero termina con \"withdraw cash\", \"cut in line\" y una razón para aplazar \"cross carefully\"." },
      practice: { en: "Students sequence errand cards under a boat deadline. The copy-shop card rejects tomar copias, while the crossing card forces cruce con cuidado. Every answer cites the cue that forced sacar plata or blocked saltarse la fila.", es: "Ordenan diligencias contra salida de lancha. Make copies bloquea take copies; cross carefully aparece solo en la avenida. Cada respuesta cita la pista que exige \"withdraw cash\" o bloquea \"cut in line\"." },
      production: { en: "Stage a rushed errand before the boat leaves. One person wants to cut the line, another insists on crossing safely, and the group chooses a route. The final decision must include sacar plata and survive one objection.", es: "Represente diligencia contra reloj. Alguien propone 'cut in line', otra persona exige 'cross carefully' y el grupo decide ruta. La decisión final debe incluir \"withdraw cash\" y resistir una objeción." },
      exitTicket: { en: "The route ticket changes \"tomar copias\" to \"sacar copias\" and adds one safety instruction with cruce con cuidado before the boat leaves.", es: "El tiquete de ruta repara \"take copies\" como \"make copies\" y añade una indicación con withdraw cash o cross carefully." },
      homework: { en: "Write directions for a cousin doing the route tomorrow. Include cash, copies, and one avenue warning that would actually prevent an accident. Students underline the Spanish form sacar plata where it carries the decision.", es: "Escriben en inglés instrucciones para una prima: cash, copies y advertencia de crossing que prevenga un accidente real. Subrayan la forma inglesa \"withdraw cash\" donde sostiene la decisión." },
      support: { en: "Sacar changes by location. Give students a small map: at the ATM it means withdraw; at the copy shop it means make, not take.", es: "La dificultad es que el verbo cambia por lugar. Dé mapa: ATM equals withdraw; copy shop equals make, no take." },
      stretch: { en: "Add an accessibility problem at the crossing. Fast groups redesign the route and defend the slower choice against the boat deadline. The added challenge must still keep sacar plata accurate in context.", es: "Agregue dificultad de acceso en la avenida. Grupos rápidos rediseñan ruta y defienden opción lenta pese a la lancha. El reto añadido conserva \"withdraw cash\" correcto dentro del contexto." },
      errors: [
        { en: "Errand route: they write \"tomar copias\" because transfer overpowers the Errand route scene. Put \"sacar copias\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Errand route: dicen \"take copies\" por transferencia del español en diligencias. Corrija a \"make copies\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"sacar plata\" where this step needs \"saltarse la fila\". Name the diligencias speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"withdraw cash\" cuando la escena necesita \"cut in line\". Nombre al hablante de diligencias, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "68-extending-turn-and-push": {
    mission: { en: "Read road, door, and crowd signs well enough to delay a turn, push a door, or stop rude shoving.", es: "Leer señales de carretera, puerta y multitud lo bastante bien para aplazar un giro, empujar una puerta o frenar empujones bruscos." },
    canDo: [
      { en: "Tell a driver no gire todavía before the river-road turn", es: "Decirle a un conductor no gire todavía antes del giro hacia el río" },
      { en: "Use empuje for a door sign and not for pushing people", es: "Usar empuje para una puerta y no para empujar personas" },
      { en: "Warn no empuje when a crowded entrance becomes unsafe", es: "Advertir no empuje cuando una entrada llena se vuelve insegura" }
    ],
    teaching: {
      minutes: 55,
      warmUp: { en: "Place a river-road arrow, a stuck paper door, and a crowded entrance sign around the room. Students act before speaking: turn, push, pull, or shove. Spanish checkpoint: no gire todavía becomes useful before empuje; students say why.", es: "Ponga flecha de carretera, puerta de papel trabada y letrero de entrada llena. En inglés actúan turn, push, pull o shove antes de hablar. Punto de control: \"don't turn yet\" sirve antes de \"push\"; explican por qué." },
      presentation: { en: "Use no gire todavía with the road map. Demonstrate empuje on the paper door, then contrast no empuje when bodies, not doors, are involved. The board ends with no gire todavía, empuje, and one reason no empuje belongs later.", es: "Use don't turn yet con el mapa. Demuestre push con puerta de papel y contraste don't shove cuando hay personas. El tablero termina con \"don't turn yet\", \"push\" y una razón para aplazar \"don't shove\"." },
      practice: { en: "Sign cards are corrected silently first. The wrong-driveway card delays turning; the door card separates pull from throw; the crowd card blocks rude pushing. Every answer cites the cue that forced no gire todavía or blocked empuje.", es: "Corrigen letreros primero en silencio. Wrong driveway retrasa turn; door separa pull de throw; crowd bloquea shove. Cada respuesta cita la pista que exige \"don't turn yet\" o bloquea \"push\"." },
      production: { en: "Run a festival entrance problem. A driver is about to turn early, a door sticks, and the crowd surges; the safety lead gives exact short commands. The final decision must include no gire todavía and survive one objection.", es: "Haga problema de entrada a festival. Carro va a girar temprano, puerta se traba y multitud empuja; seguridad da comandos breves. La decisión final debe incluir \"don't turn yet\" y resistir una objeción." },
      exitTicket: { en: "At the paper door, students replace \"tirar la puerta\" with \"jalar la puerta\" and write a separate crowd warning with no empuje.", es: "En la puerta de papel corrigen \"throw the door\" a \"pull the door\" y escriben advertencia aparte con don't shove." },
      homework: { en: "Design three signs for the route: delayed turn, door instruction, and crowd warning. Each sign must include a one-line reason. Students underline the Spanish form no gire todavía where it carries the decision.", es: "Diseñan en inglés tres letreros: delayed turn, door instruction y crowd warning. Cada uno trae razón breve. Subrayan la forma inglesa \"don't turn yet\" donde sostiene la decisión." },
      support: { en: "This module is physical; abstract explanations fail. Hand students gesture cards and make them perform the motion before selecting no gire or empuje.", es: "Este módulo es físico; explicar en abstracto falla. Dé tarjetas de gesto y actúan antes de escoger don't turn o push." },
      stretch: { en: "Add a visitor who ignores the sign and almost causes an accident. Advanced pairs rewrite the security announcement with less ambiguity. The added challenge must still keep no gire todavía accurate in context.", es: "Agregue visitante que ignora letrero y casi causa accidente. Parejas avanzadas reescriben anuncio de seguridad con menos ambigüedad. El reto añadido conserva \"don't turn yet\" correcto dentro del contexto." },
      errors: [
        { en: "Sign reading: they write \"tirar la puerta\" because transfer overpowers the Sign reading scene. Put \"jalar la puerta\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Sign reading: dicen \"throw the door\" por transferencia del español en señales. Corrija a \"pull the door\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"no gire todavía\" where this step needs \"empuje\". Name the señales speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"don't turn yet\" cuando la escena necesita \"push\". Nombre al hablante de señales, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "69-comparing-and-degree": {
    mission: { en: "Compare prices, quality and hunger with enough precision to choose without sounding dramatic or vague.", es: "Comparar precios, calidad y hambre con precisión suficiente para escoger sin sonar exagerado." },
    canDo: [
      { en: "Compare two products and explain which one is better value", es: "Comparar dos productos y explicar cuál conviene más" },
      { en: "Say two places are equal or not equal for lunch", es: "Decir si dos lugares son iguales o no para almorzar" },
      { en: "Use strongest and most intense descriptions to choose food", es: "Usar descripciones máximas e intensas para escoger comida" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Place two imaginary fans at different prices. Students can point, choose and say why in any Spanish they have. Save más barato que until they need a fair comparison. Add one reason.", es: "Pon two fans imaginarios con precios distintos. Pueden señalar, escoger y justificar en inglés simple. Guarda cheaper than hasta que necesiten comparar de verdad. Añade una razón breve." },
      presentation: { en: "Write este ventilador es más barato que aquel between the two fans. Underline que as the hinge. Then add peor and mejor only after students decide that price is not the whole choice.", es: "Escribe this fan is cheaper than that one entre los dos ventiladores. Subraya -er than. Después añade better y worse cuando vean que el precio no decide todo." },
      practice: { en: "Work with paired cards for fan, lunch spot and sancocho bowl. One stack takes \"más barato que\" for inequality; another takes tan como for equality. Save the top-degree cards for last. Keep \"más barato que aquel\" visible.", es: "Comparan pares de tarjetas: fan, café y food stall. Unas exigen cheaper than o better than; otras as good as. Los superlatives aparecen solo al final. Comparan otra vez." },
      production: { en: "Turn the class into a Valledupar food stall. The seller claims el más sabroso; buyers compare price, size and smell before choosing. They must justify the biggest or best option. Make barato necessary in the scene.", es: "Convierte la clase en un puesto de comida. El vendedor anuncia the tastiest food; los clientes comparan price, size y smell antes de escoger. Deben justificar biggest, best o cheapest. La escena debe necesitar \"cheaper\"." },
      exitTicket: { en: "Give the broken phrase más barato de aquel. Students repair it to más barato que aquel and write one fresh noun. This checks the hinge, not the whole comparison system.", es: "Da more cheap than. Deben cambiarlo a cheaper than y escribir un sustantivo nuevo. Esta salida revisa la forma corta, no todo el sistema." },
      homework: { en: "Students compare two real places to eat or study. One sentence must use más que, one tan como and one el mejor or la mejor, each with a reason. Bring barato back next class.", es: "Comparan dos lugares reales para comer o estudiar. Una frase usa cheaper than, otra as good as y otra the best, cada una con una razón." },
      support: { en: "If comparison piles up, use only two fan cards. The student says A es más barato que B, then swaps cards. Do not add tan como until inequality is automatic.", es: "Si se amontonan las formas, usa solo two fan cards. El estudiante dice cheaper than y cambia las tarjetas. No añadas as good as hasta que esa comparación salga sola." },
      stretch: { en: "Fast students become skeptical buyers. They challenge el mejor with two comparisons and one equality claim, then decide whether the seller convinced them. Push barato into a new register.", es: "Los rápidos hacen de compradores escépticos. Cuestionan the best con dos comparaciones y una frase de igualdad, y deciden si el vendedor los convenció. Lleva \"cheaper\" a otro tono." },
      errors: [
        { en: "They write \"más barato de aquel\" because de feels comparative. Put \"más barato que aquel\" on the board; que is the hinge for inequality.", es: "Dicen \"more cheap than.\" Tacha more y escribe \"cheaper than\". Los adjetivos cortos suelen tomar -er; more queda para palabras más largas." },
        { en: "They say \"el más mejor\" at the food stall. Keep either \"el mejor\" or \"el más sabroso\"; mejor already carries the comparison.", es: "Dicen \"the most biggest bowl.\" Pon \"the biggest bowl\" al lado. Biggest ya lleva el grado máximo, así que most sobra." }
      ]
    }
  },
  "70-calendar-color-and-feeling": {
    mission: { en: "Set dates, describe what you are buying and say how you feel without translating word for word.", es: "Fijar fechas, describir lo que compras y decir cómo te sientes sin traducir palabra por palabra." },
    canDo: [
      { en: "Book a visit using exact calendar dates and days", es: "Reservar una visita usando fechas y días exactos" },
      { en: "Describe color, material and pattern while shopping", es: "Describir color, material y diseño al comprar" },
      { en: "Name temporary feelings and physical states before changing plans", es: "Nombrar estados y sensaciones temporales antes de cambiar planes" }
    ],
    teaching: {
      minutes: 60,
      warmUp: { en: "Draw a calendar square, a ruana and a bored face. Students label what they can. The spread tells you whether to spend the first minutes on dates, adjectives or states. Hold junio until students ask for it.", es: "Dibuja calendar square, ruana y bored face. Etiquetan lo que puedan. La distribución te dice si empezar por dates, color adjectives o feelings. Guarda \"first\" hasta que lo pidan. Añade una pregunta breve." },
      presentation: { en: "Start with el primero de junio because date order is visible. Put lunes 5 de mayo underneath, then move to ruana verde only after the class has handled fixed calendar phrasing. Point to order.", es: "Empieza con the first of June porque el orden se ve. Debajo escribe Monday the fifth of May. Pasa a green ruana solo cuando la fecha formal ya esté clara." },
      practice: { en: "Run three short desks: booking call, textile shop, Sunday mood. Students say one exact line at each desk: a date, a color-material description and an estar feeling. Let junio carry the drill. Rotate after success.", es: "Haz tres mesas breves: booking call, textile shop y Sunday mood. En cada una dicen una línea exacta: date, color before noun y feeling with be. La práctica gira en \"first\"." },
      production: { en: "Stage the Cocora suggestion. One person is bored, another is angry from work, and both need a jacket decision. Students must use temporary states to change the plan. Make junio necessary in the scene. Keep feelings temporary.", es: "Representa la invitación a caminar. Una persona is bored, otra is angry y necesitan jacket. Deben usar I'm cold, I'm embarrassed y I'm happy para ajustar el plan. La escena debe necesitar \"first\"." },
      exitTicket: { en: "Ask students to fix soy aburrida in the Cocora line. They write estoy aburrida and explain whether the sentence describes Cami or her Sunday state. Check junio, not a list.", es: "Pide corregir I have cold. Escriben I'm cold y dicen si cold describe un objeto o el estado del cuerpo. La respuesta decide si be quedó claro. Revisa \"first\", no una lista." },
      homework: { en: "Students write a three-part weekend note: one exact date, one clothing description with color, and one feeling that could change before the weekend arrives. Bring junio back next class.", es: "Escriben una nota de fin de semana con tres partes: exact date, clothing description y one feeling that can change. Debe sonar como plan, no lista. Traen \"first\" de vuelta." },
      support: { en: "For support, give three cards only: date, color, feeling. The student chooses the card before speaking. If they choose feeling, require estar; if color, make the noun agree. Make junio the small rescue.", es: "Para apoyo, da tres tarjetas: date, color y feeling. El estudiante elige antes de hablar. Con date usa ordinal; con feeling usa be; con color pone adjective before noun. Haz de \"first\" el rescate." },
      stretch: { en: "Early finishers take a shop complaint: the gray backpack is leather, the pink purse is fabric, and the color requested is unavailable. They must describe alternatives politely. Push junio into a new register.", es: "Los rápidos hacen una queja de tienda: gray backpack, pink purse y material equivocado. Deben ofrecer alternativas con color before noun y leather or fabric sin sonar secos. Lleva \"first\" a otro tono." },
      errors: [
        { en: "They say \"junio primero\" after English date order. Write \"el primero de junio\" and make them circle de; Spanish names the day, then the month.", es: "Dicen \"June first\" cuando el modelo usa \"the first of June.\" Acepta ambas, luego practica the con el ordinal para esta forma más cuidada de fecha." },
        { en: "They write \"soy aburrida\" when Cami is stuck at home. Change it to \"estoy aburrida\"; ser aburrida would describe her as a boring person.", es: "Dicen \"I have cold.\" Pon \"I'm cold\" junto a \"tengo frío\". El inglés usa be para ese estado del cuerpo, no have." }
      ]
    }
  },
  "71-past-time-and-duration": {
    mission: { en: "Order past events and durations clearly, from what you have tried to what had already happened and how long it lasted.", es: "Ordenar hechos pasados y duraciones, desde lo que has tried hasta lo que had already happened y cuánto duró." },
    canDo: [
      { en: "Choose between present perfect and preterite when asking about food experience", es: "Escoger entre have tried y simple past al preguntar por experiencias de comida" },
      { en: "Place one past event before another with había and a participle", es: "Poner un hecho pasado antes de otro con had y past participle" },
      { en: "Say how long something has gone on and narrate a blackout with background and events", es: "Decir for, since y ago, y narrar un apagón con background y events" }
    ],
    teaching: {
      minutes: 75,
      warmUp: { en: "Lay four timeline strips on the floor: lunch, closed bridge, stone-carver interview, blackout. Students stand where the event happened and say what time words they already trust. Standing on the strips makes before and duration physical. Put he probado on the lunch strip.", es: "Pon cuatro líneas de tiempo en el piso: almuerzo, puente cerrado, tallador y apagón. Se ubican donde ocurrió el hecho y dicen qué time words ya manejan. Pararse en las tiras vuelve físicos before y duration." },
      presentation: { en: "Start with ¿ya ha probado hormigas? and ¿ya comió? from Bucaramanga. Ask why Colombian Spanish can choose the preterite where English still needs present result language. Colombian timing and English timing split at today.", es: "Empieza con Have you tried brisket yet? y Did you try it yesterday? Pregunta por qué English obliga a separar present result de finished past. El tiempo inglés se parte entre today y finished past." },
      practice: { en: "Use the Cúcuta bridge story as a sequencing puzzle. Learners place arrival after ya habían cerrado, then write one sentence for what had happened before another event. Arrival after closing is the order that matters.", es: "Usa el puente de Cúcuta como rompecabezas de orden. Ubican arrival después de had already closed y escriben qué había pasado antes de otro hecho. Arrival después de closing es el orden clave." },
      production: { en: "Interview the Barichara stone carver. One student asks how long, one answers with llevar, and one interrupts with a past event that changes the story order. The interruption must force a new place on the timeline.", es: "Entrevista al tallador de Barichara. Una persona pregunta how long, otra responde con for o since y otra interrumpe con un hecho pasado que cambia el orden. La interrupción exige nuevo lugar en la timeline." },
      exitTicket: { en: "Collect one blackout sentence that combines llovía with se fue la luz. It must show background first and the event second. Background first, event second is the proof.", es: "Recoge una oración del apagón con was raining y the lights went out. Debe mostrar background primero y event después. Background primero y event después son la prueba." },
      homework: { en: "Write a six-line story about arriving too late. Include what had already happened, what you did next, and how long the problem had been going on. Too late only works if earlier events are ordered. Use había pasado for the earlier event.", es: "Escribe una historia de seis líneas sobre llegar tarde. Incluye what had already happened, qué hiciste después y how long duraba el problema. Llegar tarde funciona solo si earlier events están ordenados." },
      support: { en: "For hace, desde, and llevar, use three colored strings: ago, starting point, duration until now. The learner places don Hernando on the right string before speaking. The string decides for, since, or ago before grammar starts.", es: "Para for, since y ago, usa tres cuerdas de colores: duration, starting point y past point. El estudiante ubica al tallador antes de hablar. La cuerda decide for, since o ago antes de la gramática." },
      stretch: { en: "Ask advanced learners to retell the wedding blackout from two witnesses. They must change one background detail without changing the sequence of events. Changing background must not change event order.", es: "Pide a los avanzados contar el apagón desde dos testigos. Cambian un detalle de background sin alterar la secuencia de events. Cambiar background no cambia event order. Usa past continuous para el fondo." },
      errors: [
        { en: "They write \"He comido ayer en Bucaramanga\". Replace it with \"Comí ayer en Bucaramanga\". With a finished yesterday in Colombian Spanish, use the preterite, not he comido.", es: "Cuando alguien dice \"I ate already today\", no lo corrijas con traducción. Pon \"I have already eaten today\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Cuando llegué, cerraron ya\". Replace it with \"Cuando llegué, ya habían cerrado\". Use habían cerrado to show the closing happened before the arrival.", es: "Si aparece \"I live here since three years\", detén la ronda y escribe \"I have lived here for three years\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "72-reporting-and-perspective": {
    mission: { en: "Report what someone said, imagine a different present, and describe what was built without always naming the actor.", es: "Reportar lo que alguien said, imaginar un presente distinto y describir what was built sin nombrar siempre al actor." },
    canDo: [
      { en: "Relay a message and keep the speaker, time, and request clear", es: "Relatar un mensaje con said that, asked if y asked someone to" },
      { en: "Describe what you would do if the resources existed now", es: "Decir qué would do si los recursos existieran ahora" },
      { en: "Report public works with passive or impersonal language when the actor matters less", es: "Reportar public works con was built, got built o by the agent cuando convenga" }
    ],
    teaching: {
      minutes: 70,
      warmUp: { en: "Put a closed envelope from Profe Yolanda on the desk. Students predict what a front-desk worker must pass on: absence, class change, request, or reason. The envelope creates a reason to report, not gossip.", es: "Pon un sobre cerrado de Profe Yolanda en el escritorio. Predicen qué debe relay la recepción: absence, class change, request o reason. El sobre crea razón para reportar, no chisme." },
      presentation: { en: "Open the message with me dijo que hoy no venía. Show dijo que and preguntó si as report frames, then ask what happens to today inside the report. Today changes because the speaker is no longer speaking now.", es: "Abre el mensaje con told me she wasn’t coming. Muestra said that y asked if como marcos de reporte, luego pregunta qué pasa con today dentro del reporte. Today cambia porque la hablante ya no habla ahora." },
      practice: { en: "Give three salsa-academy slips: statement, yes-no question, request. Learners convert them into reported speech and choose dijo, preguntó, or pidió before writing. Statement, question, and request must enter different report frames. Sort the slips first.", es: "Entrega tres papeles de la academia: statement, yes-no question y request. Los convierten a reported speech y escogen said, asked if o asked someone to. Statement, question y request entran en marcos distintos." },
      production: { en: "Move to the Buenaventura lookout. Two friends dream about a boat they cannot buy, then the class decides which imagined plan is responsible and which is fantasy. The boat dream is responsible only if the condition is honest. Use si tuviera for the honest condition.", es: "Pasa al mirador de Buenaventura. Dos amigos sueñan con una lancha que no pueden comprar y la clase decide qué plan imaginado es responsable y cuál fantasía. Usa would aquí. El sueño del bote es responsable solo con condición honesta. Usa would para medir la fantasía." },
      exitTicket: { en: "Collect one passive public-works sentence: fue arreglado or was built. It must decide whether the builder matters enough to name. The passive is useful only when the builder may disappear.", es: "Recoge una oración pasiva sobre obras: was built o got built. Debe decidir si importa nombrar quién hizo la obra. Passive sirve cuando puede desaparecer el constructor." },
      homework: { en: "Write a front-desk note for the salsa academy and a two-line dream about the boat. Keep reported facts separate from hypothetical wishes. Facts and wishes must not share the same verb frame.", es: "Escribe una nota de recepción para la academia y un sueño de dos líneas sobre el bote. Separa reported facts de hypothetical wishes. Facts y wishes no comparten el mismo marco verbal." },
      support: { en: "If reported speech collapses, give three labels: statement, question, request. The learner sorts Yolanda’s words first, then chooses said, asked if, or asked us to. Sort Yolanda’s words before touching tense. Choose preguntó si after sorting the question.", es: "Si reported speech se cae, entrega tres etiquetas: statement, question, request. Ordenan las palabras de Yolanda primero y luego escogen said, asked if o asked us to. Ordena las palabras de Yolanda antes de tocar tense." },
      stretch: { en: "Ask fast finishers to rewrite the Quibdó update twice: once naming the contractor, once hiding the actor. They explain which version fits a community notice. Naming or hiding the contractor changes the community notice.", es: "Pide a los adelantados reescribir la noticia de Quibdó dos veces: con contractor y sin actor. Explican qué versión sirve para aviso comunitario. Usa passive aquí. Nombrar u ocultar contractor cambia el aviso comunitario. Usa passive cuando el actor desaparezca." },
      errors: [
        { en: "They write \"La profe dijo que hoy no viene\". Replace it with \"La profe dijo que hoy no venía\". When reporting a past message, move viene back to venía unless you are quoting directly.", es: "Cuando alguien dice \"Yolanda told me she is not coming today\", no lo corrijas con traducción. Pon \"Yolanda told me she wasn’t coming today\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Si tendría plata, compraría lancha\". Replace it with \"Si tuviera plata, compraría lancha\". Use imperfect subjunctive after si for the unreal present, not conditional on both sides.", es: "Si aparece \"If I would have the cash, I would buy a boat\", detén la ronda y escribe \"If I had the cash, I would buy a boat\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "73-aspect-regret-and-hope": {
    mission: { en: "Place arrival, regret, and promise on a timeline so a missed chance does not erase a credible deadline.", es: "Ubicar llegada, arrepentimiento y promesa en una línea de tiempo para que una oportunidad perdida no borre un plazo creíble." },
    canDo: [
      { en: "Say acabo de llegar for a just-finished arrival with visible evidence", es: "Decir acabo de llegar para una llegada recién terminada con evidencia visible" },
      { en: "Admit a missed chance with si hubiera sabido instead of si habría sabido", es: "Admitir una oportunidad perdida con si hubiera sabido en vez de si habría sabido" },
      { en: "Promise habré terminado by a museum deadline that someone can check", es: "Prometer habré terminado para un plazo de museo que alguien pueda verificar" }
    ],
    teaching: {
      minutes: 80,
      warmUp: { en: "Lay a hot coffee cup, arena ticket, river goodbye, and museum deadline on a timeline. Students decide what just happened, what is lost, and what can still be promised. Spanish checkpoint: acabo de llegar becomes useful before si hubiera sabido; students say why.", es: "Ponga tinto caliente, boleta, despedida y plazo de museo en línea de tiempo. En inglés deciden just happened, lost chance y future promise. Punto de control: \"I just got here\" sirve antes de \"If I had known\"; explican por qué." },
      presentation: { en: "Model acabo de llegar with the coffee still hot. Move the arena ticket backward for si hubiera sabido, then point ahead to the museum deadline for habré terminado. The board ends with acabo de llegar, si hubiera sabido, and one reason habré terminado belongs later.", es: "Modele I just got here con el tinto caliente. Mueva boleta al pasado para If I had known y señale plazo con will have finished. El tablero termina con \"I just got here\", \"If I had known\" y una razón para aplazar \"will have finished\"." },
      practice: { en: "Timeline cards must be placed before they are spoken. Regret traps with habría are repaired, and future-perfect promises need an actual deadline. Every answer cites the cue that forced acabo de llegar or blocked si hubiera sabido.", es: "Tarjetas de tiempo se colocan antes de decirse. Trampas con would se reparan y future perfect necesita plazo real. Cada respuesta cita la pista que exige \"I just got here\" o bloquea \"If I had known\"." },
      production: { en: "Hold a museum-team meeting after a missed arena event. The speaker admits regret with si hubiera sabido but still commits to finishing by a credible time. The final decision must include acabo de llegar and survive one objection.", es: "Haga reunión de museo tras evento perdido. La persona admite If I had known y aun así promete terminar en hora creíble. La decisión final debe incluir \"I just got here\" y resistir una objeción." },
      exitTicket: { en: "Time stance exit ticket: place the arena regret on the timeline, then correct \"si habría sabido\" to \"si hubiera sabido\". The last line promises a museum deadline.", es: "Time stance salida: ubican el arrepentimiento en la línea de tiempo y reparan \"If I would have known\" como \"If I had known\". La última frase promete un plazo de museo." },
      homework: { en: "Write a three-part reflection: arrival, regret, and promise. The promise must contain a time that another person could check. Students underline the Spanish form acabo de llegar where it carries the decision.", es: "Escriben en inglés reflexión de tres partes: arrival, regret y promise. La promesa incluye hora verificable por otra persona. Subrayan la forma inglesa \"I just got here\" donde sostiene la decisión." },
      support: { en: "Aspect is the difficulty: students know the words but put them on the wrong time shelf. Use shelves for acabo, si hubiera sabido, and habré terminado.", es: "La dificultad es aspecto: conocen palabras pero las ponen en estante temporal equivocado. Use repisas now, lost chance y deadline." },
      stretch: { en: "Add a colleague who doubts the museum deadline. Early finishers concede the earlier mistake and defend the new promise with evidence. The added challenge must still keep acabo de llegar accurate in context.", es: "Agregue colega que duda del plazo del museo. Quienes avanzan conceden el error y defienden la promesa con evidencia. El reto añadido conserva \"I just got here\" correcto dentro del contexto." },
      errors: [
        { en: "Time stance: they write \"si habría sabido\" because transfer overpowers the Time stance scene. Put \"si hubiera sabido\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Time stance: dicen \"If I would have known\" por transferencia del español en tiempo. Corrija a \"If I had known\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"acabo de llegar\" where this step needs \"si hubiera sabido\". Name the tiempo speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"I just got here\" cuando la escena necesita \"If I had known\". Nombre al hablante de tiempo, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "74-precision-and-concession": {
    mission: { en: "Make a precise council argument by identifying whose file it is, conceding rain, and stating the purpose of repair.", es: "Construir un argumento preciso de consejo identificando de quién es el archivo, concediendo la lluvia y declarando el propósito de la reparación." },
    canDo: [
      { en: "Use cuyo autor to identify the archive file without adding an extra pronoun", es: "Usar cuyo autor para identificar el archivo sin añadir un pronombre de más" },
      { en: "Keep a procession plan alive with aunque llueva", es: "Mantener vivo un plan de procesión con aunque llueva" },
      { en: "State the ceiling repair purpose with para que before asking for action", es: "Declarar el propósito de reparar la gotera con para que antes de pedir acción" }
    ],
    teaching: {
      minutes: 85,
      warmUp: { en: "Put an archive file, rain notice, procession route, and leaking-ceiling photo on the council table. Students identify source, concession, and purpose before grammar appears. Spanish checkpoint: cuyo autor becomes useful before aunque llueva; students say why.", es: "Ponga archivo, aviso de lluvia, ruta de procesión y gotera en mesa de consejo. En inglés identifican source, concession y purpose antes de gramática. Punto de control: \"whose author\" sirve antes de \"even if\"; explican por qué." },
      presentation: { en: "Teach cuyo autor from the file label so ownership is visible. Use aunque llueva for the procession decision and para que for the ceiling repair purpose. The board ends with cuyo autor, aunque llueva, and one reason para que belongs later.", es: "Enseñe whose author desde la etiqueta del archivo. Use even if para procesión con lluvia y so that para propósito de reparar gotera. El tablero termina con \"whose author\", \"even if\" y una razón para aplazar \"so that\"." },
      practice: { en: "Teams repair argument fragments. The archive sentence loses the extra que, the rain sentence keeps the plan alive, and the ceiling sentence must name its purpose. Every answer cites the cue that forced cuyo autor or blocked aunque llueva.", es: "Equipos reparan argumentos. La frase with whose pierde pronombre sobrante, even if no cancela plan y so that exige propósito. Cada respuesta cita la pista que exige \"whose author\" o bloquea \"even if\"." },
      production: { en: "Run a council debate about fixing the ceiling before the procession. Each side cites the file, concedes rain, and states the purpose of acting now. The final decision must include cuyo autor and survive one objection.", es: "Haga debate del consejo sobre gotera antes de procesión. Cada lado cita archivo, concede rain y declara purpose para actuar ahora. La decisión final debe incluir \"whose author\" y resistir una objeción." },
      exitTicket: { en: "The council slip changes \"el archivo que autor firmó\" to \"el archivo cuyo autor firmó\" and adds a purpose line with para que.", es: "La papeleta del consejo repara \"the file whose author signed it\" como \"the file whose author signed\" y agrega propósito con so that." },
      homework: { en: "Write a formal paragraph to the council using cuyo autor, one concession, and one purpose clause tied directly to the leak. Students underline the Spanish form cuyo autor where it carries the decision.", es: "Escriben en inglés párrafo formal al consejo con whose author, una concesión y una cláusula so that ligada a la gotera. Subrayan la forma inglesa \"whose author\" donde sostiene la decisión." },
      support: { en: "Students lose the relationship inside cuyo and add an extra pronoun. Draw one arrow from file to author; no second arrow is allowed.", es: "Pierden la relación en whose y añaden pronombre final. Dibuje una flecha file-to-author; no se permite segunda flecha con 'whose author'." },
      stretch: { en: "Add a late bus that weakens one plan. Strong groups acknowledge the delay and still defend the better purpose. The added challenge must still keep cuyo autor accurate in context.", es: "Agregue bus retrasado que debilita un plan. Grupos fuertes reconocen delay y defienden el propósito más sólido. El reto añadido conserva \"whose author\" correcto dentro del contexto." },
      errors: [
        { en: "Precise argument: they write \"el archivo que autor firmó\" because transfer overpowers the Precise argument scene. Put \"el archivo cuyo autor firmó\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Precise argument: dicen \"the file whose author signed it\" por transferencia del español en argumentos. Corrija a \"the file whose author signed\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"cuyo autor\" where this step needs \"aunque llueva\". Name the argumentos speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"whose author\" cuando la escena necesita \"even if\". Nombre al hablante de argumentos, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  },
  "75-obligation-and-belonging": {
    mission: { en: "Say what has to be done, whose things are whose and how to direct people without breaking trust.", es: "Decir qué toca hacer, de quién son las cosas y cómo dirigir a la gente sin romper la confianza." },
    canDo: [
      { en: "Explain impersonal obligations and personal assignments at work", es: "Explicar obligaciones impersonales y encargos personales en el trabajo" },
      { en: "Separate mixed-up objects by saying mine, yours and hers", es: "Separar objetos mezclados diciendo cuál es mío, tuyo y de ella" },
      { en: "Give a necessary instruction as a request that keeps respect", es: "Dar una instrucción necesaria como petición respetuosa" }
    ],
    teaching: {
      minutes: 65,
      warmUp: { en: "Put an inspection checklist, mixed containers and a shelter desk on the board. Students say who owns each task or object. Their uncertainty sets up hay que, mío and polite commands. Hold toca until students ask for it.", es: "Pon inspection checklist, mixed containers y shelter desk. Dicen quién owns cada tarea u objeto. La duda prepara have to, mine y Could you sin convertirlo en gramática suelta. Guarda \"must\" hasta que lo pidan." },
      presentation: { en: "Use the inspection first: hay que tener todo listo names a job with no owner. Add me toca when invoices get assigned. Then move to el mío only after objects are mixed on the table.", es: "Empieza con everything has to be ready para una obligación general. Añade The invoices are on you cuando aparece el dueño. Después pasa a mine cuando los objetos están mezclados. Ancla el tablero en \"must\"." },
      practice: { en: "Students sort task cards into nobody named, assigned to me and assigned to you. They choose hay que, me toca or te toca. A second round uses containers for el mío and la suya.", es: "Clasifican tareas en general, mine y yours. Escogen have to, be on me o be on you. En una segunda ronda separan container, keys y charger con mine, hers y ours. La práctica gira en \"must\"." },
      production: { en: "Run the Aguachica shelter desk. The coordinator needs IDs, signatures and receipts, but every command must preserve trust. Students turn siéntese and mándemelo into courteous requests when needed. Make toca necessary in the scene. Keep authority kind.", es: "Haz el shelter desk. La coordinadora necesita IDs, signatures y receipts, pero cada orden debe cuidar la relación. Convierten sit here y send it to me en Could you...? cuando haga falta. La escena debe necesitar \"must\"." },
      exitTicket: { en: "Give yo hay que entregar el informe. Students repair it to tengo que or me toca, then write one impersonal hay que sentence for the whole team.", es: "Da la frase mala \"I must to get up early\" en una tarjeta. Deben quitar to y luego escribir \"I have to get up\". Esta salida separa must de have to." },
      homework: { en: "Students photograph or list five mixed objects at home. They write two standalone possessives and one sentence about what has to be done before Monday. Bring toca back next class.", es: "Listan cinco objetos mezclados en casa. Escriben dos standalone possessives, como mine o hers, y una frase sobre what has to be done before Monday. Traen \"must\" de vuelta." },
      support: { en: "If obligation ownership blurs, use colored stickers. Red means no owner, blue means me, yellow means you. Students place stickers before choosing hay que, me toca or te toca.", es: "Si ownership se pierde, usa stickers de color. Rojo es no owner, azul me, amarillo you. Colocan el sticker antes de escoger have to, on me u on you. Haz de \"must\" el rescate." },
      stretch: { en: "Fast students rewrite three shelter orders for different power distances: neighbor, volunteer and older resident. They must keep the action clear while changing how direct the command sounds. Push toca into a new register.", es: "Los rápidos reescriben tres shelter requests para distinta distancia: neighbor, volunteer y older resident. Mantienen clara la acción, pero cambian entre imperative, Could you y Would you mind. Lleva \"must\" a otro tono." },
      errors: [
        { en: "They turn \"hay que\" into one person and say \"yo hay que entregar.\" Give them \"tengo que entregar\" for owned duty and keep \"hay que\" for the whole room.", es: "Dicen \"I must to get up early.\" Quita to después de must: \"I must get up early.\" Luego contrasta \"I have to get up,\" donde to sí pertenece." },
        { en: "They write \"el mío es mío\" for every object. Use the container: \"el mío tiene la tapa roja\"; the standalone possessive works because the noun is already known.", es: "Dicen \"the mine has the red lid.\" Tacha the; los posesivos independientes en inglés son mine, yours, hers y ours, no the mine." }
      ]
    }
  },
  "76-habits-and-checking": {
    mission: { en: "Describe habits that ended and check shared plans with short tags instead of asking the whole question again.", es: "Describir hábitos que se acabaron y confirmar planes compartidos con coletillas breves sin repetir toda la pregunta." },
    canDo: [
      { en: "Describe what a block used to be like and what people do not do anymore", es: "Describir cómo era una cuadra y qué ya no hace la gente" },
      { en: "Ask about past habits with used to and would without making them current", es: "Preguntar por hábitos pasados con used to y would sin volverlos actuales" },
      { en: "Confirm a plan with question tags, right, or Sound good at the right weight", es: "Confirmar un plan con question tags, right o Sound good en el peso correcto" }
    ],
    teaching: {
      minutes: 50,
      warmUp: { en: "Show a Bogotá corner with an old bakery sign and a closed shutter. Students list what people did before and what they do not do now. The shutter shows the habit is gone now. Use abría only for the vanished bakery.", es: "Muestra una esquina de Bogotá con aviso viejo de panadería y persiana cerrada. Enumeran what people used to do y what they do not do now. La persiana muestra que el hábito ya terminó." },
      presentation: { en: "Use antes abría temprano to paint the old routine. Then put ¿cierto? after the Barranquilla departure time and show that the second lesson checks agreement, not memory. The tag checks agreement; it does not ask the whole plan again.", es: "Usa used to open early para pintar la rutina vieja. Luego pon aren’t we? tras la hora de salida y muestra que la segunda lección confirma acuerdo. La question tag confirma; no repite todo el plan." },
      practice: { en: "Give two piles: old-neighborhood habits and trip-plan confirmations. Learners choose imperfect or ¿cierto? for Spanish, then explain why the piles cannot mix. Old habits and trip tags belong in separate piles. Keep the piles apart.", es: "Da dos grupos: hábitos antiguos y confirmaciones de viaje. Escogen used to o question tag en inglés y explican por qué los grupos no se mezclan. Old habits y trip tags van en montones separados." },
      production: { en: "Pair an older neighbor with a trip planner. First they recount what the block used to be; then they confirm Saturday details without asking the full question again. The partner must confirm, challenge, or correct the memory. Attach ¿cierto? to the Saturday plan.", es: "Empareja vecino mayor y organizador de viaje. Primero cuentan cómo era la cuadra; luego confirman los detalles del sábado sin repetir toda la pregunta. El compañero confirma, desafía o corrige la memoria." },
      exitTicket: { en: "Ask for one ended habit and one confirmation tag. The habit must be gone now; the tag must match the subject and auxiliary. The auxiliary in the tag must come from the sentence.", es: "Pide un hábito terminado y una question tag. El hábito ya no debe existir; la coletilla debe concordar con sujeto y auxiliar. El auxiliar del tag sale de la oración." },
      homework: { en: "Write four sentences about a place that changed. Add two trip details at the end and confirm them with short tags instead of new questions. Short tags should replace full second questions.", es: "Escribe cuatro frases sobre un lugar que cambió. Añade dos detalles de viaje al final y confírmalos con tags breves, no preguntas nuevas. Tags breves reemplazan segundas preguntas completas." },
      support: { en: "If used to sounds like use now, draw a big line through the old bakery. The learner says not anymore before trying the sentence again. Say not anymore before used to enters the sentence. Put ya no before soler.", es: "Si used to suena como use ahora, dibuja una raya sobre la panadería vieja. El estudiante dice not anymore antes de intentar la oración. Di not anymore antes de meter used to en la frase." },
      stretch: { en: "Ask advanced learners to make one nostalgic claim doubtful. A partner challenges it with a tag, and the speaker must correct the memory or defend it. The challenge should make memory negotiable, not hostile.", es: "Pide a los avanzados volver dudoso un recuerdo nostálgico. Un compañero lo desafía con tag y quien habla corrige o defiende la memoria. El desafío vuelve negociable la memoria, no hostil." },
      errors: [
        { en: "They write \"Antes la tienda abrió temprano todos los días\". Replace it with \"Antes la tienda abría temprano todos los días\". Use imperfect for the old habit. Preterite makes it sound like one finished opening.", es: "Cuando alguien dice \"The bakery would open, and it still does\", no lo corrijas con traducción. Pon \"The bakery used to open, but not anymore\" debajo, marca la pieza inglesa que falta y pide otra frase en contexto." },
        { en: "They write \"Salimos a las seis, ¿no?\". Replace it with \"Salimos a las seis, ¿cierto?\". Both can work, but ¿cierto? checks shared information more softly in this planning scene.", es: "Si aparece \"We leave Saturday, isn’t it?\", detén la ronda y escribe \"We’re leaving Saturday, aren’t we?\". Señala qué palabra española empujó el error y repite la línea con otro detalle." }
      ]
    }
  },
  "77-delegation-degree-and-doubt": {
    mission: { en: "Decide a risk case by separating work you did, work you had done, excessive degree, and doubt about a warning.", es: "Decidir un caso de riesgo separando trabajo hecho personalmente, trabajo mandado a hacer, grado excesivo y duda sobre una alerta." },
    canDo: [
      { en: "Say mandé a arreglar el techo when someone else did the repair", es: "Decir mandé a arreglar el techo cuando otra persona hizo la reparación" },
      { en: "Use tan lleno que to connect a crowded bar with a consequence", es: "Usar tan lleno que para conectar un bar lleno con una consecuencia" },
      { en: "State no creo que sea before voting on whether the road warning is credible", es: "Decir no creo que sea antes de votar si la alerta de vía es creíble" }
    ],
    teaching: {
      minutes: 85,
      warmUp: { en: "Open with a roof-repair invoice, crowded-bar photo, late order, and road warning. Students decide who did the work, how excessive the crowd is, and what they doubt. Spanish checkpoint: mandé a arreglar becomes useful before tan lleno que; students say why.", es: "Abra con factura de techo, foto de bar lleno, pedido tarde y alerta vial. En inglés deciden who did it, degree y doubt. Punto de control: \"had the roof repaired\" sirve antes de \"so packed that\"; explican por qué." },
      presentation: { en: "Contrast arreglé el techo with mandé a arreglar using the invoice. Move to tan lleno que for the bar, then no creo que sea for the road warning. The board ends with mandé a arreglar, tan lleno que, and one reason no creo que sea belongs later.", es: "Contraste I repaired con had the roof repaired mediante factura. Pase a so packed that en el bar y a I don't think it's para vía. El tablero termina con \"had the roof repaired\", \"so packed that\" y una razón para aplazar \"I don't think it's\"." },
      practice: { en: "Risk files go to three committees: delegated repair, excessive degree, and doubtful warning. Students cannot vote until the file's evidence matches the chosen form. Every answer cites the cue that forced mandé a arreglar or blocked tan lleno que.", es: "Archivos de riesgo van a tres comités: delegated repair, excessive degree y doubtful warning. No votan hasta emparejar evidencia y forma. Cada respuesta cita la pista que exige \"had the roof repaired\" o bloquea \"so packed that\"." },
      production: { en: "Run a risk-committee vote. The owner claims credit, the inspector questions the repair, and the group decides whether the road warning is credible enough to act on. The final decision must include mandé a arreglar and survive one objection.", es: "Haga votación de comité. Dueña reclama crédito, inspector cuestiona arreglo y grupo decide si road warning merece acción. La decisión final debe incluir \"had the roof repaired\" y resistir una objeción." },
      exitTicket: { en: "The committee form changes \"arreglé el techo\" to \"mandé a arreglar el techo\" and adds one doubt line with no creo que sea.", es: "El formulario del comité corrige \"I repaired the roof\" a \"I had the roof repaired\" y añade una duda con I don't think it's." },
      homework: { en: "Write the committee decision note. It must say who arranged the roof work, describe one excessive degree, and state one doubt that changes the vote. Students underline the Spanish form mandé a arreglar where it carries the decision.", es: "Escriben en inglés decisión del comité: who had work done, one excessive degree y una doubt que cambie el voto. Subrayan la forma inglesa \"had the roof repaired\" donde sostiene la decisión." },
      support: { en: "The core problem is agency. Give three responsibility cards: did it, paid someone, doubts it; students choose before using mandé a arreglar.", es: "El problema central es agencia. Dé tarjetas did it, paid someone, doubts it; eligen antes de usar had the roof repaired." },
      stretch: { en: "Add a contractor who admits only part of the roof was fixed. Advanced groups revise the vote and specify what evidence would remove doubt. The added challenge must still keep mandé a arreglar accurate in context.", es: "Agregue contratista que admite arreglo parcial. Grupos avanzados revisan voto y especifican qué evidencia quitaría la duda. El reto añadido conserva \"had the roof repaired\" correcto dentro del contexto." },
      errors: [
        { en: "Risk committee: they write \"arreglé el techo\" because transfer overpowers the Risk committee scene. Put \"mandé a arreglar el techo\" beside it, circle the changed word, and ask what object or relationship forces repair.", es: "Risk committee: dicen \"I repaired the roof\" por transferencia del español en riesgo. Corrija a \"I had the roof repaired\", encierre la palabra cambiada y pregunte qué objeto o relación obliga a reparar la frase." },
        { en: "They write \"mandé a arreglar\" where this step needs \"tan lleno que\". Name the riesgo speaker, return to the concrete scene, and make the student justify the repaired choice aloud.", es: "Otro error es decir \"had the roof repaired\" cuando la escena necesita \"so packed that\". Nombre al hablante de riesgo, vuelva a la escena concreta y haga justificar la forma reparada en voz alta." }
      ]
    }
  }
};

